window.D=window.D||{};D["mb_9"]={"226":[{"s":"<b>הרואה פרחי האילן מה מברך. ובו סעיף אחד:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>היוצא בימי ניסן וראה אילנות שמוציאין <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>פרח אומר בא\"י אמ\"ה שלא חיסר בעולמו כלום וברא בו בריות טובות ואילנות טובות ליהנות בהם בני אדם <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>ואינו מברך אלא פעם אחת בכל שנה ושנה ואם איחר לברך עד אחר שגדלו הפירות לא יברך עוד:","m":["(א) בימי ניסן - אורחא דמלתא נקט שאז דרך ארצות החמים ללבלב האילנות וה\"ה בחודש אחר כל שרואה הלבלוב פעם ראשון מברך [אחרונים]:","(ב) פרח - דוקא פרח הא עלים לחודיה לא ואף בפרח דוקא באילני מאכל שמזה הפרח עתיד להתגדל פרי אבל אילני סרק לא [אחרונים]:","(ג) אלא פעם אחת - מדסתם משמע דאפי' על אילנות אחרים לא יברך וכנ\"ל בסי' רכ\"ה ס\"י:","(ד) ואם איחר לברך וכו' - היינו אפילו לא ראה כלל מקודם אפ\"ה אבד הברכה כיון שגדלו הפירות כ\"מ בב\"י אבל בא\"ר הכריע לדינא דאם לא ראה מקודם לא אבד הברכה וכן משמע ג\"כ בביאור הגר\"א דאפילו כבר גדל הפרי לא אבד הברכה ומ\"מ אם כבר גדל הפרי ונגמר כל צרכו שראוי לברך עליה שהחיינו משמע מפמ\"ג וח\"א ששוב אין כדאי לברך ברכה זו:","(ה) עד אחר שגדלו - אבל קודם שגדלו הפירות יוכל לברך ואפילו לא בירך בשעת ראיה ראשונה [תשובת מהרי\"ל סי' קמ\"ג]:"]}],"227":[{"s":"<b>ברכת הזיקים. ובו ג סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>על הזיקים והוא כמין כוכב היורה כחץ באורך השמים ממקום למקום ונמשך אורו כשבט ועל רעדת הארץ ועל <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>הברקים ועל הרעמים <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>ועל רוחות שנשבו <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>בזעף על כל אחד מאלו אומר בא\"י אמ\"ה עושה מעשה בראשית <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ואם ירצה יאמר בא\"י אמ\"ה <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>שכחו וגבורתו מלא עולם:","m":["(א) היורה כחץ - וי\"א שהוא כוכב שיש לו זנב ושבט של אורה ושניהם העתיקו אחרונים לדינא ואם אותו כוכב עצמו שיש לו שבט רואהו עוד הפעם בלילה אחרת א\"צ לחזור ולברך כל שהוא עדיין בתוך למ\"ד יום לראיה ראשונה:","(ב) ממקום למקום - ולא יברך בלילה אחד רק פ\"א אפילו אם ראה כוכב אחר רץ באותו לילה:","(ג) הברקים - בליצי\"ן בל\"א. ואותן שהן באים בלא רעם כלל רק מחמת חום מצדד הח\"א שאין זה ברקים הנזכר בגמרא ואין מברכין עליהם:","(ד) שנשבו בזעף - ואם שלא בזעף אם הוא רוח גדול מברך עושה מעשה בראשית ולא יוכל לברך שכחו וגבורתו וכו' אחרי שהוא שלא בזעף גדול וטוב לברך תמיד על רוח סערה שאין מצויה רק ברכת עושה מעשה בראשית שבזה בודאי יוצא ממ\"נ כי אין אנו בקיאין כ\"כ מהו בזעף:","(ה) על כל אחד וכו' - והעולם נוהגים לברך על הברקים עושה מ\"ב ועל הרעמים שכחו וגבורתו וכו' וכן מסתבר שע\"י הרעם נראה גבורתו של הקב\"ה יותר מבברק אמנם באמת שייך כל אחת מהברכות על שניהם וע\"כ אם שמע ברק ורעם כאחד מברך ברכה אחת דהיינו עושה מע\"ב על שניהם ואם בירך שכחו וגבורתו מ\"ע ג\"כ יוצא. ואם לא היו תכופים זה אחר זה מברך תחלה על הברק [שהוא מתראה תחלה לעין האדם] עושה מע\"ב ואח\"כ על הרעם שכחו וגבורתו מ\"ע וה\"ה אם לא ראה את הברק ושמע קול הרעם ובירך עליו שכחו וגבורתו מ\"ע או שבירך עושה מע\"ב ואח\"כ ראה ברק מברך עליו ג\"כ עושה מע\"ב ועיין בשע\"ת שכתב בשם הברכ\"י דאם בירך על הברק ונתכוין לפטור הרעם הבא אחריו יצא בדיעבד ור\"ל דאחרי שטבע הבריאה שאחר הברק יוצא רעם א\"כ חל ברכתו על הרעם שיצא אח\"כ:","(ו) ואם ירצה וכו' - אבל לא יברך שתי ברכות כאחת אלא או זו או זו:","(ז) ברוך וכו' שכחו וגבורתו וכו' - ר\"ל ברוך הנותן כח להטבע להראות כח יוצר בראשית כדי שייראו מלפניו [א\"ר בשם אבודרהם]:","(ח) נתפזרו וכו' - ודוקא היכא דהשמים נטהרו וזכו לגמרי בין ברק לברק ואח\"כ נתקדרו השמים בעבים ושמע עוד קול רעם וברק צריך לברך מחדש עליהם דהוי מלתא חדתא אבל היכא שנתפזרו העבים ע\"י הרוח אחד הנה ואחד הנה ועדיין מעונן הרקיע אז נפטר הכל ע\"י ברכה הראשונה ואין צריך לחזור ולברך מחדש ומשמע בירושלמי דדוקא באותו יום אבל ביום אחר בכל גוונא צריך לחזור ולברך:","(ט) בבית הכסא - וה\"ה אם היה בבית שמקצבין בו בשר דשם ריח מעופש מאד או שהיה הולך במבואות המטונפות ויכול לזרז עצמו לצאת משם תיכף:"]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>כל זמן שלא נתפזרו העבים נפטר בברכה אחת נתפזרו בין ברק לברק ובין רעם לרעם צריך לחזור ולברך:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>היה יושב בבה\"כ ושמע קול רעם או ראה ברק אם יכול לצאת ולברך <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>תוך כדי דיבור <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>יצא ואם לאו לא יצא:","m":["(י) אם יכול וכו' - י\"א דאפילו אם נתעורר לעשות צרכיו מ\"מ כל זמן שאין מתאוה כ\"כ שיהא בו משום בל תשקצו יכול לצאת משם קודם שעשה צרכיו ולברך ויש מחמירין בזה. ובפרט היכי דמשער שישמע עוד קול רעם ויוכל לברך אח\"כ בודאי נכון להחמיר:","(יא) לצאת ולברך וכו' - והיינו היכא שלא עשה צרכיו ולא נגע בידיו במקום הטינופת [ואע\"ג דלעיל בסימן ד' מבואר דהיוצא מביה\"כ צריך ליטול ידיו אפילו לא עשה צרכיו מ\"מ הכא כדי שלא יפסיד הברכה אין צריך ליטול ידיו מקודם אם לא שהיו ידיו מטונפות] או שיכול ליטול ידיו במים או בשאר מידי דמנקי סמוך לשמיעתו דאל\"ה ודאי יתארך הזמן יותר מכדי דבור:","(יב) יצא - פי' ימהר לצאת משם כדי שלא יפסיד הברכה אבל אם יתארך יותר מכדי דבור דבלא\"ה כבר עבר הזמן א\"צ שוב למהר ומכל זה נשמע דשיעור הברכה שעל רעמים וברקים הוא דוקא בכדי דיבור ואם עבר יותר מכדי דבור מעת שראה הברק או שמע הרעם שוב לא יברך על רעם וברק זה. ומטעם זה היכא דעשה צרכיו ונטל ידיו ושמע קול רעם או ראה ברק יברך מתחלה על הרעם והברק ואח\"כ יאמר אשר יצר. ודע עוד דסתם ידים דהיינו שאינו יודע אם הם מלוכלכות כשרות לברכה [ס' ד' סכ\"ג]:"]}],"228":[{"s":"<b>ברכת ימים ונהרות הרים וגבעות. ובו ג סעיפים:</b><br><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>על <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>ימים ונהרות הרים וגבעות ומדבריות אומר ברוך אתה יי אמ\"ה עושה מעשה בראשית <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>ועל <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>הים <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>הגדול והוא הים שעוברים בו לארץ ישראל ולמצרים אומר <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>ברוך אתה ה' אלהינו מלך העולם עושה הים הגדול:","m":["(א) עושה מ\"ב - פי' כיון שיסדן מאז ושבחו של מקום הוא כשאנו מכירין היום דבר שאנו יודעין שהמקום בראו מששת ימי בראשית ועדיין הוא קיים ואין שייך לברך עליהם שכחו וגבורתו מלא עולם כמו על רוחות ורעמים דהתם הם נראים ונשמעים למרחוק אבל ימים ונהרות כל אחד במקומו:","(ב) והוא הים שעוברין וכו' - ונקרא ים הגדול מפני חשיבותו של א\"י אבל הרבה אחרונים פליגי על המחבר וס\"ל דדוקא על ים אוקינוס שהוא הים הגדול שבכל הימים שמקיף את כל העולם עליו קבעו ברכה בפני עצמו מפני גדלו אבל על ים שעוברין בו לא\"י לא נקרא לענין זה ים הגדול ומברכין עליו כמו על שאר ימים. ודע דכל הברכות האלו אינן אלא כשרואה אותן משלשים יום לשלשים יום [אחרונים]:","(ג) עושה הים הגדול - כן הוא לשון הטור אבל כמה פוסקים העתיקו נוסח ברכה זו בלשון עבר שעשה את הים הגדול:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>לא על כל הנהרות מברך אלא על ארבע נהרות דכתיבי בקרא <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>כמו חדקל ופרת <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>והוא שראה אותם במקום <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>שלא נשתנה <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>מהלכם ע\"י אדם:","m":["(ד) כמו חדקל ופרת - לאו דוקא אלו אלא ה\"ה כל הנהרות שהן גדולות כמו אלו הד' נהרות ושיהיו ידועים שהם מימי בראשית כמו אלו ולא נתהוו אח\"כ מברך:","(ה) במקום שלא נשתנה וכו' - פי' דבמקום שחפרו ושינו מהלכו של הנהר לדרך אחרת אין מברכין מאותו המקום והלאה דשם לאו מעשה בראשית הוא ועיין בא\"ר שמצדד לומר דאם ספק לו אם נשתנו ג\"כ לא יברך:","(ו) ע\"י אדם - וה\"ה לענין ימים אם המשיכו בני אדם מאחד לחבירו ועשוהו לאחד אין מברכין על אותו מקום אלא דבימים מן הסתם אין אנו צריכין לחוש לזה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>ולא על כל הרים וגבעות מברך אלא דוקא על הרים וגבעות המשונים וניכרת גבורת הבורא בהם:","m":[]}],"229":[{"s":"<b>ברכת הקשת וחמה בתקופתה. ובו ב סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>הרואה הקשת אומר ברוך אתה ה' אמ\"ה זוכר הברית <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>נאמן בבריתו וקיים במאמרו <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ואסור <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>להסתכל בו ביותר:","m":["(א) הרואה הקשת וכו' - ואין כדאי להגיד לחבירו שיש קשת מטעם מוציא דבה [ח\"א]:","(ב) אומר וכו' - ובכאן אם ראה אותו עוד הפעם אפילו בתוך למ\"ד יום חוזר ומברך ולא דמי לכל הנך דקי\"ל בהו דפעם אחת בחודש די לברוכי דכאן הקשת שבירך עליו חלף והלך לו ודמי לברכת רעמים [שע\"ת בשם ברכ\"י]:","(ג) נאמן וכו' - ברמב\"ם וטור הנוסח ונאמן:","(ד) בבריתו - ר\"ל שלא יעבירנו אע\"פ שרבו הרשעים וקיים במאמרו אפילו לא היה הברית כיון שאמר בדבור בעלמא ולא יהיה עוד מבול לשחת הארץ ברור הוא שיקיים מאמרו [אבודרהם]:","(ה) ואסור להסתכל וכו' - והמסתכל בו ביותר עיניו כהות [חגיגה ט\"ז] אלא רואהו ומברך:","(ו) בתקופתה - מקום שהיא חוזרת שם לתחלת הקיפה היא שעת תליית המאורות בעת הבריאה ומאז התחילה להקיף ולשמש והוא נמשך כ\"ח שנה עד שבא לאותו המקום בצמצום בתחלת ליל רביעי כבעת הבריאה:"]},{"s":"<i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>הרואה חמה בתקופתה <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>והוא מכ\"ח <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>לכ\"ח שנה והתקופה בתחלת ליל ד' כשרואה אותה ביום ד' <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"3\"></i>בבקר אומר ברוך עושה בראשית וכן מברך גם כן כשרואה לבנה בטהרתה וככבים במשמרותם ומזלות בעתם <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>דהיינו כשתחזור הלבנה בתחלת מזל טלה בתחלת החדש ולא תהיה נוטה לא לצפון ולא לדרום וכן כשיחזרו כל כוכב <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>מחמשה <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>הנשארים לתחלת מזל טלה ולא יהא נוטה לא לצפון ולא לדרום וכן בכל עת שיראה מזל טלה עולה מקצות המזרח:","m":["(ז) והתקופה - היינו תקופת ניסן:","(ח) בבוקר - היינו לכתחלה מצותה מיד להקדים מה דאפשר וטוב לברך אותה ברוב עם ובדיעבד עד ג' שעות על היום [לבוש ומ\"א] אבל הרבה אחרונים הסכימו דיוכל לברך בשעת הדחק עד חצות והיינו אפילו בשם ומלכות ואם נתכסה השמש בעבים ואין רואין אותה עיין בשע\"ת. ובתשובת חתם סופר סימן נ\"ו כתב דאם היתה מכוסה בעבים אך נראית רושמה מבין העבים מברכין אבל כשלא נתראה כלל לא נראה לברך. וע\"ש שכתב מנהגו בענין ברכה זו קודם הברכה אמרו הללו את ה' מן השמים ואחר ברכת עושה מעשה בראשית אמרו פיוט אל אדון על כל המעשים עד וחיות הקודש ואח\"כ מזמור השמים מספרים כבוד אל ואח\"כ עלינו לשבח וקדיש:","(ט) וכן מברך וכו' - וכהיום אין נוהגין העולם בזה:","(י) הנשארים - הם שבתי צדק מאדים נוגה כוכב:"]}],"230":[{"s":"<b>דין קצת ברכות פרטיות. ובו ה סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>המתפלל על מה שעבר כגון שנכנס לעיר ושמע קול צוחה בעיר ואמר יהי רצון שלא יהא קול זה בתוך ביתי או שהיתה אשתו מעוברת <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>אחר מ' יום לעיבורה ואמר יהי רצון שתלד אשתי זכר ה\"ז תפלת שוא <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>אלא יתפלל אדם על העתיד לבא ויתן הודאה על שעבר כגון הנכנס <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>לכרך אומר יהי רצון מלפניך ה' אלהינו שתכניסני לכרך הזה לשלום נכנס בשלום אומר מודה אני לפניך ה' אלהינו שהכנסתני לכרך הזה בשלום <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>בקש לצאת אומר יהי רצון מלפניך ה' אלהינו שתוציאני מכרך זה לשלום יצא בשלום אומר מודה אני לפניך ה' אלהי שהוצאתני מכרך זה לשלום וכשם שהוצאתני לשלום כן תוליכני לשלום וכו' עד בא\"י שומע תפלה <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>וזו היא <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>תפלת הדרך שנכתבה היא וכל דיניה <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>בסימן ק\"י:","m":["(א) אחר מ\"ם יום לעיבורה - שכבר נצטייר צורת הולד אבל תוך מ\"ם יום מועיל תפלה. ואפילו אחר מ\"ם יום יוכל להתפלל שיהיה הולד זרע קיימא ויהיה עוסק במצות ומע\"ט:","(ב) לכרך - דוקא לכרך דשם מצויים ממונים רעים ומחפשים עלילות אבל לעיר קטנה א\"צ לומר כשנכנס לה ולא אח\"כ כשיצא ממנה אלא אח\"כ כשמחזיק בדרך אומר תפלת הדרך משום סכנת דרכים וכמבואר לעיל בסימן ק\"י:","(ג) וזו היא תפלת הדרך וכו' - לכאורה הלא בסימן ק\"י מבואר דכשיוצא לדרך אומר תפלת הדרך לבד בלא הודאה על שעבר וגם אינו אומר אותה רק כשהחזיק בדרך ומהו זה שכולל הכא תה\"ד בהודאה שנותן על העבר וגם משמע שאומר אותה תיכף ביציאתו מן העיר י\"ל דהתם מיירי ביוצא מעיר קטנה שאין שם מורא כלל לצאת מן העיר וצ\"ל תה\"ד רק משום מורא הדרך ולכך אין לומר אותה רק כשהחזיק בדרך וכמ\"ש בס\"ק ב' ואפילו אם נזדמן אח\"כ בדרך נסיעתו שנוסע דרך כרך אין לומר כשיוצא ממנה רק ההודאה מודים וכו' עד לבסוף בלא חתימה כיון שאמר תה\"ד בתחלת נסיעתו והכא מיירי בנכנס לכרך ולן שם בענין שצ\"ל תה\"ד שנית בבוקר בשביל הדרך שרוצה לנסוע ומלבד זה הלא צריך ליתן הודאה ג\"כ על יציאת הכרך בזה אמר שיעשה משניהם אחד ויחתום בה ומיגו דצ\"ל ההודאה תיכף כשיוצא מן העיר אומר אז ג\"כ תה\"ד שכולל בה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>הנכנס למוד את גרנו אומר יהי רצון מלפניך ה' אלהי שתשלח ברכה בכרי הזה התחיל למוד אומר ברוך השולח ברכה בכרי הזה מדד ואח\"כ בירך ה\"ז תפלת שוא שאין הברכה מצויה אלא בדבר הסמוי <small> (פי' הנעלם ואינו נראה) </small> מן העין:","m":["(ד) ברוך השולח ברכה וכו' - וכתב הא\"ר דיאמר בלא הזכרת השם דדוקא במודד כדי לעשר מצינו שהבטיח הקב\"ה ברכה עד בלי די כמה דכתיב הביאו את כל המעשר וגו' ובחנוני נא בזאת וגו' והריקותי לכם ברכה עד בלי די:"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>הנכנס <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>למרחץ אומר יהר\"מ ה' אלהי שתכניסני לשלום ותוציאני לשלום ותצילני מהאור הזה וכיוצא בו לעתיד לבא יצא בשלום אומר מודה אני לפניך ה' אלהי שהצלתני מהאור הזה:","m":["(ה) הנכנס למרחץ וכו' - ועכשיו לא נהגו בתפלה זו והטעם דלא ניתקן אלא בימיהם שהיו מסיקין האש מלמטה בחפירה ורוחצים באמבטי מלמעלה ע\"ג תקרה שע\"ג ויש חשש פן תפחת ויפלו לתוכה אבל בזה\"ז עומד התנור בזוית וליכא סכנה [אחרונים]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>הנכנס <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>להקיז דם אומר יהר\"מ ה' אלהי שיהא עסק זה לי לרפואה כי רופא חנם אתה ולאחר שהקיז יאמר <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"•\" data-order=\"6\"></i>ברוך רופא חולים:","m":["(ו) להקיז דם - וה\"ה בכל מידי דרפואה יאמר זה ולא יחשוב שתהיה איזה דבר לו רפואה אלא ע\"י הבורא ית\"ש ולכן ע\"י תפלה זו ישים בטחונו בו ויבקש ממנו שתהיה לו לרפואה:","(ז) ברוך רופא חולים - וצריך לומר בשם ומלכות [ב\"י וט\"ז] אבל לא ראיתי נוהגין כן [פמ\"ג]. מי שמתעטש וחבירו אומר לו אסותא יאמר לו ברוך תהיה ואח\"כ יאמר לישועתך קויתי ה' [דארז\"ל דמתחלה לא היה אדם חולה כלל אלא היה הולך בשוק ומתעטש ומת עד שבא יעקב אבינו וביקש רחמים על הדבר]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"7\"></i>לעולם יהא אדם רגיל לומר כל מה דעביד רחמנא לטב עביד:","m":[]}],"231":[{"s":"<b>שכל כוונותיו יהיו לשם שמים. ובו סעיף אחד:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>אם אי אפשר לו ללמוד בלא שינת הצהרים יישן: <small>הגה <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>וכשנעור משנתו א\"צ לברך אלהי נשמה (ב\"י) ויש אומרים שיקרא קודם שישן <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>ויהי נועם (כל בו) </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>ובלבד שלא יאריך בה שאסור לישן ביום יותר משינת הסוס שהוא שתין נשמי <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ואף בזה המעט לא תהא כוונתו להנאת גופו אלא להחזיק גופו לעבודת הש\"י וכן בכל מה שיהנה בעוה\"ז לא יכוון להנאתו אלא לעבודת הבורא יתברך כדכתיב בכל דרכיך דעהו ואמרו חכמים כל מעשיך יהיו לש\"ש שאפילו דברים של רשות כגון האכילה והשתיה וההליכה והישיבה והקימה והתשמיש והשיחה וכל צרכי גופך יהיו כולם לעבודת בוראך או לדבר הגורם עבודתו שאפילו היה צמא ורעב אם אכל ושתה להנאתו אינו משובח אלא יתכוין שיאכל וישתה כפי חיותו לעבוד את בוראו וכן אפילו לישב <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>בסוד ישרים ולעמוד במקום צדיקים ולילך בעצת תמימים אם עשה להנאת עצמו והשלים חפצו ותאותו אינו משובח אלא א\"כ עשה לשם שמים וכן בשכיבה אין צריך לומר שבזמן שיכול לעסוק בתורה ובמצות לא יתגרה בשינה לענג עצמו אלא אפי' בזמן שהוא יגע וצריך לישן כדי לנוח מיגיעתו אם עשה להנאת גופו אינו משובח אלא יתכוין לתת שינה לעיניו ולגופו מנוחה לצורך הבריאות שלא תטרף דעתו בתורה מחמת מניעת השינה וכן בתשמיש אפילו בעונה האמורה בתורה אם עשה להשלים תאותו או להנאת גופו הרי זה מגונה ואפי' אם נתכוין כדי שיהיו לו בנים שישמשו אותו וימלאו מקומו אינו משובח אלא יתכוין שיהיו לו בנים לעבודת בוראו או שיתכוין לקיים מצות עונה כאדם הפורע חובו וכן בשיחה אפי' לספר בדברי חכמה צריך שתהיה כוונתו לעבודת הבורא או לדבר המביא לעבודתו כללו של דבר חייב אדם לשום עיניו ולבו על דרכיו ולשקול כל מעשיו במאזני שכלו וכשרואה דבר שיביא לידי עבודת הבורא ית' יעשהו ואם לאו לא יעשהו ומי שנוהג כן עובד את <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>בוראו תמיד:","m":["(א) אם א\"א לו וכו' - עיין לעיל בסימן ד' סט\"ז ובמשנה ברורה שם:","(ב) וכשניעור משנתו וכו' - אפשר הטעם דנתקנה ברכה זו על מנהגו של עולם שהקב\"ה מחזיר הנשמות לבני האדם בבוקר:","(ג) ויהי נועם - משום סכנת מזיקין. וכתב הלבוש שאין נוהגין כן:","(ד) יותר משינת הסוס וכו' - עיין לעיל בסימן ד' סט\"ז מש\"כ במ\"ב בשם המחה\"ש:","(ה) אלא יתכוין שיאכל וכו' - וראיתי לאנשי מעשה שקודם אכילה היו אומרים הנני רוצה לאכול ולשתות כדי שאהיה בריא וחזק לעבודת הש\"י [ח\"א]:","(ו) בסוד ישרים וכו' אינו משובח - ומ\"מ טוב הוא דמתוך כך בא לשמה:","(ז) יתכוין שיהיו לו בנים וכו' - ועיין עוד כונות אחרות בסימן ר\"מ ס\"א ואחר כונת הלב הן הדברים ורחמנא לבא בעי:","(ח) אפילו לספר בדברי חכמה - וכ\"ש אם סיפורו הוא בעניני משא ומתן צריך שתהיה כונתו לשם מצוה דהיינו שיהיה לו במה להתפרנס כדי שלא יבוא ליד גזל. ואפילו אם הוא עשיר גדול שדי לו בממונו לפרנס עצמו וב\"ב כל ימי חייו ג\"כ יצוייר לפעמים במה שמשתדל להרבות עסקיו דבר מצוה כגון שכונתו להרבות בצדקה וגמ\"ח עי\"ז או שכונתו ליקח עסקים תחת רשותו כדי להמציא מלאכה לעניי ישראל שישתכרו להחיות נפשם שכל זה הוא בכלל צדקה ומעולה ממנה כמו שכתב הרמב\"ם ומובא ביו\"ד סימן רנ\"א וע\"ש שהמחזיק ביד ישראל שמך ונותן לו מלאכה כדי שישתכר ולא יצטרך לבריות לשאול הוא מקיים בזה המ\"ע דומטה ידו עמך והחזקת בו:"]}],"232":[{"s":"<b>דברים האסורים בשעת המנחה. ובו ג סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>אם השעה דחוקה <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>יתפללו בלחש ואח\"כ יאמר ש\"ץ מגן ומחיה ויענה קדושה ומסיים האל הקדוש אם אין שהות ביום לגמור י\"ח ברכות: <small>הגה <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>וי\"א שמתפלל <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>השליח צבור עם הקהל <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>בקול <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>רם וכן נוהגים וע\"ל סי' קכ\"ד סעיף ב':</small>","m":["(א) דחוקה - דהיינו שאין שהות ביום שיתפללו מתחלה הצבור בלחש ואח\"כ גם חזרת הש\"ץ כראוי:","(ב) יתפללו בלחש - היינו שלא יסמכו הצבור מפני הדחק לצאת רק בתפלת הש\"ץ שיתפלל בקול רם דעיקר תפלה בלחש הוא ורק הש\"ץ יקצר בתפלתו שבקול ולא יאמר כ\"א ג' ראשונות להוציאן ידי חובתן בקדושה:","(ג) ביום - עיין לקמן בסימן רל\"ג ס\"א בהג\"ה מתי נגמר היום לענין תפלת המנחה ועיין במ\"ב שם:","(ד) הש\"ץ עם הקהל - היינו שהש\"ץ אומר מיד בקול רם והקהל יאמר עמו בלחש מלה במלה עד לאחר האל הקדוש וטוב שיהיה עכ\"פ אחד שיענה אמן על ברכת הש\"ץ [רמ\"א לעיל בסימן קכ\"ד ס\"ב ועיין במ\"ב מש\"כ שם]:"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"1\"></i> <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>לא ישב אדם <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>להסתפר <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>סמוך <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>למנחה עד שיתפלל ולא יכנס <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>למרחץ ולא <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>לבורסקי <small> (מקום שמעבדין שם העורות) </small> <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>ולא לדין ולא לאכול <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>אפי' <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>סעודה קטנה סמוך למנחה גדולה <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i><i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>ואם <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>התחיל באחת מכל אלו אינו מפסיק אף ע\"פ שהתחיל באיסור <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>והוא שיהא שהות ביום להתפלל אחר שיגמור סעודתו או מלאכתו אבל <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>אם אין שהות להתפלל אחר כך צריך <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>להפסיק מיד <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>ומאימתי התחלת תספורת משיניח סודר של ספרים על ברכיו והתחלת מרחץ משיפשוט לבושו העליון והתחלת בורסקי משיקשור בגד בין כתפיו כדרך הבורסקים והתחלת דין אם היו עסוקים בו משיתחילו בעלי דינין לטעון ואם לא היו עסוקים בו משיתעטפו הדיינים <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>ולדידן משישבו אדעתא לדון והתחלת אכילה <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>משיטול <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>ידיו: <small>הגה <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>ויש חולקים וסבירא להו <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i>דסעודה קטנה מותר ואינו אסור רק בסעודת נשואין או מילה (טור בשם רבינו תם) <i data-commentator=\"Magen Avraham\" data-order=\"14\"></i>וי\"א דאפי' סעודה גדולה סמוך למנחה גדולה שרי (בעל המאור והגהות מרדכי פ\"ק דשבת) <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"3\"></i>וי\"א דסעודה קטנה אפילו סמוך למנחה קטנה שרי (טור בשם ר\"י) ונהגו להקל כשתי הסברות דהיינו בסעודה גדולה סמוך למנחה גדולה ובסעודה קטנה <i data-commentator=\"Magen Avraham\" data-order=\"15\"></i>סמוך למנחה קטנה ואפשר הטעם משום דעכשיו קוראין לבה\"כ לא חיישינן דלמא יפשע ולא יתפלל (אגודה פ\"ק דשבת) (וע\"ל סי' פ\"ט) מיהו בסעודה גדולה יש להחמיר אפי' סמוך למנחה גדולה ואפי' אם התחיל קודם לכן כשמגיע מנחה קטנה <i data-commentator=\"Magen Avraham\" data-order=\"16\"></i><i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>והשעה <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>עוברת צריך לקום ולהתפלל (טור ובית יוסף בשם הפוסקים):</small>","m":["(ה) לא ישב אדם וכו' - הנה מפני שבסעיף זה יש בו פרטים רבים לכן מוכרח אנכי להאריך קצת. הנה כל זה הסעיף לענין אכילה וכן לענין להסתפר וליכנס למרחץ ושאר דברים הנזכרים פה הוא משנה בפ\"ק דשבת דאסור סמוך למנחה ולא ביארה המשנה איזה מנחה אי מנחה גדולה [דהיא משש שעות ומחצה ולמעלה וסמוך לה הוא חצי שעה קודם דהיינו תיכף אחר חצות היום] או מנחה קטנה [דהוא מתשע שעות ומחצה ולמעלה וסמוך לזה היינו מתחלת שעה עשירית] גם לא ביארה המשנה מה דאסרה לענין אכילה אי דוקא לסעודה גדולה דהיינו סעודת נישואין וכה\"ג אז אסור שמא יעבור זמן המנחה או אפילו סעודה קטנה כסעודת כל אדם אסור דלמא אתי לאמשוכי [וכן כה\"ג יש להסתפק בשאר דברים המוזכרים במשנה דהיינו שאסור ליכנס למרחץ אי דוקא לכולא מלתא דמרחץ דהיינו לחוף ראשו ולהשתטף בחמין וצונן ולהזיע או אפילו להזיע בעלמא אסור שמא יתעלף מחמת חום המרחץ וכן לענין בורסקי אי דוקא לבורסקי גדולה או אפי' לעיוני בעלמא וכה\"ג בשארי דברים כאשר מוזכרים בזה הסעיף] ויש שם בגמרא שני תירוצים ולתרוייהו איירי המשנה במנחה גדולה תירוץ קמא דכונת המשנה שאסרה סמוך למנחה גדולה איירי דוקא בסעודה גדולה [הא סעודה קטנה מותר להתחיל עד זמן סמוך למנחה קטנה. ויש שמקילין עוד לתירוץ זה דאפילו סמוך למנחה קטנה ג\"כ מותר להתחיל סעודה קטנה] ותירוץ בתרא דכונת המשנה לאסור אפילו סעודה קטנה סמוך למנחה גדולה ונחלקו הפוסקים בזה הרי\"ף והרמב\"ם פסקו כתירוצא בתרא וזהו שסתם המחבר כמותם והרמ\"א בריש דבריו פסק כתירוצא קמא זהו תורף הענין שבסעיף זה ועתה נתחיל לבאר את דברי הסעיף:","(ו) להסתפר סמוך למנחה - האי סמוך למנחה היינו סמוך למנחה גדולה כאשר כתב המחבר בסוף דבריו ואכולהו קאי ואף שעד סוף זמן המנחה יש שהות הרבה אפ\"ה חיישינן שמא ישבר הזוג ויחזר אחר אחרת ויעבור המנחה ואפשר שאם יש לו ב' או ג' זוגים מוכנים לפניו שרי. כשמגיע זמן המנחה נכון שלא יקח ילד בחיקו דשמא יטנף בגדיו ובעוד שיחזר אחר מים יעבור מנחה או יתאחר לבוא לבהכ\"נ [ס\"ח סימן י\"ח]:","(ז) סמוך למנחה - היינו חצי שעה קודם דהוא תחלת שעה שביעית שהוא מחצי היום ומעלה ואין חילוק בין היום ארוך או קצר לעולם חשבינן לדעה זו סמוך למנחה אחר חצי היום:","(ח) למרחץ - אפילו להזיע בעלמא וכ\"ש לכולא מלתא דמרחץ:","(ט) לבורסקי - אפילו לעיוני בעלמא שמא יראה שנתקלקלו העורות ויצטער ויהיה טרוד בצערו ולא יתפלל [רש\"י] ומשמע דהוא הדין לכל מלאכה או חשבון כיוצא בו שאפשר להמשך או לגרום טרדא [ועיין בבה\"ל] ולכן אותם היוצאים לירידים שטרודים בקניית ומכירת סחורה לא יתחילו לכתחלה סמוך לזמן מנחה גדולה עד שיתפללו מקודם [ח\"א]:","(י) ולא לדין - אפילו שמעו טענותיהם מכבר ועתה ראו לישב בשביל גמר דין אסור שמא יראו טעם ויסתרו הדין וימשך הענין:","(יא) סעודה קטנה - היינו סעודת כל אדם [וסעודה גדולה הוא של נישואין ומילה] והטעם דחיישינן שמא ימשך. ודין איסור אכילה או מלאכה קודם מעריב יתבאר בסימן רל\"ה ס\"ב. ולענין להתחיל ללמוד קודם תפלת המנחה ע' לעיל בסי' פ\"ט ס\"ו לענין לימוד קודם תפלת שחרית וה\"ה הכא כשמגיע זמן מנחה קטנה:","(יב) סמוך למנחה גדולה - עיין לעיל בסק\"ז במ\"ב:","(יג) ואם התחיל וכו' - אפילו התחיל אחר שהגיע כבר זמן מנחה גדולה ואפילו אחר כך כל שלא הגיע עדיין החצי שעה שקודם מנחה קטנה [דאלו כשהתחיל בזו החצי שעה מפסיק כשיגיע זמן מנחה קטנה ואף שיש שהות הרבה עדיין עד הערב דעיקר זמן מנחה הוא ממנחה קטנה ולמעלה ועיין לקמן בהג\"ה מה שעכשיו נוהגין להקל]:","(יד) באחת מכל אלו - היינו אפילו התחיל סעודה גדולה או שנכנס לבורסקי גדולה וכה\"ג בשארי דברים כאשר הזכרנו בפתיחה דבודאי יש לחוש בהו שמא ימשך הרבה אפ\"ה אינו מפסיק כיון שיש שהות להתפלל אחר שיגמור סעודתו או מלאכתו:","(טו) אם אין שהות - אפילו התחיל בהיתר מפסיק:","(טז) להפסיק מיד - היינו אפילו עוד היום גדול כל שיודע שתמשך סעודתו או מלאכתו עד שתחשך צריך להפסיק מיד שמא ישכח ויעבור הזמן לגמרי:","(יז) ומאימתי התחלת וכו' - קאי אמה שכתב לעיל ואם התחיל וכו':","(יח) אם היו עסוקים - פי' שכבר ישבו בדינין אחרים:","(יט) משיתעטפו - שכך היו נוהגים מלפנים כשיושבין בדין משום ששכינה שורה עמהם [ב\"י]:","(כ) משיטול ידיו - ומי שרגיל להתיר איזורו בשעת אכילה מקרי התחלה מישתיר איזורו אף קודם נטילה:","(כא) דסעודה קטנה - ולדידהו תספורת דידן נמי שרי סמוך למנחה גדולה [ואינו אסור אלא תספורת של בן אלעשה שהיא מלאכה גדולה כמבואר בגמרא] ומרחץ דוקא כולא מילתא דמרחץ אסור אז אבל להזיע בעלמא שרי ובורסקי דוקא בורסקי גדולה ודין דוקא התחלת דין שצריך לזה שיהוי הרבה וחיישינן שמא יעבור עי\"ז הזמן אבל גמר דין שרי:","(כב) מותר - היינו סמוך למנחה גדולה ואחר מכן עד סמוך למנחה קטנה אבל סמוך למנחה קטנה שהוא מתחלת שעה עשירית ולמעלה גם לדידהו אסור בכל אלה ואפילו בדיעבד אם התחילו אז מפסיקין כשיגיע הזמן דמנחה קטנה:","(כג) ואינו אסור וכו' - היינו דלידידהו אינו אסור להתחיל סמוך למנחה גדולה אלא סעודה גדולה דבדידהו דוקא שצריך שיהוי רב ע\"כ חיישינן שמא ימשך הרבה עד שיעבור הזמן:","(כד) נישואין או מילה - וה\"ה פדיון הבן שיש שם הרבה בני אדם מסובין יחד ועי\"ז רגיל הדבר להמשך וסעודת שבת ויו\"ט לא מקרי סעודה גדולה [ב\"י]:","(כה) וי\"א וכו' וי\"א וכו' - שתי אלו הדעות מקילין יותר מדעות הקודמות דלדידהו רק באופן אחד אסור ונחלקין זה מזה דלי\"א הראשון רק סמוך למנחה קטנה אסור ואפילו סעודה קטנה אבל סמוך למנחה גדולה שרי הכל וי\"א השני ס\"ל בהיפך דסעודה גדולה אסור אפילו סמוך למנחה גדולה וסעודה קטנה מותר אפילו סמוך למנחה קטנה:","(כו) אפילו סמוך למ\"ק וכו' - משמע דכשהגיע זמן מנחה קטנה מודה דאסור להתחיל ובהגהת מרדכי מיקל גם בזה ודעתו דאין איסור אלא בסעודה גדולה סמוך למ\"ק וכן משמע במהרי\"ו דנהגו העולם להקל אף לאחר שהגיע זמן מנחה קטנה:","(כז) ונהגו להקל כשתי וכו' - וכן העתיקו האחרונים:","(כח) משום דעכשיו וכו' - ומיירי שדרכו ג\"כ לילך להתפלל בצבור בבהכ\"נ אבל אם דרכו להתפלל ביחידות בביתו לא מהני [דה\"ח]:","(כט) לא חיישינן וכו' - אמנם מיד שקורין לבהכ\"נ צריך להפסיק ולהתפלל דאל\"ה מאי תקנתיה [שם]. ודע דדוקא סעודה קטנה סומכין על קריאת השמש לבהכ\"נ אבל סעודה גדולה אין סומכין על קריאה לבהכ\"נ להתיר להתחיל סמוך למ\"ק [דהיינו מט' שעות ולמעלה] משום דשכיחא שכרות. ומשמע מהאחרונים דלענין לילך למרחץ אפילו לכולא מלתא דמרחץ וכן לענין כל הדברים שמוזכר לעיל בסעיף זה סמכינן על קריאת השמש לבהכ\"נ כמו לענין סעודה קטנה. והנה לפ\"ז מותר לילך בע\"ש למרחץ אפילו כשהגיע זמן מנחה קטנה במקום שהשמש קורא לבהכ\"נ. אמנם אנשי מעשה נוהגין להתפלל מקודם שהולכין לבית המרחץ ויש שמדקדקין ליזהר להתפלל מקודם אפילו כשהולכין לבית המרחץ סמוך למנחה גדולה דהיינו אחר חצות כמו שמוזכר במעשה רב אמנם הנוהגין להקל בזה אין למחות בידן דיש להם על מה שיסמכו וכנ\"ל אבל כ\"ז דוקא אם השמש יכריז גם לאנשי בית המרחץ לצאת מבע\"י איזה זמן קודם השקיעה בכדי שיספיק להם העת אחר צאתם להתפלל בזמנה דאל\"ה לא נוכל לסמוך ע\"ז כלל:","(ל) יש להחמיר - היינו שלא לסמוך על קריאת השמש להתחיל אז הסעודה דשכיח שכרות ובשכרות לא מהני הקריאה ולפ\"ז כשיש חתונה בשבת ולא יצאו מבהכ\"נ עד אחר חצות יתפללו מנחה מקודם ואח\"כ יאכלו דסעודת נישואין הוי סעודה גדולה:","(לא) קודם לכן - דהיינו שהתחיל הסעודה גדולה קודם חצות דאז עדיין זמן היתר לכו\"ע:","(לב) כשמגיע וכו' והשעה עוברת - ר\"ל כיון שמשער שימשך סעודתו עד הלילה צריך לקום ולהתפלל תיכף כשיגיע זמן מנחה קטנה:","(לג) צריך לקום ולהתפלל - נראה דדוקא בסעודה גדולה ומשום דשכיחא שכרות דלא סמכינן על קריאת השמש לביהכ\"נ וכנ\"ל לכך פוסק מיד אבל בסעודה קטנה א\"צ לפסוק מיד דיוכל לסמוך [אפילו אם התחיל סעודתו אחר שהגיע זמן מנחה קטנה] דיפסוק מסעודתו כשיקרא השמש לביהכ\"נ:","(לד) מותר - אפילו כבר הגיע זמן מ\"ק ואפילו אם אוכל הרבה פירות דזה לא מקרי סעודה. ותבשיל העשוי מחמשת המינים ג\"כ מותר אם אינו קובע עלייהו [דה\"ח]:"]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>והא דאסור לאכול סעודה קטנה היינו כשקובע לסעודה אבל לטעום דהיינו אכילת פירות מותר <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>וה\"ה לאכול פת <i data-commentator=\"Magen Avraham\" data-order=\"17\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>כביצה כדרך שאדם אוכל בלא קבע מותר:","m":["(לה) כביצה - ולא יותר וכתב המ\"א דבשתיה יותר מכביצה נמי אסור אף דלענין אכילה חוץ לסוכה חשיב עראי אף ביותר מכביצה בזה דהחשש הוא שמא ימשך וזה שייך בשתיה יותר אם הוא משקה המשכר. וסתם משקה מותר לשתות אפילו הרבה:"]}],"233":[{"s":"<b>זמן תפלת המנחה. ובו ב סעיפים:</b><br><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>מי שהתפלל תפלת <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>המנחה לאחר שש שעות ומחצה <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>ולמעלה <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>יצא <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>ועיקר זמנה מט' שעות ומחצה ולמעלה <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>עד הלילה לרבנן ולרבי יהודה עד פלג המנחה שהוא עד סוף י\"א שעות חסר רביע: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>ומשערינן <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>שעות אלו לפי ענין היום ואף אם היום ארוך משערינן <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>לי\"ב שעות והם נקראים <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>שעות זמניות וכן כל מקום ששערו חכמים בשעות משערינן בשעות אלו (רמב\"ם בפי' המשנה בפ\"ק דברכות) </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ואסיקנא דעבד כמר עבד ודעבד כמר עבד והוא שיעשה <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>לעולם <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>כחד מינייהו שאם עושה כרבנן ומתפלל מנחה עד הלילה שוב אינו יכול להתפלל ערבית מפלג המנחה ולמעלה ואם עושה כר' יהודה ומתפלל ערבית מפלג המנחה ולמעלה צריך ליזהר שלא יתפלל מנחה באותה שעה <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>ועכשיו שנהגו להתפלל תפלת המנחה עד הלילה אין להתפלל תפלת ערבית קודם שקיעת החמה <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>ואם בדיעבד התפלל תפלת ערבית מפלג המנחה <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>ולמעלה יצא ובשעת הדחק יכול להתפלל תפלת ערבית מפלג המנחה ולמעלה: <small>הגה ולדידן במדינות אלו שנוהגין להתפלל ערבית מפלג המנחה אין לו להתפלל מנחה אחר כך ובדיעבד או בשעת הדחק יצא אם מתפלל מנחה עד הלילה <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>דהיינו <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>צאת הכוכבים: (ב\"י בשם אהל מועד ורשב\"א):</small>","m":["(א) שהתפלל וכו' - דתפלת המנחה כנגד תמיד של בין הערבים תקנוה וזמן שחיטתו מדאורייתא התחלתו אחר שש שעות ומחצה דהיינו חצי שעה אחר חצות היום ורק משום כדי שיהיו יכולין להקריב קרבנות יחיד מקודם [שאחר התמיד של בין הערבים אסור להקריב שום קרבן] לכן היו מאחרין הקרבתו בכל יום עד ט' שעות ומחצה לבד מערב פסח שחל להיות בע\"ש שהיו שוחטין התמיד בשש שעות ומחצה וע\"כ עיקר זמן תפלת המנחה לכתחלה הוא מט' ומחצה ולמעלה כנגד התמיד שהיו מקריבין בכל יום ומ\"מ אם התפלל משש ומחצה ולמעלה יצא אחרי דעיקר זמנו של תמיד מדאורייתא מתחיל מאותו זמן ויש מהראשונים שמקילין לכתחלה משש שעות ומחצה ולמעלה ועכ\"פ אם רוצה לאכול או לצאת לדרך או שעתה יוכל להתפלל עם הצבור ואם ימתין על מ\"ק לא יהיה לו מנין לכו\"ע מותר להתפלל לכתחלה משש שעות ומחצה ולמעלה:","(ב) ומחצה ולמעלה יצא - משמע דמקודם לכן לא יצא אפילו דיעבד [כ\"כ מ\"א ודה\"ח וברכ\"י] ויש מאחרונים דס\"ל דאף דלכתחלה אסור להתפלל קודם שנשלם החצי שעה שאחר חצות מ\"מ בדיעבד שהתפלל בזו החצי שעה לא יתפלל שנית. ודע דמש\"כ עד הלילה לרבנן לאו דוקא דהא לערך רבע שעה קודם צאת הכוכבים לכו\"ע בכלל בין השמשות הוא כדלקמן בסימן רס\"א ואין להתפלל מנחה אז ועיין לקמיה בהג\"ה שניה מה שכתבנו בענין זה למעשה:","(ג) שהוא עד סוף וכו' - שזמן מנחה קטנה הוא שתי שעות ומחצה [דהלא הוא מט' שעות ומחצה עד סוף י\"ב שעות] ונמצא דפלג המנחה הוא שעה שלמה ועוד רביע:","(ד) ומשערינן שעות אלו וכו' - היינו כל חשבון השעות הנ\"ל בין למנחה גדולה בין למנחה קטנה ופלג המנחה דחשבינן בשעות היום מחלקינן היום בין ארוך בין קצר לי\"ב חלקים וכל חלק נקרא שעה וע\"פ שעות אלו קבעינן זמן מנחה לכל הנ\"ל. ושיעור י\"ב שעות היום דמשערינן בו יש מחלוקת בין הפוסקים די\"א דחשבינן מעמוד השחר עד צאת הכוכבים וממילא לר' יהודה מותר להתפלל מנחה עד שעה ורביע קודם צה\"כ ולרבנן עד הלילה וכנ\"ל בסק\"ב וכך סתם המחבר בסימן זה ולקמן בסימן תמ\"ג וי\"א דחשבינן הי\"ב שעות מנץ החמה עד שקיעתה וממילא לר' יהודה אינו מותר להתפלל מנחה רק עד שעה ורביע קודם השקיעה ולרבנן עד השקיעה:","(ה) דעבד כמר וכו' - ויש לכל אחד משניהם קולא וחומרא היינו דלענין מנחה דעת ר' יהודה אינה אלא לחומרא דאין להתפלל מנחה רק עד פלג המנחה אבל ממילא יש קולא לענין מעריב דמשם ואילך נחשב כלילה לענין שיוכל להתפלל תפלת מעריב [היינו רק התפלה עצמה דאלו זמן ק\"ש של ערבית לכו\"ע בצאת הכוכבים הוא וכדלקמן בסימן רל\"ה] ולרבנן הוי קולא לענין תפלת המנחה דמתפללין עד הערב וממילא חומרא לענין תפלת הערב דאין להתפלל קודם חשיכה:","(ו) לעולם כחד - פ' שלא ינהוג פעם כך ופעם כך משום דהוה תרתי דסתרי אפילו למחר ומכ\"ש שלא יתפלל ביום אחד מנחה אחר פלג כרבנן וערבית קודם צה\"כ:","(ז) באותה שעה - אלא קודם פלג דוקא:","(ח) עד הלילה - ר\"ל עד ביה\"ש שהוא ספק לילה:","(ט) קודם שקיעת החמה - ר\"ל סוף שקיעה שהוא לדעת המחבר בסי' רס\"א זמן מועט קודם צאת הכוכבים ואע\"ג דגם אז אין להתפלל עד צאת הכוכבים ממש דמקודם לכן הוי רק ספק לילה וכדלקמן בסימן רל\"ה בהאי פורתא לא דק:","(י) ולמעלה יצא - אבל קודם פלג אפילו בדיעבד לא יצא ולעיל מתבאר דיש דעות בפוסקים אימת הוא פלג המנחה וע\"כ יש לסמוך להקל שלא לחזור ולהתפלל אף אם התפלל שעה ורביע קודם שקיעת החמה:","(יא) ובשעת הדחק וכו' - ר\"ל דאף אם דרכו תמיד להתפלל מנחה אחר פלג מ\"מ יכול להתפלל תפלת ערבית ג\"כ בזמן הזה ומ\"מ אין להקל בזה רק אם עכ\"פ באותו היום התפלל מנחה קודם פלג אבל אם באותו היום גופא התפלל מנחה אחר פלג שוב אסור לו להתפלל ערבית קודם הלילה דהוי תרתי דסתרי באותו יום גופא וכ\"ז אם מתפלל ביחידי אבל צבור שהתפללו מנחה וכשילכו לביתם יהיה טורח לקבצם שנית לתפלת ערב ויתבטל תפלת הצבור לגמרי הקילו האחרונים שמותר להתפלל ערבית סמוך למנחה ועיין לקמן בסימן רל\"ה ס\"א:","(יב) מנחה אחר כך - ר\"ל אפילו ביום אחר לא יתפלל מנחה אחר פלג כיון דתמיד מחזיק אותו זמן לזמן תפלת הערב אפילו אם בדעתו באותו היום להתפלל מעריב אחר צאת הכוכבים:","(יג) או בשעת הדחק וכו' - ר\"ל דכיון שהוא שעת הדחק מותר לו לכתחלה להתפלל מנחה בשעה שנהג עד היום להתפלל מעריב וכבר כתבתי בסקי\"א דיש לו ליזהר שלא להתפלל אז מעריב רק אחר צה\"כ אם לא שהוא בצבור ויהיה טורח לקבצם שנית כשילכו כ\"א לביתו:","(יד) דהיינו עד צאת הכוכבים - לאו דוקא דערך רבע שעה קודם צאת הכוכבים בודאי בין השמשות הוא לכו\"ע ואין להתפלל באותו זמן אלא ר\"ל סמוך לזה וכן אי' בד\"מ ברל\"ב. ודע דאף שמהמחבר והרמ\"א משמע דלדידן דנוהגים להתפלל מעריב אחר צה\"כ מותר להתפלל מנחה אפי' אחר שקיעה עד סמוך לצ\"ה יש פוסקים רבים שחולקים בזה ודעתם שתפלת המנחה הוא רק קודם שקיעת החמה ולכן לכתחלה צריך כל אדם ליזהר להתפלל קודם שקיעת החמה דוקא דהיינו שיגמור תפלתו בעוד שלא נתכסה השמש מעינינו ומוטב להתפלל בזמנה ביחידות מלהתפלל אח\"כ בצבור ובדיעבד יוכל לסמוך על דעת המקילים להתפלל אחר שקיעה עד רבע שעה קודם צה\"כ [אך כל מה שיכול להקדים מחוייב להקדים כדי שלא יכנס בספק בין השמשות אכן אם כבר נראו כוכבים כבר עבר זמן מנחה בודאי דזהו סימן ללילה כמבואר כ\"ז בסימן רצ\"ג ע\"ש במ\"ב ובה\"ל] אך כ\"ז בדיעבד ושעת הדחק גדול אבל לכתחלה בודאי אין לאחר זמן המנחה עד אחר שקיעה וכ\"ש שיש ליזהר מאד שלא לאחר עד סמוך לצאת הכוכבים וכבר אחז\"ל במערבא לייטי אמאן דמצלי עם דמדומי חמה דלמא מטרפא ליה שעתא:"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>אם יש לו מים צריך ליטול ידיו כדי להתפלל אע\"פ שאינו יודע להן שום לכלוך ולא יברך <small> (וע\"ל סי' צ\"ב סעיף ה') </small> <small>הגה ואפי' <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>עומד מלמודו יטול ידיו <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>לתפלה (מנהגים) </small> ואם אין לו מים מזומנים <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>אינו צריך ליטול:","m":["(טו) צריך ליטול וכו' - בין לתפילת המנחה בין לתפלת ערבית דמצוה ליטול ידיו לתפלה:","(טז) אע\"פ שאינו יודע וכו' - ואם נטל ידיו לתפלת המנחה ולא הסיח דעתו משמירתן אין צריך ליטול ידיו לתפלת ערבית:","(יז) ועיין לעיל וכו' - היינו מה דמבואר שם דאפילו היו ידיו מלוכלכות ונוטל ידיו לתפלה אינו מברך ועיין לעיל בסימן וי\"ו ס\"א במ\"ב:","(יח) מלמודו - ר\"ל דמסתמא לא נגע באמצע הלימוד במקום מטונף אפ\"ה מצוה ליטול בשביל התפלה וכתב המ\"א דמ\"מ אם נטל לתפלה והפסיק בלימוד א\"צ ליטול שנית ובשבת שמפסיקין במכירת המצות צריכין ליטול שנית לתפלת המוסף אא\"כ לא הסיח דעתו משמירת ידיו והא\"ר כתב דכ\"ז שהם בבה\"מ מן הסתם אין כאן היסח הדעת וכן המנהג:","(יט) לתפלה - ואפילו נטל ידיו לאכילה ואכל ולא הסיח דעתו צריך נטילה לתפלה שאין נטילתו לאכילה עולה לתפלה אבל נטילת שחרית שנטל כשקם ממטתו ולא הסיח דעתו עולה לו לתפלה:","(כ) א\"צ ליטול - אלא ינקה ידיו בכל מידי דמנקי. וכ\"ז בסתם ידים אבל אם נגע ידיו במקום מטונף או עשה צרכיו צריך לחזור אחר מים אף בתפלת מנחה ומעריב וכמו בתפלת שחרית וכמבואר שיעורו לעיל בסימן צ\"ב ס\"ד ע\"ש [אחרונים בסימן צ\"ב] וע\"ש במ\"ב ובה\"ל ששייך לכאן:"]}],"234":[{"s":"<b>הרוצ' להתפלל מנחה גדולה ומנחה קטנה. ובו ב סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>הרוצה להתפלל מנחה גדולה ומנחה קטנה אין ראוי לו להתפלל רשות אלא הגדולה ואם יתפלל הגדולה חובה לא יתפלל הקטנה כי אם רשות אבל אין ראוי להתפלל תפלת רשות אא\"כ מכיר בעצמו שהוא זהיר וזריז ואמיד בדעתו לכוין בתפלתו מראש ועד סוף בלא היסח הדעת אבל אם אינו מכוין בה יפה קרינן ביה למה לי רוב זבחיכם: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>אין לומר אשרי שקודם מנחה אלא כשיש מנין בב\"ה כדי שיאמרו עליו הקדיש שלפני תפלת המנחה (הגהות סמ\"ק וכל בו) יש שכתבו שנהגו לומר <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>פרשת התמיד <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>קודם אשרי של תפלת המנחה נגד תמיד של בין הערבים ומנהג יפה הוא (אבודרהם בשם הר\"י וב\"י):</small>","m":["(א) מנחה גדולה - הוא משש שעות ומחצה ומנחה קטנה הוא מתשע ומחצה ולמעלה ורוצה להתפלל שניהם אחת לחיוב ואחת לנדבה וכמו דקי\"ל בסימן ק\"ז דיכול אדם להתפלל כמה שירצה בתורת נדבה ובלבד שיחדש דבר בתפלתו שהוא לנדבה ע\"ש:","(ב) אין ראוי וכו' - דאף דלעולם מתפללין החוב מקודם ואח\"כ הרשות הכא קודם תשע ומחצה לא הגיע עוד עיקר זמן מנחה שעיקר זמנה לכתחלה הוא מט' ומחצה ולמעלה שהיה זמן הקרבת התמיד בכל יום כנ\"ל בסימן רל\"ג:","(ג) ואם יתפלל וכו' - דבדיעבד יצא י\"ח במנחה גדולה כנ\"ל בסי' רל\"ג ובסתמא [שלא כוון בהדיא לשם נדבה] נמי נראה דעולה לשם חובה ויתפלל השניה לשם נדבה אם ירצה:","(ד) אא\"כ מכיר וכו' - ובריש סימן ק\"ז משמע דבעינן ג\"כ שיחדש בה דבר ואפשר דהיכא שהוא מכיר בעצמו שיכוין היטב ותפלה טובה היא לא בעינן חידוש אבל מלישנא דטור לא משמע הכי:","(ה) אין לומר אשרי וכו' - ואם אמרו בלא מנין ואח\"כ בא מנין יאמרו מזמור א' ואח\"כ יאמרו קדיש וה\"ה כשלומדים בבהמ\"ד בלא מנין ואח\"כ קורין בבהמ\"ד אנשים להשלים המנין לא יפה עושים דהא עיקר טעם קדיש על הלימוד הוא משום שנתקדש השם ברבים וא\"כ בעינן שיהיו עשרה בבהמ\"ד בעת הלימוד מיהו אפשר ללמוד משנה אחת וכיו\"ב אחר שהתאספו עשרה אנשים ולומר קדיש:","(ו) פרשת התמיד - וטוב ג\"כ לומר פטום הקטורת אך כ\"ז אם לא יעבור זמן תפלה אבל אם יש חשש שיעבור זמן תפלה אפילו אשרי ידלג ובעו\"ה יש אנשים שנכשלין בזה:","(ז) קודם אשרי - ט\"ז ומ\"א כתבו לומר אחר אשרי אבל אין המנהג כן. כתב הטור סדר תפלת המנחה אומר אשרי וקדיש ומתפללין י\"ח וש\"ץ חוזר התפלה כמו בשחרית ונופלין על פניהם ואומרים ואנחנו לא נדע וגו' ואומרים קדיש שלם וכו' וכתבו הפוסקים דאם התפללו מנחה סמוך לחשיכה ונמשכו באמירת אבינו מלכנו או שארי תחנונים אחר התפלה עד שחשיכה אין לומר קדיש תתקבל שהתפלה היתה ביום אחר אבל אם אירע שהתפלה עצמה נמשכה בלילה [וכמו תפלת נעילה] אומרים קדיש תתקבל:"]},{"s":"<i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>אם שכח ולא התפלל מנחה מתפלל ערבית שתים ואומר אשרי קודם תפלה שהיא תשלומין לתפלת המנחה (וע\"ל סימן ק\"ח):","m":["(ח) אם שכח וכו' - ואם הזיד עיין לעיל בק\"ח ס\"י:","(ט) קודם תפלה - עיין לעיל בסי' ק\"ח סקי\"ד במ\"ב:"]}],"235":[{"s":"<b>זמן ק\"ש של ערבית. ובו ד סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>זמן קריאת שמע בלילה משעת יציאת <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>שלשה ככבים <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>קטנים ואם הוא יום מעונן ימתין עד שיצא הספק מלבו ואם קראה קודם לכן <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>חוזר <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>וקורא אותה <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"2\"></i><i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>בלא ברכות <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>ואם הצבור מקדימים לקרות ק\"ש מבעוד יום יקרא עמהם ק\"ש וברכותיה ויתפלל עמהם וכשמגיע זמן קורא ק\"ש בלא ברכות: <small>הגה ומיהו לא יחזור ויתפלל בלילה אע\"פ שהצבור <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>מקדימים הרבה לפני הלילה אלא אם כן הוא רגיל בשאר פרישות וחסידות דאז לא מתחזי כיוהרא מה שיחזור ומתפלל (מרדכי ריש ברכות והגהות מיימוני פ\"ב מהלכות תפלה ותרומת הדשן ס\"א):</small>","m":["(א) בלילה משעת וכו' - דכתיב ובשכבך וקודם לילה לאו זמן שכיבה הוא ולילה מקרי משנראו ברקיע ג' כוכבים בינונים אך מפני שאין הכל בקיאין ויבואו לטעות בגדולים [וגדולים בודאי אינן סימן ללילה שכמה פעמים נראין אפילו ביום] החמירו גבי ק\"ש דאינו קורא עד שיראו ג' קטנים:","(ב) שלשה כוכבים - ואפי' מפוזרים:","(ג) ימתין וכו' - דספק דאורייתא הוא [הגר\"א]:","(ד) מלבו - ואם הוא יודע מתי שקעה החמה ימתין כשיעור ד' מילין שהוא ע\"ב מינוט ועיין לקמן סימן רצ\"ג ס\"ב במ\"ב ובה\"ל דכל הענין דשם שייך גם לכאן:","(ה) קודם לכן - ר\"ל קודם צה\"כ או ביום המעונן קודם שיצא הספק מלבו:","(ו) חוזר וקורא אותה - עיין במאמר מרדכי ובנהר שלום שכתבו דמעיקר הדין הוא ולא משום חומרא וכן דעת הגר\"א סק\"א:","(ז) בלא ברכות - דהא כבר בירך אותם ואע\"ג דלא יצא בק\"ש שקרא קודם הזמן אעפ\"כ לא הוי הברכות לבטלה דאע\"ג דמסמכינן להן לק\"ש מ\"מ עיקרן לא נתקנו דוקא לק\"ש ולפיכך בדיעבד שקראן קודם לזמן של ק\"ש יצא:","(ח) ואם הצבור וכו' - והיו עושין כן מפני הדחק שכמה פעמים אלו היו ממתינין בתפלת ערבית עד צה\"כ היה כ\"א הולך לביתו ולא היו מתפללין בצבור שטורח להם להתאסף עוד וגם איכא עמי הארץ טובא דאי לא יתפללו בצבור לא היו מתפללין כלל וע\"כ סומכין עצמן על דעת ר' יהודה שס\"ל דמפלג המנחה ולמעלה נחשב ערבית להתפלל תפלת ערבית וכדאיתא לעיל סימן רל\"ג דשרי לעשות כן בשעת הדחק וכיון שנחשב לענין תפלה ללילה היה מנהגם שהיו קורין אז ג\"כ ק\"ש אף שהוא דלא כהלכתא לרוב הפוסקים:","(ט) יקרא עמהם ק\"ש - ולא יכוין אז לצאת ידי חובת ק\"ש כ\"א בקריאה שניה שקורא אח\"כ בזמנה:","(י) וברכותיה ויתפלל עמהם - כדי לסמוך גאולה לתפלה וגם להתפלל עם הצבור:","(יא) וכשיגיע זמן קורא וכו' - ודי שיקרא שתי פרשיות הראשונות כיון שהזכיר יציאת מצרים בבהכ\"נ דנהי דלענין ק\"ש לא יצא בזה הזמן משום דאכתי לאו זמן שכיבה הוא לענין יציאת מצרים שאנו מחוייבין להזכיר בלילה יוצא בזה הזמן [מ\"א בשם תר\"י] אבל בשאגת אריה האריך ומסיק דירא שמים יש לו ליזהר לקרות כל השלש פרשיות של ק\"ש אחר צאת הכוכבים:"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>אסור <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>להתחיל <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>לאכול <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>חצי שעה סמוך לזמן קריאת שמע של ערבית <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>ואם התחיל לאכול אחר שהגיע זמנה <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i><i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>מפסיק וקורא קריאת שמע בלא ברכותיה וגומר סעודתו ואחר כך קורא אותה בברכותיה ומתפלל: <small>הגה אבל אין צריך להפסיק לתפלה הואיל והתחיל לאכול אבל אם לא התחיל לאכול אע\"פ שנוטל ידיו <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>צריך <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>להפסיק (ר\"ן פ\"ק דשבת) <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>ואם אין שהות להתפלל מפסיק אף <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>לתפלה (הראב\"ד בהגהות פ\"ג מהלכות ברכות):</small>","m":["(יב) קריאת שמע בלא ברכות - ואין כדאי לסמוך על הקריאה שקורא על מטתו אפילו אם מנהגו לקרות כל הג' פרשיות דהא צריך לכוין לצאת ידי מ\"ע של ק\"ש כדלעיל בסימן סמ\"ך וק\"ש שעל מטתו אין אנו מכונים לשם מצוה כ\"א להבריח המזיקין ועוד שאפילו אם נימא דאין צריך כונה לצאת המ\"ע צריך עכ\"פ כונת הלב לקבל עליו עול מלכות שמים במורא ובאותה שעל מטתו אין מכוין לזה. והנה בזמנינו נהגו רוב העולם לקרות ק\"ש ולהתפלל אחר צאת הכוכבים כדין מיהו באיזה מקומות בבתי כנסיות יש עדיין מנהג הישן שמתפללין תיכף אחר מנחה אף שהוא מבע\"י קצת והמתפלל במקומות האלו יראה לחזור ולקרות ק\"ש כשיגיע הזמן. ולפחות יראה לקרות כל הפרשיות על מטתו כדין ויכוין לצאת בזה המ\"ע של ק\"ש ובאיזה מקומות יש מנהג שהותיקין אינן קוראין ק\"ש עם הצבור אלא שותקין עד שמ\"ע ומתפללין עמהם וממתינין אחר התפלה עד צה\"כ וקורין ק\"ש וברכותיה ואין חוששין לסמיכת גאולה לתפלה וגם מנהג זה נזכר בדברי הקדמונים עיין בב\"י ועיין מה שכתבנו לעיל בסימן רל\"ג ס\"א במ\"ב ואשרי המתפלל מעריב בזמנו בצבור ועיין מה שכתבנו בבה\"ל בשם המעשה רב:","(יג) ומיהו לא יחזור וכו' - עיין בה\"ל:","(יד) מקדימין - הסכמת הפוסקים הוא דעכ\"פ אין לו להקדימה יותר מפלג המנחה ואם הקדים לא יצא לא בק\"ש וברכותיה ולא בתפלה לכו\"ע וצריך לחזור ולקרוא ק\"ש וברכותיה ולהתפלל שמ\"ע. ואפילו מפלג המנחה ולמעלה אינו אלא למי שהתפלל מנחה קודם פלג אבל להתפלל מנחה ומעריב אחר פלג הוי תרתי דסתרי אהדדי:","(טו) דאז לא מתחזי כיוהרא - אבל מה שחוזר וקורא ק\"ש לא מחזי כיוהרא דלענין ק\"ש כמעט כל הפוסקים מסכימים דזמנה הוא מצה\"כ. כתבו האחרונים מי שנוהג לקרות ק\"ש ולהתפלל בצבור בזמנה וכשהיה בצבור שקורים ומתפללים מבעוד יום טעה והתחיל בברכת ק\"ש יגמור הברכות עם הק\"ש עד שמ\"ע כדי שלא יהיה ברכה לבטלה אבל שמ\"ע לא יתפלל עמהם וכשיגיע זמן ק\"ש יקרא ק\"ש בלא ברכות ויתפלל עם הצבור ואע\"ג דעכשיו אינו סומך גאולה לתפלה דתפלה בזמנה עדיף מסמיכת גאולה לתפלה:","(טז) אסור להתחיל וכו' - והטעם שמא ימשך בסעודתו ופעמים ישתקע עי\"ז גם בשינה וישכח לקרות שמע ואפילו לאכול קמעא אסור ומ\"מ טעימה בעלמא מיני פירות או אפילו פת בכביצה שרי:","(יז) לאכול - וכן לישן אפילו דעתו רק לישן קמעא [גמרא] וה\"ה דאסור אז לעשות כל המלאכות המבוארות לעיל בסימן רל\"ב ס\"ב שהם דברים המביאים לידי פשיעה וכ\"ש כשהגיע זמן ק\"ש בודאי אסור להתחיל בהן [לבוש ופמ\"ג ברל\"ב ודה\"ח] וא\"ר מצדד להתיר בהם קודם שהגיע זמן ק\"ש. מיהו ללמוד לכו\"ע שרי בסמוך לה [ואדרבה מצוה הוא וכמו שאמרו בש\"ס אדם בא מן השדה בערב נכנס לביהכ\"נ אם רגיל לקרות קורא לשנות שונה וקורא ק\"ש ומתפלל] אבל משהגיע זמן ק\"ש אסור אף ללמוד כשהוא מתפלל בביתו ביחיד ואם אמר לחבירו שאינו לומד שיזכרנו שיתפלל מותר [אחרונים]:","(יח) חצי שעה - דעת הט\"ז להקל בזה ולא בעי אלא שיעור מועט והאחרונים מסכימים לפסק השו\"ע דכל דליכא אלא חצי שעה אסור להתחיל לאכול ואם ביקש מאחד שיזכירנו להתפלל ליכא אסורא להתחיל לאכול אפילו כשכבר הגיע זמן ק\"ש:","(יט) סמוך לזמן ק\"ש - היינו סמוך לצאת הכוכבים ומשמע ממ\"א דאפילו במוצאי שבת יש ליזהר שלא להתחיל אז הסעודה ועיין במ\"ב רצ\"ט סק\"א מש\"כ בזה. כתבו האחרונים הקורין ומתפללין מבעוד יום אע\"ג שיש להם לחזור ולקרות ביציאת הכוכבים וכנ\"ל בס\"א אפ\"ה מותר להם לאכול קודם שיקרא שנית שהרי עכ\"פ כבר קרא ומ\"מ בהגיע זמן צה\"כ ממש נכון ליזהר גם בזה:","(כ) התחיל לאכול אחר וכו' - ובתוך חצי שעה סמוך לצאת הכוכבים נמי כאחר שהגיע זמן הוא:","(כא) מפסיק - מיד כיון דק\"ש דאורייתא הוא והוא התחיל באיסור ואם התחיל בהיתר דהיינו לפני חצי שעה שסמוכה לצה\"כ אפילו לק\"ש אינו מפסיק כל שיש לו שהות לקרוא אחר גמר סעודתו וכנ\"ל בסימן עיי\"ן במ\"ב ס\"ק כ\"ג כ\"ד:","(כב) בלא ברכותיה - משום דברכות אינם אלא מדרבנן לא הטריחוהו להפסיק בשבילם:","(כג) אבל אין צריך וכו' - כמ\"ש המחבר שאינו מפסיק אלא לקרות ק\"ש בלחוד בלא ברכות ובלא שמ\"ע ומשום שהם רק מדרבנן והאי דהדר ושנאו הרמ\"א משום דרצה לסיים אבל וכו':","(כד) אע\"פ שנטל ידיו - היינו אף שיש עוד שהות הרבה להתפלל מחמרינן ליה שיפסיק. ולא דמי להתחיל סמוך למנחה דאינו מפסיק בדיעבד אם כבר נטל ידיו כדמבואר לעיל בסי' רל\"ב דבמנחה כיון דזמנה מועט מירתת ולא אתי למפשע משא\"כ בערבית דזמנה בדיעבד כל הלילה גזרינן דלמא אתי למפשע ויסמוך על אריכותה של לילה להכי כ\"ז שלא התחיל באכילה עצמה מטרחינן ליה להפסיק אף שנטל ידיו ודוקא כשלא בירך עדיין ענט\"י אבל אם כבר בירך ענט\"י נכון שלא יפסיק אלא יברך המוציא ויאכל כזית ויפסיק סעודתו ואף דבהתחיל לאכול א\"צ להפסיק הכא שאני שלא התחיל לאכול רק בשביל שלא יהא הפסק בין נט\"י להמוציא שאינו נכון לכתחלה כמבואר לעיל בסימן קס\"ו:","(כה) ואם אין שהות - ר\"ל בין שהוא עומד סמוך לעלות השחר או אפילו עומד בתחלת הלילה רק שסעודה זו תמשך עד עלות השחר כגון סעודות גדולות בימות הקיץ שהלילות קצרים צריך להפסיק מיד ביציאת הכוכבים ואפילו התחיל בהיתר מבעוד יום נמי הדין כן:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>לכתחלה צריך לקרות ק\"ש <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"7\"></i>מיד בצאת הככבים <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>וזמנה עד <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>חצי הלילה ואם עבר ואיחר וקרא עד שלא עלה עמוד השחר יצא י\"ח:","m":["(כו) מיד בצאת הכוכבים - דזריזין מקדימין למצות:","(כז) עד חצי הלילה - פי' דרבנן גדרו שאסור להתאחר בקריאת שמע ביותר מחצות שלא לבוא לידי מכשול ואם מתאחר מקרי עובר על דברי חכמים אבל עד חצות ליכא איסורא אם מתאחר אלא שלא נקרא זריז וכנ\"ל והיינו ביושב ואינו עוסק באכילה או במלאכה המטרדת דאלו אוכל או עוסק במלאכה המטרדת כההיא דסימן רל\"ב ס\"ב מדינא אסור משהגיע זמן ק\"ש וכנ\"ל בס\"ב:","(כח) ואם עבר ואיחר וכו' - דמן התורה לכו\"ע זמנה כל הלילה דובשכבך כ\"ז שבני אדם שוכבין משמע:","(כט) עד שלא עלה עה\"ש וכו' - משום דמיירי בעבר דהיינו בפשיעה נקט עד שלא עלה אבל בנאנס אפילו אחר שעלה השחר רק שהוא קודם הנץ נמי קורא ויוצא וכדלקמיה בסעיף ד':"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>הקורא קריאת שמע של ערבית אחר שעלה עמוד השחר קודם הנץ <small> (פירוש יציאת החמה מענין הנצו הרימונים) </small> החמה לא יצא ידי חובתו אלא א\"כ היה אנוס <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>כגון <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>שכור או חולה וכיוצא בהן <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>ואנוס שקרא אז לא יאמר השכיבנו דכיון שעלה עמוד השחר אינו זמן שכיבה: <small>הגה אבל שאר הברכות דהיינו שנים שלפני קריאת שמע וברכת אמת ואמונה עד השכיבנו אומר (טור ומרדכי והגהות מיימוני וע\"ל סי' נ\"ח סעיף ה'):</small>","m":["(ל) לא יצא וכו' - דאף דמן התורה קרינן בשכבך עד הנץ משום דאיכא עדיין מקצת אנשים דגנו בההיא שעתא מ\"מ היכא דלא איתנס בטלו חכמים ממנו מצות ק\"ש על שאיחר כ\"כ ואינו יוצא ידי חובתה שוב בקריאתה:","(לא) כגון שכור וכו' - ואפילו נשתכר לאחר שהגיע זמן ק\"ש דהיינו מצאת הכוכבים ואילך נמי אינו בכלל מזיד דקסבר עדיין יש שהות שבתוך כך יפוג יינו אבל בנשתכר זמן מועט קודם עלות השחר שאי אפשר בשעה קטנה כזו להפיג שכרותו לא הוי אונס ולא יצא ידי חובתו:","(לב) לא יאמר השכיבנו - מתבאר בפוסקים דאפילו אם ירצה לדלג תיבת השכיבנו ולהתחיל מן ותקננו בעצה וכו' נמי אינו נכון:","(לג) אינו זמן שכיבה - ר\"ל אינו זמן שבני אדם הולכים לשכב שיהיה שייך לומר על זה השכיבנו אבל מ\"מ מיקרי זמן שכיבה לענין מצות עשה דק\"ש דכתיב בה בשכבך דהכוונה כל זמן שבני אדם שוכבין ועדיין יש מקצת בני אדם שוכבין וכנ\"ל:","(לד) עד השכיבנו אומר - ולא יאמר ברוך ה' לעולם וגו' וגם שמ\"ע לא יתפלל דתפלת ערבית נתקנה רק בשביל לילה ומכיון שעלה עה\"ש יום הוא לכל דבר:"]}],"236":[{"s":"<b>דין ברכות ק\"ש של ערבית. ובו ד סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>בערב <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>מברך <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>שתים לפני ק\"ש ושתים לאחריה:","m":["(א) בערב וכו' - והמנהג לומר והוא רחום קודם תפלת ערבית [טור בסי' רל\"ז ע\"ש הטעם]. ודע דמה שמבואר לעיל בסימן נ\"ד במ\"ב סקי\"ד בשם האחרונים דאחר ברכו דינו כאמצע הפרק [דעיקר ברכו שאומר הש\"ץ הכונה אברכות שמברכין העולם אח\"כ וכיון שענו העולם ברכו הוי כאלו התחילו הברכה וכמש\"כ הא\"ר והפמ\"ג שם עי\"ש] פשוט דאין לחלק בין שחרית לערבית ולפ\"ז צריך ליזהר מאד שלא לספר אחר ברכו דערבית אפילו קודם שהתחיל לברך הברכה ראשונה אם דעתו להתפלל אז מעריב עם הצבור ובעו\"ה הרבה אנשים נכשלין בזה:","(ב) שתים וכו' - אשר בדברו וכו' ואהבת עולם ואינה פותחת בברוך דהויא סמוכה לראשונה. ויש להפסיק בין ברקיע כרצונו לבין בורא יום ולילה דכרצונו קאי אדלעיל. ומנהג ספרד שלא לומר ה' צבאות וכו' אל חי וכו' אלא מסיימין תיכף אחרי מבדיל בין יום וכו' ברוך אתה וכו' כי היכי דלהוי מעין חתימה סמוך לחתימה וכן נכון ועיין בטור שיישב גם מנהגנו דהוי ג\"כ מעין חתימה שאנו מתפללין שימלוך ה' ויתקיים והיה לעת ערב יהיה אור לנו וחשך לשונאי ה' ומה שאנו אומרים ה' צבאות כתבו ג\"כ האחרונים משום דכתיב עושה עיפה ושחר ה' צבאות שמו:","(ג) ושתים לאחריה - ראשונה אמת ואמונה ואינה פותחת בברוך דהויא סמוכה לחברתה דק\"ש לא הוי הפסק וחותם בא\"י גאל ישראל ולא גואל ישראל כמו בתפלה משום שנתקנה על הגאולה שעברה [טור] ובמערבית של יו\"ט נוהגין לסיים מלך צור ישראל וגואלו ומפקפקין הרבה בזה והרבה מהאחרונים מישבין המנהג ואעפ\"כ יותר טוב לסיים גאל ישראל כמו בשאר ימות השנה וכמו שכתבנו לעיל בסימן ס\"ו במ\"ב ס\"ק ל\"ג וברכה שניה השכיבנו וחותם שומר עמו ישראל לעד מפני שלילה צריכין שימור מן המזיקין ואע\"ג דקי\"ל דצריך לסמוך גאולה לתפלה אף בערבית וכדלקמיה בס\"ב מ\"מ השכיבנו לא הוי הפסק דכגאולה אריכתא דמיא [גמרא] וכתבו בתר\"י הטעם דכשעבר ה' לנגוף את מצרים היו ישראל מפחדים ומתפללים להש\"י שיקיים דברו שלא יתן המשחית לבא אל בתיהם לנגוף וכנגד אותה תפלה תקנו לומר השכיבנו הלכך מעין גאולה היא:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>אין לספר בין גאולה דערבית לתפלה <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ואף הנוהגין <i data-commentator=\"Eshel Avraham\" data-label=\"ב\" data-order=\"2\"></i>לומר י\"ח פסוקים ויראו עינינו אין להפסיק בין יראו עינינו לתפלה <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>ומיהו מה שמכריז ש\"צ ר\"ח בין קדיש לתפלת ערבית לא הוי הפסק כיון שהוא <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>צורך תפלה <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>וכן יכול לומר ברכו להוציא מי שלא שמע ולא הוי הפסק: <small>הגה וע\"ל סי' ס\"ט. ראיתי מדקדקים <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>נהגו לעמוד כשאומרים הי\"ח פסוקים של ברוך ה' לעולם וכו' ומנהג יפה הוא <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>כי נתקנו במקום תפלת י\"ח וע\"כ ראוי <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>לעמוד בהן כמו בתפלה:</small>","m":["(ד) בין גאולה דערבית לתפלה - שגם בערבית מצוה לסמוך גאולה לתפלה:","(ה) ואף הנוהגין לומר וכו' - ובטור מסיים בזה ומה שנוהגין להפסיק בפסוקים ויראו עינינו וקדיש לפי שבימים הראשונים היו בתי כנסיות שלהם בשדות והיו יראים להתאחר שם עד זמן תפלת ערבית ותקנו לומר פסוקים אלו שיש בהם י\"ח אזכרות כנגד י\"ח ברכות שיש בתפלת ערבית ונפטרין בקדיש ועתה שחזרו להתפלל ערבית בבתי כנסיות לא נתבטל מנהג הראשון ומ\"מ אין להפסיק בדברים אחרים ויש מן הגדולים שנהגו שלא לאמרם עכ\"ל ובזה נבין דברי המחבר:","(ו) אין להפסיק וכו' - דאותן פסוקים לא מקרי הפסק כיון דתקינו לאומרם הו\"ל כגאולה אריכתא [תוספות]:","(ז) צורך התפלה - ולאו דוקא לקרוא ולהכריז שהוא ר\"ח שהוא דאורייתא או להכריז טל ומטר שאם יטעו צריך לחזור אלא אפילו להכריז על הנסים שפיר דמי ואע\"ג שאם יטעו ג\"כ אין צריך לחזור דמ\"מ הוא צורך תפלה. ודוקא במקום זה יכול להפסיק אבל כשהוא עומד בברכת ק\"ש בין הפרקים אסור לו להכריז שום דבר:","(ח) לומר ברכו - דגם זה הוא צורך תפלה:"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"4\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>מצא צבור שקראו קריאת שמע ורוצים לעמוד בתפלה <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>יתפלל עמהם ואח\"כ יקרא ק\"ש <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>עם ברכותיה:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>אחר שומר עמו ישראל אומר אמן אחר ברכת עצמו ולא יענה אמן אחר ברכת <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>המלך בכבודו: <small> (ועיין לעיל סי' רט\"ו):</small>","m":["(ט) ועיין לעיל סי' ס\"ט - ר\"ל דשם בהג\"ה מבואר דדוקא בערבית מקילינן לזה אבל לא בשחרית:","(י) נהגו לעמוד וכו' - והרבה אחרונים כתבו דיותר טוב שלא לעמוד כדי להראות שאין רוצה לצאת בזה ידי חובת תפלת י\"ח אך כשמתפלל עם הצבור וקורא אח\"כ ק\"ש וברכותיה אז יוכל לומר ברוך ה' וכו' מעומד ועיין מה שנכתוב לקמיה. כתב מ\"א בשם רש\"ל שיש לומר הושיענו אלהי ישענו והוא פסוק בדברי הימים ולא יאמר הושיענו ה' אלהי ישענו דא\"כ הוא מוסיף על י\"ח אזכרות:","(יא) ורוצים לעמוד בתפלה - ואם הם עוסקים עדיין בברכות ק\"ש והוא משער שעד שיגיעו הצבור לשמ\"ע יוכל לומר ק\"ש וברכותיה עד שומר עמו ישראל לעד יעשה כן וידלג ברוך ה' לעולם וכו' ויתפלל שמ\"ע עם הצבור דאותן הפסוקים אינן אלא מנהג ויש גדולים שסוברים שאין לאומרו ולכן מוטב לדלג כדי לקיים תפלה בצבור עם סמיכת גאולה לתפלה כן כתבו כמה אחרונים [והנה בדברי הט\"ז וא\"ר מבואר בהדיא דברוך ה' לעולם וכו' וגם יראו עינינו יאמר אחר התפלה וכן העתיק הח\"א וכן משמע קצת במ\"א סק\"ב אכן במעשה רב כתב דאחר התפלה לא יאמר הפסוקים דברוך ה' לעולם וכו' ומשמע דטעמיה דלא נתקן אלא לאומרו במקומו ולא אחר שכבר התפלל ערבית וע\"כ נראה דטוב שלא יחתום ברכת יראו עינינו אלא יאמר עד כי אין לנו מלך אלא אתה ואע\"ג דברכה בלא חתימה בעלמא אינה חשובה ברכה כלל מ\"מ כיון דאפילו קודם י\"ח הוא רק מנהגא בעלמא הבו דלא להוסיף עלה] עוד כתבו במקומות שמקדימין להתפלל ערבית מבע\"י ובא לבהכ\"נ בשעה שמתחילין ברכו והוא לא התפלל מנחה יתפלל מנחה בעוד שהם קורין ק\"ש וברכותיה ואח\"כ יתפלל ערבית עם הצבור ואח\"כ יקרא ק\"ש וברכותיה בלילה אכן אם יהיה לו לתפלת ערבית מנין בלילה ימתין בתפלת מנחה להתפלל בשעה שהצבור מתפללין ערבית ותפלת ערבית יתפלל אח\"כ כדינה עם צבור בלילה [פמ\"ג]:","(יב) יתפלל עמהם - דתפלת הצבור עדיפא ממסמך גאולה לתפלה דערבית [ואפילו אם הצבור מתפללין מבע\"י אפ\"ה יתפלל עמהם ויקרא ק\"ש וברכותיה כשיגיע זמנה ועיין לעיל בסי' רל\"ג ס\"א מתי יוכל להתפלל שמ\"ע דערבית מבעוד יום] אבל כ\"ז דוקא כשהוא משער שלא יוכל להשיג אח\"כ מנין להתפלל עמהם דאל\"ה אין לו לבטל מצות סמיכת גאולה לתפלה:","(יג) אחר ברכת עצמו - שהוא סיום ברכת ק\"ש ואזיל המחבר לטעמיה במה שפסק בסימן רט\"ו ס\"א עי\"ש:","(יד) ולא יענה וכו' - כי היא אינה שייך לברכת ק\"ש והויא ככל ברכה מיוחדת שאין עונה אמן אחר ברכת עצמו:","(טו) המלך בכבודו - באומרו תמיד ימלוך עלינו לא יהיה כונתו בלשון בקשה שמתפלל שימלוך עלינו דהיינו לקרב הגאולה שאין תפלה בחתימת הברכה אלא יהיה כונתו בלשון שבח שהקב\"ה ימלוך לעולם [מ\"א]:","(טז) וע\"ל סי' רט\"ו - ר\"ל ששם כתב הרמ\"א שבמדינותינו אין נוהגין לענות אחר ברכת עצמו אפילו אחר ברכת שומר עמו ישראל לעד:"]}],"237":[{"s":"<b>סדר תפלת ערבית. ובו סעיף אחד:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>אין ש\"צ חוזר התפלה בתפלת ערבית <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><small> (ואין נופלין על פניהם לאחר ערבית):</small>","m":["(א) אין שליח צבור וכו' - שאין תפלת ערבית חובה רק מצוה ולא נתחייב בה אדם שיצטרך הש\"ץ להוציאו ידי חובתו [רמב\"ם] ואפילו האידנא דקבעוה חובה מ\"מ לא אלים מנהגא לשויוה חובה כדי לאטרוחי צבורא להחזיר הש\"ץ התפלה [ל\"ח וא\"ר]:","(ב) ואין נופלין וכו' - וכ\"כ הב\"ח ומ\"א. ואפילו התפללו ערבית מבע\"י אין נופלין דכבר שויא לילה. ואפילו תפלה שהוא מתפלל לשם תשלומין של תפלת מנחה ג\"כ אין ליפול [פמ\"ג]. כתב ש\"ג ריש ברכות נהגו בקצת מקומות לומר שיר המעלות הנה ברכו וכו' קודם מעריב משום דאמרינן רגיל לקרות קורא דצריך לקרות שמע מתוך ד\"ת והא דאמרינן מזמור זה יותר מאחרים משום דכתיב ביה העומדים בבית ה' בלילות א\"נ משום דכתיב שאו ידיכם קודש וברכו את ה' [א\"ר ע\"ש עוד]:\n"]}],"238":[{"s":"<b>לקבוע עתים לתורה בלילה. ובו ב סעיפים:</b><br><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>צריך ליזהר בלמוד הלילה יותר מבשל יום והמבטלו עונשו <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>מרובה:","m":["(א) בלימוד הלילה וכו' - כדאמרינן לא איברי לילא אלא לגירסא וכיון דלכך נברא הלילה ע\"כ צריך ליזהר בה יותר ואיתא בגמרא כל העוסק בתורה בלילה הקב\"ה מושך עליו חוט של חסד ביום שנא' יומם יצוה ד' חסדו ובלילה שירה עמי. עוד אמרו [מנחות ק\"י] ת\"ח העוסקים בתורה בלילה מעלה עליהן הכתוב כאלו עסוקין בעבודה ומייתי שם מקרא. עוד אמרו [תמיד ל\"ב] כל העוסק בתורה בלילה שכינה כנגדו שנאמר קומי רוני בלילה [היינו לעסוק בתורה] וכתיב בתריה שפכי כמים לבך נוכח פני ה' וכתב הרמב\"ם והובא ביו\"ד סי' רמ\"ו הרוצה לזכות בכתרה של תורה יזהר בכל לילותיו ולא יאבד אפילו אחת מהן בשינה ואכילה ושתיה ושיחה וכיו\"ב וכו' ומה דכתב בכל לילותיו היינו דאפילו בקיץ בלילות הקצרים כגון בתמוז שאז נקבע הלילה העיקר לשינה כמו שכתבו התוספות אפ\"ה צריך עכ\"פ ללמוד מעט קודם השינה [אחרונים] ועיין לעיל בסימן א' במ\"ב סק\"ט:","(ב) עונשו מרובה - וכדאמרינן [חלק צ\"ב] כל בית שאין ד\"ת נשמעין בו בלילה אש אוכלתו שנאמר וגו' ואיתא בפ\"ק דאבות ודלא מוסיף יסיף [היינו דלא מוסיף ללמוד בלילה מט\"ו באב ואילך יסוף מן העולם] ועיין במ\"א דלשינת האדם בלילה אין לזה שיעור קבוע אלא תלוי בכל אדם לפי כח בריאותו ועכ\"פ לא ישתקע בשינה יותר מדאי וכדאיתא במשנה [סנהדרין פ\"ח] שינה לצדיקים רע להן ורע לעולם ופירש\"י מפני שאינם עוסקין בתורה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>אם יש לו חק קבוע ללמוד כך וכך ליום והיה טרוד ביום ולא השלימו <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>ישלימנו <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>בלילה מיד:","m":["(ג) חק קבוע וכו' - עיין לעיל בסימן קנ\"ה ס\"א ובמ\"ב שם:","(ד) ישלימנו בלילה - כלומר אפילו בלילות הקצרים מחוייב להיות ניעור בלילה כדי להשלים חוקו ולא יאחר זה עד יום מחר כי יום של אחריו מחוייב בפני עצמו ונמצא דיום זה לא השלים חוקו והוי מעוות לא יוכל לתקון [פמ\"ג]:","(ה) מיד - והוי נדר כדאמרינן [נדרים ז'] האומר אשנה פרק זה נדר גדול נדר לאלהי ישראל ואיתא ביו\"ד בסימן ר\"ד ס\"א דאם נהג לעשות דבר טוב אם היה דעתו לנהוג כן לעולם הוי נדר וטוב שיתנה בתחלה שלא יהיה עליו דבר זה בנדר פן יזדמן איזה פעם שלא יוכל להשלים:"]}],"239":[{"s":"<b>דין ק\"ש על מטתו. ובו ב סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>קורא על מטתו <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>פרשה ראשונה של שמע <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>ומברך <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"2\"></i>המפיל חבלי שינה על עיני וכו': <small>הגה ויקרא ק\"ש <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>סמוך למטתו ואין אוכלים ושותים ולא מדברים אחר קריאת שמע על מטתו אלא <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>ישן מיד שנאמר אמרו בלבבכם על משכבכם ודומו סלה (כל בו רוקח ורבינו ירוחם נ\"ב ח\"ב) ועיין לעיל סי' ס\"ג אי מותר לקרות <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>כשהוא <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>שוכב ואם קרא קריאת שמע ולא יוכל לישן מיד אז <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>חוזר וקורא כמה פעמים זה אחר זה עד שישתקע בשינה ושיהיה קריאתו סמוך לשינתו (הגהות מיי' פ\"ז) ואין מברכין על ק\"ש של ערבית (הגהות מיי' פ\"ז וב\"י בשם תוס' פ' כל הבשר) </small> ואומר <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>יושב <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>בסתר עליון ואומר ה' מה רבו צרי עד לה' הישועה ואומר <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ברוך ה' ביום ברוך ה' בלילה ברוך ה' בשכבנו ברוך ה' בקומנו ויאמר ה' אל השטן יגער ה' בך השטן וכו' ה' שומרך וכו' מעתה ועד עולם בידך אפקיד רוחי וכו' יברכך ה' וכו' עד וישם לך שלום ואומ' <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>השכיבנו עד סמוך לחתימה:","m":["(א) פרשה ראשונה - ואם התפלל ערבית מבעוד יום צריך לקרות כל הפרשיות ויכוין לצאת בהן המ\"ע של ק\"ש וגם המצוה של זכירת יציאת מצרים. וטוב לומר תמיד כל ק\"ש שהיא רמ\"ח תיבות [בצירוף אל מלך נאמן] לשמור רמ\"ח אבריו:","(ב) ומברך המפיל וכו' - מלשון השו\"ע משמע דברכת המפיל אומר אחר ק\"ש כדי שתהא הברכה סמוכה לשינה ומה שקורא אח\"כ יושב בסתר ואינך כיון דהוי משום שמירה לא הוי הפסק [ויש מדקדקין לברך המפיל בסוף אחר כל הפסוקים] ויש מאחרונים שהסכימו שיברך ברכת המפיל קודם ואח\"כ ק\"ש ויתר פסוקי דרחמי (כמו שנדפס בסידורים) ונראה דלמעשה יתנהג האדם כפי טבעו דהיינו אם טבעו להרדם באמצע ק\"ש טוב יותר שיקדים ברכת המפיל מה דאפשר ואם אין טבעו לזה טוב יותר לאחר ברכת המפיל עד לבסוף:","(ג) סמוך למטתו - ולא יקרא ק\"ש כשיכנס לישן אלא כשרואה שהשינה באה עליו [סדה\"י] אבל בכנה\"ג כתב שיש לקרות מיד שמא יחטפנו שינה אח\"כ ולא יקרא ואין לחוש משום הפסק אלא כשעושה ד\"א בינתים אבל מה שיושב ודומם לא מקרי הפסק אף ששהה איזה זמן קודם שיישן:","(ד) אחר ק\"ש וכו' - ואם תאב לשתות או לדבר איזה ענין נחוץ נראה שמותר אך יחזור ויקרא פרשת שמע אכן אם כבר אמר ברכת המפיל יזהר בזה כי יפסיק בין הברכה להשינה:","(ה) יישן מיד - ואם צריך לשמש מטתו ירחץ עצמו מהש\"ז שעליו ויטול ידיו ואח\"כ יקרא. ולפחות יאמר ברכת המפיל ושמע אחר התשמיש:","(ו) כשהוא שוכב - ר\"ל דשם מוכח בס\"א בהג\"ה דלכתחלה אין כדאי לילך ולשכב ולקרותה בשכיבה אפילו כשהוא שוכב על צדו ממש. כתב המ\"א דוקא כשקורא זו הק\"ש לשם חובה כגון שהתפלל ערבית מבע\"י וצריך עתה לכוון לקיים המ\"ע דק\"ש לכך צריך ליזהר בכל פרטיה אבל אם כבר קרא בזמנה וקורא עתה רק משום ק\"ש שעל המטה מותר לכתחלה לקרותה בשכיבה ויש שמחמירין לכתחלה לקרותה בעמידה או בישיבה אכן אם כבר שכב לכו\"ע מותר להטות על צדו ולקרוא. ויש לו לאדם להרגיל עצמו לשכב על צדו דוקא ואיסור גדול לשכב פרקדן דהיינו שמושלך על גבו ופניו למעלה או שפניו טוחות למטה:","(ז) חוזר וקורא - פרשה ראשונה [וראוי שלא לכפול פסוק ראשון] או שיאמר שאר פסוקים דרחמי. וה\"ה אם מהרהר בד\"ת שפיר דמי [מ\"א]:","(ח) ואין מברכין וכו' - פי' אשר קדשנו במצותיו וצונו על ק\"ש אין לברך ולאפוקי מדעת איזה פוסק שמצריך לברך. כתבו הפוסקים הישן ביום א\"צ לברך ברכת המפיל וטוב שיאמר ויהי נועם וגו' יושב בסתר וגו':","(ט) ואומר יושב בסתר וגו' - כל אלו הפסוקים שנהגו לאומרם הוא להגן שלא יבוא עליו ח\"ו דבר רע. ואם הוא חולה או אנוס די במה שיאמר פרשה ראשונה של ק\"ש וברכת המפיל לבד [מ\"א]. כתבו הספרים שבלילה קודם השינה נכון לאדם שיפשפש במעשיו שעשה כל היום ואם ימצא שעשה עבירה יתודה עליה ויקבל ע\"ע שלא לעשותה עוד ובפרט בעונות המצויים כגון חניפות שקרים ליצנות לשה\"ר וכן עון בטול תורה צריכים בדיקה ביותר. גם ראוי למחול לכל מי שחטא כנגדו וציערו ובזכות זה האדם מאריך ימים [מגילה כ\"ח]. אחז\"ל הישן בבית יחידי והיינו בלילה אוחזתו לילית ובית היינו חדר. אלו צריכין שימור מהמזיקין חולה חיה חתן כלה אבל. ות\"ח בלילה [היינו כשהוא עומד יחידי באישון לילה ואפלה]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i> כשיפשוט חלוקו לא יהפכנו ממטה למעלה שאם כן נמצא גופו ערום אלא יפשטנו דרך ראשו ויכסה עצמו בסדינו מתחת ויכנס במטתו:","m":[]}],"240":[{"s":"<b>איך יתנהג האדם בתשמיש מטתו. ובו יז סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>אם היה נשוי לא יהא רגיל ביותר עם אשתו אלא <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>בעונה האמורה <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>בתורה <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>הטיילים שפרנסתן מצויה להם ואין פורעים מס עונתן בכל יום. הפועלים שעשו מלאכה בעיר אחרת <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>ולנין בכל לילה בבתיהם פעם אחת בשבוע ואם עושים מלאכה בעירם פעמים בשבוע. החמרים אחת בשבוע. הגמלים אחת לשלשים יום. הספנים אחת לששה חדשים. <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>ועונת <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>תלמידי חכמים מליל שבת <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>לליל שבת <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>וכל אדם צריך לפקוד את אשתו בליל <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>טבילתה <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>ובשעה שיוצא <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>לדרך אם אינו הולך לדבר מצוה וכן אם אשתו מניקה <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>והוא מכיר בה שהיא משדלתו ומרצה אותו ומקשטת עצמה לפניו כדי שיתן דעתו עליה <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>חייב לפקדה. <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>ואף כשהוא מצוי אצלה לא יכוין להנאתו אלא כאדם שפורע חובו שהוא חייב בעונתה <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>ולקיים מצות בוראו שיהיו לו בנים עוסקים בתורה ומקיימים מצות בישראל וכן אם מכוין לתקון הולד <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>שבששה חדשים אחרונים יפה לו שמתוך כך יצא מלובן ומזורז שפיר דמי. ואם הוא מכוין לגדור עצמו בה כדי שלא יתאוה לעבירה כי רואה יצרו גובר ומתאוה אל הדבר ההוא: <small>הגה גם בזה יש קבול שכר אך (טור) יותר </small> טוב היה לו לדחות את יצרו ולכבוש אותו כי אבר קטן יש באדם מרעיבו שבע משביעו רעב אבל מי שאינו צריך לדבר אלא שמעורר תאותו כדי למלאות תאותו זו היא עצת יצר הרע ומן ההיתר יסיתנו אל האיסור ועל זה <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>אמרו רבותינו ז\"ל המקשה עצמו לדעת יהא בנדוי:","m":["(א) לא יהא רגיל ביותר - עיין רמב\"ן בחומש פרשת קדושים בראשו:","(ב) אלא בעונה וכו' - וצריך לקיים העונה גם כשהיא מעוברת או מניקה. ולא יבטל עונתה אלא מדעתה כשהיא מוחלת לו וכבר קיים מצות פו\"ר:","(ג) האמורה בתורה - וכ\"ז במי שגופו בריא אבל מי שאינו בריא אינו חייב אלא לפי מה שאומדין אותו שיכול לקיים [אה\"ע סימן ע\"ו ס\"ג]:","(ד) הטיילים - בני אדם הבריאים והמעונגים [רמב\"ם] ואפילו הם בני תורה כ\"ז שאיננו ת\"ח [א\"ר וכ\"כ בית שמואל באה\"ע סימן ע\"ו דבת\"ח שהתורה מתשת כחו בכל גווני הוא מע\"ש לע\"ש וכ\"מ בתשובת מ\"צ סימן נ\"א] ועיין לקמיה בסק\"ו:","(ה) הגמלים - שהם המביאים חבילות על הגמלים ממקום רחוק:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>לא ישתה אדם בכוס זה <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>ויתן עיניו <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>בכוס אחר ואפילו שתיהן נשיו:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>וברותי מכם המורדים והפושעים בי אלו בני תשע' מדות בני <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>אנוס' בני <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>שנואה בני נידוי <i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>בני <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>תמורה בני <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i>מורדת בני <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"11\"></i>שכרות בני <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"12\"></i>גרושת הלב בני <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"13\"></i>ערבוביא בני <i data-commentator=\"Magen Avraham\" data-order=\"14\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"14\"></i>חצופה:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>אסור להסתכל באותו מקום <i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>שכל המסתכל שם אין לו בושת פנים ועובר על והצנע לכת ומעביר הבושה מעל פניו שכל המתבייש אינו חוטא דכתיב ובעבור תהי' יראתו על פניכם זו הבושה לבלתי תחטאו ועוד דקא מגרי יצר הרע בנפשי' וכל שכן הנושק שם שעובר על כל אלה ועוד שעובר על בל תשקצו את נפשותיכם:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>הוא למטה והיא <i data-commentator=\"Ba'er Hetev\" data-order=\"15\"></i>למעלה זו דרך עזות שמשו שניהם כאחד זה דרך עקש:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i>אסור לאדם לשמש מטתו בפני כל אדם אם הוא נעור <i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"15\"></i>ואפי' ע\"י הפסק מחיצה עשרה <i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"16\"></i>ובפני תינוק שאין יודע לדבר מותר <i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"17\"></i>בית שיש בו ס\"ת או חומשים העשוים בגלילה <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>אסור לשמש בו עד שיהי' בפניו <i data-commentator=\"Magen Avraham\" data-order=\"15\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"16\"></i>מחיצ' <small>[ולענין לעשותה בשבת ע\"ל ריש סי' שט\"ו] </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"18\"></i>ואם יש לו <i data-commentator=\"Magen Avraham\" data-order=\"16\"></i>בית <i data-commentator=\"Ba'er Hetev\" data-order=\"17\"></i>אחר אסור עד שיוציאנו ואם יש בו תפילין <i data-commentator=\"Magen Avraham\" data-order=\"17\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"18\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ק\" data-order=\"19\"></i>או ספרים <i data-commentator=\"Magen Avraham\" data-order=\"18\"></i>אפילו של גמרא אסור עד שיתנם בכלי בתוך כלי <i data-commentator=\"Be'er HaGolah\" data-label=\"ר\" data-order=\"20\"></i>והוא שלא יהא השני מיוחד להם <small>[וע\"ל סי' מ' סעיף ב'] </small> אבל אם הוא מיוחד להם אפילו מאה כחד חשיבי ואם פירש טלית על גבי <i data-commentator=\"Magen Avraham\" data-order=\"19\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"19\"></i>ארגז חשוב ככלי בתוך כלי:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ש\" data-order=\"21\"></i>לא ישמש בתחלת הליל' ולא בסופה <i data-commentator=\"Magen Avraham\" data-order=\"20\"></i>כדי שלא ישמע קול בני אדם ויבא לחשוב באשה אחרת אלא באמצע הלילה:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ת\" data-order=\"22\"></i>וישמש באימה ובירא' כמ\"ש על ר\"א שהיה מגל' טפח ומכסה טפח ודומה כמי שכפאו שד פי' באימה וביראה כאלו כפאו שד <i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"23\"></i>ויש מפרשים מגלה טפח ומכסה טפח שלא היה ממרק האבר בשעת תשמיש כדי למעט הנאתו ודומ' כמו שכפאו שד שעושה הדבר באונס <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"24\"></i>ויש מפרשים מגלה טפח שבאשה כלומ' עכשיו מגלה אותו לצורך תשמיש ועכשיו מכסה אות' כלומר שלא הי' מאריך באותו מעש' ודומ' לו כמו שבעתו השד ונבעת והניח המעש' כל כך היה <i data-commentator=\"Magen Avraham\" data-order=\"21\"></i>מקצר בתשמיש <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"25\"></i>ויש מפרשים מגלה טפח על הסינר שהית' חוגרת בו שאף בשע' תשמיש <i data-commentator=\"Magen Avraham\" data-order=\"22\"></i>הי' מצריכה לחוגרו ומגלה רק טפח ממנה ומכס' מיד כדי למעט הנאתו וכולהו פירושי איתנהו וצריך בעל נפש ליזהר בהם:","m":["(ו) ת\"ח - שבחול צריכים לעסוק בתורה בלילה שתורתן אומנותן ואל יאמר אדם אעשה עצמי כת\"ח כי כתיב ועונתה לא יגרע [מ\"א בשם הקנה] ור\"ל להפקיע העונה שלא ברשותה אבל ברשותה תבוא עליו ברכה [פמ\"ג] וע\"ש שמסתפק בזמנינו אם נקרא ת\"ח לזה ומ\"מ מצדד דכיון דלפי הדור הוא ת\"ח והוא נשאה ע\"ד כן לית חיוב עונה כ\"א בליל שבת ועיין בבה\"ל:","(ז) מליל שבת וכו' - יש שכתבו שה\"ה בר\"ח ויו\"ט. ולכאורה לפי טעם המ\"א הנ\"ל בסק\"ו שצריך לעסוק בתורה בלילה אין שייך לחייב אותו בר\"ח ועיין בבה\"ל. אין לשמש בליל א' של פסח וליל שבועות ושני ימים של ר\"ה וליל שמיני עצרת אם לא בליל טבילה. וכ\"ז אינו אלא לאדם שהוא מלא ביראה ולא יחטא ח\"ו אבל אלו שיצרם מתגבר עליהם והם חושבים שהוא כעין איסור תורה ועי\"ז באים ח\"ו לידי כמה מכשולים מצוה לשמש אפילו בר\"ה ויטבול למחר דמצד הדין אין איסור אלא ביוה\"כ ובט\"ב ובימי אבלות שלו או שלה [חכמ\"א]:","(ח) בליל טבילתה - ר\"ל אפילו שלא בשעת עונתה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"26\"></i>לא יספר עמה בדברים <i data-commentator=\"Magen Avraham\" data-order=\"23\"></i>שאינם מעניני תשמיש ולא בשעת תשמיש ולא קודם לכן שלא יתן דעתו באשה אחרת ואם סיפר עמה ושימש אמרו עליו מגיד לאדם מה שיחו אפילו שיחה קלה שבין אדם לאשתו מגידין לו בשעת הדין:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"27\"></i>אם הי' לו כעס עמה אסור לשמש עד שיפייסנה <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"28\"></i>ויכול לספר עמה קודם תשמיש כדי לרצות':","m":[]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"29\"></i>אסור לשמש לאור הנר <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"30\"></i>אע\"פ שמאפיל בטליתו: <small>הגה אבל אם עושה מחיצ' גבוה עשרה לפני הנר [הגהות מיי' פ\"ג מה' י\"ט] <i data-commentator=\"Magen Avraham\" data-order=\"24\"></i>אע\"פ שהאור <i data-commentator=\"Ba'er Hetev\" data-order=\"20\"></i>נראה דרך המחיצה כגון שהפסיק בסדין שרי <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>כן נ\"ל מדברי רש\"י בפרק ב' דמס' ביצה דף כ\"ב גם אמרי' התם דשרי כשכופה כלי על הנר ואם מותר לעשות מחיצה זו בשבת ע\"ל ריש סימן שט\"ו </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"31\"></i>וכן אסור לשמש ביום אא\"כ הוא בית אפל: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"25\"></i>ות\"ח <i data-commentator=\"Magen Avraham\" data-order=\"26\"></i>מאפיל <i data-commentator=\"Ba'er Hetev\" data-order=\"21\"></i>בטליתו ושרי [טור]:</small>","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"32\"></i>אסור לשמש מטתו <i data-commentator=\"Eshel Avraham\" data-label=\"ב\" data-order=\"2\"></i>בשני רעבון אלא לחשוכי בנים <small>[פירוש מי שאין לו בנים] הגה וע\"ל סי' תקע\"ד ס\"ד וה\"ה בשאר צרות שהם כרעבון [ירושלמי דתענית]:</small>","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"33\"></i>אכסנאי אסור לשמש <i data-commentator=\"Magen Avraham\" data-order=\"27\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"34\"></i>ואם יחדו לו ולאשתו בית מותר ובלבד שלא יישן <i data-commentator=\"Magen Avraham\" data-order=\"28\"></i>בטליתו של <i data-commentator=\"Ba'er Hetev\" data-order=\"22\"></i>בעל הבית:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"35\"></i>שכבת זרע הוא כח הגוף ומאור העינים וכל זמן שתצא ביותר הגוף כלה וחייו אובדי' וכל השטוף בבעילה זקנה קופצת עליו וכחו תשש ועיניו כהות וריח רע נודף מפיו ושער ראשו וגבות עיניו וריסי עיניו נושרים ושער זקנו ושחיו ושער רגליו רבה ושיניו נושרו' והרב' כאבים חוץ מאלו באים עליו אמרו חכמי הרופאים אחד מאלף מת משאר חלאי' והאלף מרוב תשמיש לפיכך צריך אדם ליזהר:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"36\"></i>לא יבעול והוא שבע או רעב אלא כשיתעכל המזון שבמעיו <i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"37\"></i>ולא יבעול מעומד ולא מיושב ולא בבית המרחץ ולא ביום שנכנס למרחץ ולא ביום הקזה <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>ולא ביום <i data-commentator=\"Magen Avraham\" data-order=\"29\"></i>יציאה לדרך או ביאה מן הדרך ולא לפניהם ולא לאחריהם: <small>[והא דבריש הסימן שחייב לפוקדה איירי כשהוא רוכב או יושב בקרון וכאן איירי <i data-commentator=\"Ba'er Hetev\" data-order=\"23\"></i>במהלך] [מהרש\"ל]:</small>","m":["(ט) לדרך - עיין לקמן בסט\"ו:","(י) מניקה - ר\"ל אף שהיא מניקה או מעוברת מ\"מ חייב לפקדה [ב\"י]:","(יא) לפקדה - היינו אפילו שלא בשעת עונתה וה\"ה ביוצא לדרך אך שם מהני מחילה דידה [פמ\"ג]:","(יב) כאדם שפורע חובו וכו' - וזה יכוין אפילו בעת עיבור ויניקה:","(יג) ויתן עיניו - פי' שיתן מחשבתו בשעת תשמיש על האחרת:","(יד) אנוסה - אפילו אינה אנוסה רק שאינה מרוצה מפני כעס שיש לה עליו לכן יפייס ואח\"כ יבעול:","(טו) שנואה - בשעת תשמיש אבל אם היא אז רצויה אע\"פ שהיא שנואה שרי [טור]:","(טז) תמורה - אפילו שתיהן נשיו וכגון שנתכוין לזו ונזדמנה לו אחרת:","(יז) מורדת - דאמרה לא בעינא לך לבעל ואעפ\"כ הוא משמש עמה אע\"פ שהיא מרוצה לו בשעת תשמיש:","(יח) שכרות - הוא או היא שכורה. ומסתברא דדוקא נתבלבל דעתו מחמת שכרות ולא בששתה רביעית [פמ\"ג]:","(יט) גרושת הלב - שבדעתו לגרשה אע\"פ שהוא אוהבה כגון מאותן שכופין להוציא:","(כ) ערבוביא - כגון שנותן אז דעתו על אחרת כמ\"ש ס\"ב:","(כא) חצופה - שתובעתו בפה אבל אי מקשטת עצמה ומרצה אותו שיתן דעתו עליה אדרבה אז חייב בעונה כדלעיל בס\"א והו\"ל בנים מהוגנים. וכל אלו הדברים הנזכרים כאן צריך ליזהר אפילו כשהיא מעוברת או זקנה שאינה ראויה לילד [פמ\"ג]. כתבו האחרונים דיש ליזהר מלבוא על אשתו כשהיא ישנה:","(כב) ואפילו ע\"י הפסק וכו' - הטעם דמרגיש הוא בעת שהלה משמש מטתו ואין כאן צניעות. ואם הוא בענין שאין מרגישים כלל מותר ע\"י הפסק מחיצה [אחרונים]:","(כג) העשויים בגלילה - ר\"ל שהן כתובין בקלף כמו ספר תורה אלא שיש בהן רק חומש התורה וה\"ה שאר כתבי קודש כשהן עשויין בגלילה:","(כד) עד שיהיה וכו' - ר\"ל אפילו היא מונחת בארגז וע\"ג הארגז יש עוד כיסוי דלגבי תפלין ושאר ספרים מהני וכדלקמיה בס\"ת אסור עד שיהיה מחיצה מפסקת וכשיש מחיצה אפילו אינה מונחת בארגז כלל ג\"כ שרי:","(כה) מחיצה - ומה שפרוש וילון סביב המטה אינה בכלל מחיצה [ואפילו הוילון הוא גבוה הרבה שאין הספר נראה עי\"ז והס\"ת מונחת בארגז ובכמה כיסויין על הארגז ג\"כ אסור] שהוילון נע ונד ע\"י רוח. כתב המ\"א אם יש נקבים וחלונות במחיצה כעין סריגה אסור עד שיהיו הספרים מכוסים מן העין שאין נראין ובספר נהר שלום מפקפק על דבריו וכן בספר תוספת ירושלים ובמקום הדחק יש לסמוך ע\"ז אכן לכתחלה טוב לכסות שלא יהיו הספרים נראין ובפרט ס\"ת בודאי יש להחמיר:","(כו) בית אחר - פי' חדר אחר:","(כז) תפילין - וה\"ה מזוזה ועיין לעיל בסימן מ' במ\"ב שם ביארנו כל פרטי הדינים:","(כח) או ספרים - ר\"ל כ\"ד ספרי קודש ומיירי שאינם עשויין בגלילה דאי עשויין בגלילה דינם כס\"ת וכנ\"ל:","(כט) אפילו של גמרא - ר\"ל אע\"ג דגמ' לא ניתן לכתוב בדורות הראשונים משום דדברים שבע\"פ אסור לאומרם בכתב אפ\"ה כיון דלבסוף התירו האמוראים לכתוב משום עת לעשות לה' הו\"ל כשאר ספרי קודש וממילא היום ה\"ה כל הספרים הן בכתיבה או בדפוס יש בהן קדושה [פמ\"ג]:","(ל) עד שיתנם וכו' - ר\"ל אע\"ג דלא בעינן בהו הפסק מחיצה כמו בס\"ת מ\"מ כלי בתוך כלי בעינן. וכתבו האחרונים דוילון התלוי לפני המטה אף דאין שם מחיצה עליה כיון דאינה קשורה לצד מטה והיא נע ונד ע\"י רוח ואין זה נחשב הפסק לענין ס\"ת וכנ\"ל בסקכ\"ה מ\"מ שם כיסוי יש עליה אם אין הספרים נראין עי\"ז וע\"כ אם יכסה על הספרים אפילו רק בכיסוי אחד מותר דתו הוי שני כיסויין וככלי בתוך כלי דמיא:","(לא) בכלי תוך כלי - וה\"ה שני כיסויין. ומה שנוהגין איזה אנשים שתולין נגד הספרים וילון לכסותם וסוברים שבזה לבד די לאו שפיר עבדי דזה הוי רק כיסוי אחד ובעינן עוד כיסוי אחר שיכסה אותן לבד זה:","(לב) טלית ע\"ג ארגז - ר\"ל אע\"ג דהטלית אינו פרוש רק מלמעלה ולא מלמטה אפ\"ה נחשב כאלו היה מונח בכלי תוך כלי:","(לג) חשוב וכו' - ואם הארגז גדול שמחזיק ארבעים סאה והוא אמה על אמה ברום שלש אמות חולקת רשות לעצמה וא\"צ לפרוס עוד כסוי על הארגז ויש מחמירין בזה אכן אם מחובר לכותל במסמרין לכו\"ע יש להקל:","(לד) בתחלת הלילה וכו' - ואם רואה שיצרו מתגבר עליו ובא לידי הרהורים ויכול לבוא לידי טומאה עי\"ז לא יחמיר בזה [אחרונים]:","(לה) מקצר וכו' - עיין במ\"א מש\"כ בזה:","(לו) וצריך וכו' - כתבו התוספות [נדה י\"ז] בשם המדרש דהקב\"ה שונא המשמש ערום. ודוקא ערום ממש ומשום דיש לו לאדם להיות צנוע אבל אם מכסה עצמו מלמעלה ליכא שום חשש בדבר:","(לז) שאינם וכו' - ואם היה לו כעס עמה מותר לספר עמה מתחלה כל דברי ריצוי כדי לפייסה וכדלקמיה [פמ\"ג]:","(לח) מעניני וכו' - ולפעמים אפילו מעניני תשמיש ג\"כ יש ליזהר שלא לספר מתחלה כגון שהוא איש מחומם ויכול לבוא עי\"ז לידי חטא [אחרונים]:","(לט) לאור הנר - ואפילו אין שם אלא קצת אור כגון שדולק הנר בתוך השפופרת שהנר מונח בתוכו או שמאיר קצת דרך לאנטערנ\"ע [אחר שאין שם מחיצה המפסקת] וה\"ה לאור הלבנה ג\"כ אסור ודוקא אם אור הלבנה מאיר עליהם להדיא אבל אם אינה מאירה עליהם אע\"פ שמאירה לבית מותר [ומ\"מ נכון שיאפיל בטליתו] ואם הם תחת אויר השמים אפילו אין אור הלבנה עליהם ממש אלא הם בצלה אפ\"ה אסור. והיינו אפילו יש שם מחיצות סביבם דבמקום מגולה שאין שם מחיצות בלא\"ה אסור לשמש כמבואר באה\"ע סימן כ\"ה ס\"ד:","(מ) מחיצה גבוה עשרה - ומיירי שקשר אותה מלמטה שלא ינוד ברוח מצויה דאל\"ה אין דין מחיצה עליה:","(מא) אע\"פ שהאור נראה וכו' - וה\"ה אם האור נראה למעלה מהמחיצה שרי כיון שהיא מחיצה גמורה. וכ\"ז דוקא כשמאפיל בטליתו אבל בלא\"ה אסור דמאחר שהחדר מלא אור לא עדיף מביום ויש שמחמירין אפילו ע\"י האפלת טלית כיון שמ\"מ האור נראה באותו חדר:","(מב) דרך המחיצה - וכ\"ש אם הנר בחדר אחר ומאיר לחדר זה דשרי וכתב בחכ\"א דמ\"מ צריך האפלת טלית:","(מג) כשכופה כלי - עיין לקמן בסוף סימן רע\"ז בט\"ז ומ\"ב שם:","(מד) ביום - דאין זה דרך צניעות:","(מה) ות\"ח - שהוא צנוע בדרכיו ולא יבוא להסתכל ע\"כ מותר ע\"י האפלת טלית אבל מ\"מ אין להקל בדבר זה אלא לצורך גדול דהיינו כשיצרו מתגבר עליו:","(מו) אלא וכו' - ואם יצרו מתגבר עליו ויש חשש שיבוא לידי השחתת זרע כתב א\"ר בשם ספר דברי דוד בסימן תקע\"ד להקל וכ\"כ בספר בית מאיר לאה\"ע:","(מז) שאין לו בנים - ר\"ל שלא קיים עדיין פ\"ו =פריה ורביה= ולכן אפילו יש לו בנים אם אין לו עדיין בת מותר:","(מח) וע\"ל סי' תקע\"ד - ר\"ל דמתיר שם המחבר גם בליל טבילה וע\"ש באחרונים:","(מט) אכסנאי וכו' - היינו אפילו כשהבני בית כולם ישנים:","(נ) ואם יחדו וכו' - היינו שאין לבעה\"ב עסק באותו מקום אלא מיוחד לשניהם לבדם דאז הו\"ל הוא כבעה\"ב:","(נא) בית - וה\"ה חדר:","(נב) בטליתו של בעה\"ב - שמא יראה קרי עליו. איתא בעירובין ס\"ג הישן בקילעא [בחדר] שאיש ואשתו ישנים שם עליו הכתוב אומר ואת נשי עמי תגרשון מבית תענוגיה ואפילו כשהיא נדה והובא בחידושי רע\"א:","(נג) ולא ביום הקזה - מי שחלה ונתרפא יזהר מלשמש עד שיתחזק גופו כי יכאיבהו ויחליאהו ולא ידע כי בנפשו הוא [א\"ר בשם צ\"ל]:","(נד) במהלך - ומ\"א כתב דכאן איירי מצד הרפואה ובס\"א איירי מהדין ותדע דהא קאמר נמי ולא ביום שנכנס למרחץ ולא לפניהם ולא לאחריהם וידוע דמצוה לרחוץ בכל ע\"ש ועונת ת\"ח משבת לשבת אע\"כ דכל זה רק מצד רפואה הוא. היוצא מבהכ\"ס קבוע [דהיינו שיש שם מקום מושב לאפוקי בהכ\"ס עראי] אל ישמש מטתו עד שישהה שיעור חצי מיל לפחות מפני ששד של בהכ\"ס מתדבק בו [גיטין דף ע'] וכ\"כ גם בסדה\"י בשם הזוהר אלא דהוא כתב שלא ישמש מטתו כל אותה שעה ועיין ביד אפרים דגם כונת הזוהר לאו דוקא שעה ממש אלא ר\"ל זמן מה ע\"ש. כתב בבדק הבית בשם הזוהר והביאוהו האחרונים דאשה מינקת לא תשמש אלא בשעה שהתינוק ישן ואחר התשמיש לא תניק את הילד עד אחר שיעור הילוך שני מילין ואם התינוק בוכה תמתין לפחות שיעור מיל. ואשה שמאחרת טבילתה לצער בעלה עבירה גדולה בידה וגורמת כמה רעות [זוהר]. כ' בס\"ח אסור להזכיר השם וכל דבר שבקדושה כשעדיין שכבת זרע עליו רק ישטוף מים על מקומות שטינף עצמו. וכתבו הספרים שתמיד יהא אצל מטתו כלי מים ויטלו ידיהם קודם התשמיש ואחריו. וכשמתעורר בקישוי אבר בחלום יזהר שלא לבעול אז כי הבנים יהיו פגומין ח\"ו ואף אם היא מעוברת תלד רוחין בישין [האר\"י ז\"ל]. יש ליזהר מלשום ספר על מטה שישן עליה ובפרט עם אשתו כי שכבת זרע מצוי עליו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"38\"></i>המשמש מטתו על מטה שתינוק <i data-commentator=\"Ba'er Hetev\" data-order=\"24\"></i>ישן עליה אותו תינוק נכפה ולא אמרן אלא דלא הוי בר שתא אבל הוי בר שתא לית לן בה ולא אמרן אלא דגני להדי כרעיה <small>[פי' שישן לרגליו] </small> אבל גני להדי רישיה לית לן בה ולא אמרן אלא דלא מנח ידיה עליה אבל מנח ידיה עליה לית לן בה:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"39\"></i>מטה שישן <i data-commentator=\"Ba'er Hetev\" data-order=\"25\"></i>בה <i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"40\"></i>עם אשתו צריך שתהא ראשה ומרגלותיה זה לצפון וזה לדרום:","m":["(נה) זה לצפון וכו' - עיין לעיל בסימן ג' ס\"ו ובמ\"ב שם:"]}],"241":[{"s":"<b>שלא להשתין ערום בפני מטתו. ובו סעיף אחד:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>אחד מהדברים ששונא הקב\"ה <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>המשתין בפני מטתו <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>ערום <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>המשתין לפני מטתו ערום מביא לידי <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>עניות ולא אמרן אלא דמהדר אפיה לפוריא <small>[פי' למטה] </small> אבל <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>לבראי לית לן בה <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>ודמהדר אפיה לפוריא נמי לא אמרן אלא בארעא אבל <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>במנא לית לן בה:","m":["(א) ששונא הקב\"ה וכו' - מפני שרצון הקב\"ה שיהיה האדם מתנהג בדרך נקיות וקדושה וזה מתנהג עצמו בדרך מיאוס וטינופת ולא יוכל להשרות שכינתו אצלו:","(ב) בפני מטתו - ומכ\"ש אם משתין מים לפני מקומות אחרים שצריכים להתנהג יותר בנקיות כגון לפני שלחנו וכיב\"ז:","(ג) ערום - לאו דוקא ערום אלא ה\"ה אם היה לבוש אלא אורחא דמלתא נקט מתוך שהוא ערום אינו יוצא לחוץ להשתין:","(ד) המשתין וכו' - קיצור לשון הוא וכונתו עוד אחז\"ל המשתין וכו':","(ה) לידי עניות - דאמרינן בערבי פסחים קי\"א דשרא דעניותא נבל שמיה ואוהב לשרות במקום מיאוס [ומשו\"ה קרי ליה נבל שחפץ לנבל את עצמו] ומשתין לפני מטתו היינו מיאוס:","(ו) לבראי וכו' - שהקלוח הולך וניתז למרחוק וממילא באשה אסור אפילו בכה\"ג [מ\"א]:","(ז) במנא וכו' - ומ\"מ ת\"ח צריך שיכפה עליו כלי מלמעלה דא\"א לו לת\"ח בלא הרהור תורה:","(ח) לית לן בה - וכשרוצה לברך אח\"כ ברכת אשר יצר יטול ידיו וגם יחגור עצמו כדי שלא יהא לבו רואה את הערוה וירחיק את עצמו כדין ממקום המי רגלים אם אין הכלי מכוסה כדין:"]}],"242":[{"s":"<b>להזהר בכבוד שבת. ובו סעיף אחד:</b><br><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>אפילו מי שצריך לאחרים אם יש לו מעט משלו צריך לזרז עצמו <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i><i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>לכבד את <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>השבת ולא <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>אמרו עשה שבתך חול ולא תצטרך לבריות אלא למי <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>שהשעה דחוקה לו <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>ביותר על כן צריך לצמצם בשאר ימים כדי לכבד את השבת <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>מתקנת עזרא שיהיו מכבסים בגדים בחמישי בשבת מפני <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>כבוד השבת: <small>הגה <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>נוהגין ללוש כדי שיעור חלה <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>בבית <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>לעשות מהם לחמים לבצוע עליהם בשבת ויום טוב [סמך ממרדכי ריש מסכת ר\"ה] והוא מכבוד שבת ויום טוב ואין לשנות יש שכתבו שבקצת מקומות נהגו לאכול מולית\"א שקורין פשטיד\"א בליל שבת זכר למן שהיה מכוסה למעלה [מהרי\"ל ולא ראיתי לחוש לזה]:</small>","m":["(א) אפילו וכו' - הנה עיקר מצות עונג שבת נתפרש לנו על ידי הנביאים וכמו שנאמר וקראת לשבת עונג ויש פוסקים שס\"ל דעיקרו הוא מן התורה שהשבת הוא בכלל מקראי קודש שנאמר וביום השביעי שבת שבתון מקרא קודש וגו' ומקרא קודש פירשו חז\"ל בספרא דהיינו לקדשו ולכבדו בכסות נקיה ולענגו בעונג אכילה ושתיה והפליגו חז\"ל [בשבת קי\"ח] מאד במצוה זו ואמרו דכל המענג את השבת נותנין לו נחלה בלי מצרים וניצול משעבוד מלכיות וזוכה עבור זה לעשירות ועי\"ש עוד כמה מאמרים בענין זה. והנה בגדר מצוה זו יש ג' מאמרי חז\"ל בזה א) הא דאמרו דצריך לענגו בדגים גדולים וראשי שומן ותבשיל של תרדין שזה היה מאכל חשוב בזמניהם וכן בכל מקום ומקום לפי מנהגו יענגוהו במאכלים ומשקים החשובים להם עונג [ולפי שמן הסתם רוב בני אדם עיקר ענוגם בבשר ויין ומגדנות לכך איתא בסימן ר\"נ ס\"ב דירבה בבשר ויין ומגדנות כפי יכלתו]. ב) הא דאמרו דאפילו דבר מועט שעשאו לכבוד שבת קיים מצות עונג שבת ואפי' כסא דהרסנא (היינו דגים קטנים מטוגנין בשמנן) ג) הא דאמר ר\"ע עשה שבתך חול ואל תצטרך לבריות וחילוק כל אלו המאמרים הוא באופן זה דהיינו למאן דאפשר ליה צריך לכבדו כפי יכלתו ומי שהשעה דחוקה לו ביותר היינו שאין לו רק מזון ב' סעודות לשבת בזה אמר ר\"ע עשה שבתך חול ואל תצטרך לבריות ואינו מחויב לא בג' סעודות ולא בכסא דהרסנא ומי שיש לו ממון כדי לקנות מזה מזון ג' סעודות ויותר מזה קצת מחויב להוציא אותן על שבת כדי שיקיים ג' סעודות וכסא דהרסנא וה\"ה מי שאין לו כלום והוא מוטל הכל על הצדקה הרי הגבאים מחויבים ליתן לו ג' סעודות וכסא דהרסנא עכ\"פ ובאדם נכבד הכל לפי כבודו וכמו שנתבאר ביו\"ד בסי' רנ\"ג. ולא אמרינן בזה עשה שבתך חול ואל תצטרך לבריות דלא אמרינן הכי אלא במי שעדיין לא נצטרך ליטול אבל מי שכבר בא לידי מדה זו לפשוט ידו וליטול נותנים לו הכל כנ\"ל [ובמקומות שנוהגין הגבאים לקבוע לעניים רק שתי סעודות ולא הסעודה ג' לאו שפיר עבדי ועכ\"פ בימות הקיץ בודאי יזהרו בזה] ולזה בא השו\"ע לומר דאם יש לו גם מעט משלו צריך לדחוק עצמו לכבד ולענג שבת כראוי כיון דאפשר לו ויש בידו להוציא ע\"ז ולא סגי בכסא דהרסנא לחוד ולזה סיים דיצמצם בשאר ימים מהוצאותיו כדי שיהא נשאר לו זה לכבוד שבת. ועיין בט\"ז ותוספות שבת ושארי אחרונים שכתבו דאף מי שהשעה דחוקה לו ביותר דהוא פטור מדינא מסעודה ג' וכסא דהרסנא מ\"מ נכון מאד שיראה להשתדל להיות עכ\"פ מן הכת האמצעית דהיינו בקיום ג' סעודות וכסא דהרסנא:","(ב) לכבד את השבת - וטוב ליזהר שלא יפחות משני תבשילין גם טוב שיאכל בכל סעודה מג' סעודות דגים אם לא שאין נאותים לו לפי טבעו או ששונאן ושבת לעונג ניתן ולא לצער וכדלקמן בסי' רפ\"ח אם מוכרי הדגים מייקרין השער נכון לתקן שלא יקנו דגים איזה שבתות עד שיעמוד השער על מקומו והנה בבה\"ט הביא דלא יעשו תקנה רק אם הוסיפו המקח יתר על שליש מכמו שהיה מקדם אבל בא\"ר ובפמ\"ג כתבו דאף פחות משליש יוקר יש לעשות תקנה משום עניים. עוד כתב שם דאין בזה משום בטול מצות עונג דיש לענג השבת במאכלים אחרים. אם תקנו לאסור לאכול דגים כמה שבתות ואחד קנה מקודם מותר:","(ג) למי שהשעה וכו' - ומיירי כשאין לו משכונות ללות עליהם ובלא משכון אין יכול להשיג דאל\"ה צריך ללות כדי שלא לבטל מצות עונג שבת וכמו שאחז\"ל שאומר הקב\"ה בני לוו עלי ואני פורע:","(ד) כדי לכבד השבת - דבמזונות של שבת ויו\"ט אם מוסיף מוסיפין לו וכמו שאחז\"ל כל מזונותיו של אדם קצובין לו מר\"ה ועד ר\"ה ויש ליזהר שלא יוסיף בהן פן לא קצבו לו כ\"כ חוץ מהוצאות שבת ויו\"ט והוצאות בניו לת\"ת שאם מוסיף מוסיפין לו [טור] לוין ברבית לצורך סעודת שבת או סעודת מצוה והיינו מא\"י או מישראל בדרך היתר. אם שלחו לו דבר מאכל שיאכלנו בשבת לא יאכלנו בחול כ\"כ בס\"ח ועיין לקמן בסימן תרצ\"ד ס\"ב דדעת הש\"ע שם דהעני יכול לשנות במגבת פורים למה שירצה אף דגבוהו לצורך פורים אכן גם שם יש מחמירין בזה עיין בטור שם:","(ה) מפני וכו' - היינו כדי שיהיו לבנים לשבת אבל לא בע\"ש כדי שיהיו פנוים להתעסק בצרכי שבת ולפ\"ז צריך ליזהר שלא לילך בחלוק אחד כמה שבתות כדי שלא לעבור על תקנות עזרא:","(ו) כדי שיעור חלה - היינו מלבד שהלישה והאפיה הוא מכלל כבוד שבת ויו\"ט כמו שמסיים לבסוף עוד יש בזה טעם כדי לקיים מצות חלה לפי שאיבדה את אדה\"ר שהיה חלתו של עולם שנברא בע\"ש ועיין באחרונים דאפילו הנוהגין לאכול פת פלטר של א\"י בחול מ\"מ בשבת ויו\"ט נכון ליזהר שלא לאכול כ\"א מפת ישראל מפני כבוד השבת ויו\"ט. ופשוט דאם הוא אנוס שאין לו על מה לקדש כ\"א על פת של אינם יהודים כמו שמצוי לאנשי חיל העברים יכול לקדש עליו:שהיה מכוסה למעלה ולמטה - בטל ואף זה מכוסה הבשר בין דפי העיסה:","(ז) ולא ראיתי וכו' - ובמקומותינו המנהג לאכלן [שכנה\"ג]:"]}],"243":[{"s":"<b>דין המשכיר שדה ומרחץ לעכו\"ם. ובו ב סעיפים:</b><br><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i> <i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>לא ישכיר אדם מרחץ שלו לעכו\"ם <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>מפני שנקרא על <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>שמו ועכו\"ם זה עושה בו מלאכה בשבת דסתם מרחץ לאו לאריסותא <small>[פירוש אריס הוא העובד ליקח חלק ממה שישביח לבעליו] </small> עביד ואמרי שכל הריוח של ישראל <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>ושכר את העכו\"ם בכך וכך ליום ונמצא שהעכו\"ם עושה מלאכה בשליחותו של ישראל אבל <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>שדה מותר שכן דרך לקבל שדה באריסות ואף ע\"פ שיודעים שהוא של ישראל אומרים העכו\"ם לקח' באריסו' ולעצמו הוא עובד <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>ותנור דינו <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"2\"></i>כמרחץ ורחיים דינו כשדה: <small>הגה ואע\"פ שלא לקחה העכו\"ם <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>רק לשליש או לרביע ויש לישראל הנאה במה שהעכו\"ם עובד בשבת שרי דעכו\"ם אדעתא דנפשיה עובד. [ב\"י בשם מיי' פ\"ז וב\"י סי' רמ\"ה בשם סה\"ת]:</small>","m":["לא ישכיר. דע ששלושה חילוקים יש אחד הוא אריסות ששוכר לא\"י שיעשה המלאכה בשדה או במרחץ והרווחים או הפירות יחלוקו. הב' הוא שכירות שא\"י נוטל כל הרווחים או הפירות ונותן לישראל עבור שדהו ומרחצו דבר קצוב לכל שנה. הב' חילוקים אלו מותרים בשדה לגמרי ובמרחץ רק מדינא דא\"י אדעתיה דנפשיה עביד אלא שחכמים אסרו אלו הב' חלוקים במרחץ משום מראית העין מפני דנקראת על שמו ויבואו לחשדו שעושה בשליחותו אבל החלוקה הג' דהוא קבלנות דהיינו שיהיו כל הרווחים לישראל רק שישראל נותן לא\"י דבר קצוב לכל שנה עבור פעולתו זהו ודאי אסור מדינא במרחץ דהוי הא\"י שלוחו של ישראל וישראל נהנה ממלאכה בשבת דאם לא יעשה יום אחד יפסיד הישראל ריוח אותו יום וע\"כ אם מנהג רוב אנשי המקום להשכירם או ליתנם באריסות כמבואר בס\"ב חזר להיות המרחץ כשדה הב' חילוקים ראשונים מותר והחלוקה הג' אסור. וכל היתר שכירות דכאן היינו שהוא משכירו דרך הבלעה עם ימות החול אבל ליום השבת לחוד אסור אפילו בשדה וגם נתפרסם זהו עיקרי הדינים שבסימן זה בקצרה:","(א) מרחץ שלו - בין שבנהו בעצמו או אפילו קנה וישב בה ונקרא שמו עליו:","(ב) לא\"י - וכ\"ש לישראל מומר דעובר נמי משום לפני עור לא תתן מכשול וטעם זה שייך אף בשדה ובכל דבר:","(ג) מפני שנקרא - פירוש דמדינא שרי להשכירו לא\"י לשנה או לחודש שיתן לו כך וכך בין יסיק בו הא\"י בין לא יסיקנו וכל הריוח יהיה לא\"י דאיסור שכר שבת ליכא דהא מושכרת היא לו לשנה ואיסור דאמירה לא\"י בודאי לא שייך בשכירות דלנפשיה הוא עושה ואפילו אם יש לו לא\"י רק חלק בריוח המרחץ גם כן אמרינן אדעתיה דנפשיה עביד כמש\"כ בסוף הסעיף אלא שאסור בכל זה מפני מראית העין שנקראת על שמו של ישראל ויאמרו הבריות דשכיר יום הוא ושלוחו הוא ודוקא כשמשכירו לשנה או לחודש אבל להשכירה לא\"י לימים שיתן לו הא\"י כל יום ויום שיסיקנו כך וכך אף דגם זה אדעתיה דנפשיה עביד מ\"מ מדינא אסור דהוי כשכר שבת ועיין לקמן בסימן רמ\"ד דדבר האסור מפני מראית עין אינו אסור אלא בתוך התחום של ישוב ישראל:","(ד) דסתם מרחץ - פי' דכתב להלן דשדה מותר להשכירו מטעם זה שיתלו באריסות וע\"ז קאמר דבמרחץ ליכא האי טעמא להתיר דאין דרך ליתנו באריסות ולא יתלו ג\"כ שהשכירו כפי האמת דלא שכיח:","(ה) בשליחותו של ישראל - וזהו איסור גמור כמו שאמרו בכמה מקומות דאמירה לא\"י שבות ואסמכוהו אקרא דכל מלאכה לא יעשה בהם ולא כתיב לא תעשה לרמז דאפילו ע\"י אחרים לא יעשה ואפילו כשעושה בעצמו מלאכה של ישראל בשבילו ג\"כ צריך למחות בידו:","(ו) שדה מותר - להשכירה לא\"י בדבר קצוב דאף דנקראת נמי על שמו כמו מרחץ דכל מחובר סתמא שם בעליו עליו ולהשכיר נמי לא שכיח כל כך מ\"מ מותר דלא יחשדוהו בשכיר יום כדמפרש שכן דרך וכו' ולפיכך יתלו באריסות ואריסות שרי דאדעתיה דנפשיה עביד כדלקמיה בהגה\"ה:","(ז) ותנור - להשכיר תנורו לאפות בו דינו כמרחץ דתנור נמי אין דרך להשכירו וליתנו באריסות כמו מרחץ ויחשדו דשכיר יום הוא אצלו:","(ח) ורחיים וכו' - משום דדרכו ליתנו באריסות כמו שדה ולפיכך להשכירו נמי מותר וכדלעיל. ועיין בר\"ן דמשמע דאם אין דרך אנשי אותו המקום ליתן רחיים באריסות דינו כמו מרחץ לאיסור דבאמת תלוי בכל אלו הדברים לפי מנהג המדינה בין להקל בין להחמיר וכדלקמיה בס\"ב:","(ט) ואע\"פ וכו' - אשדה וריחיים קאי דהמחבר מיירי בשכירות והוא מוסיף דאף אריסות מותר והמחבר ג\"כ ס\"ל כן דמטעם זה התיר בשכירות כנ\"ל אלא שהוא ביאר בהדיא:","(י) רק לשליש וכו' - ודוקא בזה שנותן לאינו יהודי חלק בתבואה אבל אם שכר האינו יהודי לעבוד בו כל השנה ושיטול היהודי כל התבואה מהשדה אף דמדינא בזה ג\"כ שרי דהאינו יהודי אדעתיה דנפשיה עביד דאף אם לא יזבל ויחרוש ויקצור השדה בשבת יכול לעשות בחול וממהר בשביל עצמו מ\"מ אסור דיבאו לחשדו בשכיר יום ולא יתלו באריסות כשיראו לבסוף שאין לו שום חלק בפירות הארץ וכדלקמן בריש סימן רמ\"ד ודע דבמרחץ כה\"ג דהיינו ששוכר אינו יהודי לעבוד בו כל השנה ושיטול היהודי כל הריוח של השבתות מדינא אסור וה\"ה בריחיים באופן זה דהא דשרינן מתחלה מדינא היינו דוקא בשדה וכדומה דהמלאכה קצובה ואפשר להשלימה בכל עת דאין ריוח לישראל במה שעושה האינו יהודי בשבת דאם לא יעשה היום יעשנה ביום אחר אז אמרינן אדעתיה דנפשיה עביד אבל במרחץ וריחיים דהמלאכה אינה קצובה וכל יום ריוח לעצמו דאם לא יעשה יום אחד יפסיד הישראל אותו היום א\"כ עיקר המלאכה בשביל ישראל הוא ומדינא אסור כמו שכיר יום דאף דמקבל שכר לא אמרינן אדעתיה דנפשיה עביד הואיל ונהנה הישראל ממלאכת שבת [ואפילו להט\"ז לקמן בסימן רמ\"ד סק\"ה דמתיר להרמב\"ם נראה דאסור ג\"כ בזה מדינא דרגילות להקפיד על האינו יהודי כשמבטל איזה יום]. וכיון דמדינא אסור אפילו נתפרסם ששכרו לשנה וגם הוא חוץ לתחום דאין בו משום מראית העין ג\"כ אסור ואין היתר כ\"א היכא דיש לאינו יהודי קצת חלק בריוח השבתות דאז אמרינן דאדעתיה דנפשיה עביד ומותר בריחיים וגם במרחץ במקום שנתפרסם הדבר וכבסעיף ב' וכ\"ש שמותר היכא שמוכרו לו לגמרי בכל ע\"ש:","(יא) מותר וכו' או ליתנם וכו' - דתו ליכא חשדא ואף דאין דרך אותו המקום ואותו האיש רק להשכיר מ\"מ מותר גם באריסות דיתלו דהשכירו לו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>אפילו מרחץ או תנור אם השכירם שנה אחר שנה ונתפרסם הדבר ע\"י כך שאין דרכו לשכור פועלים אלא להשכירם <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>וכן אם מנהג רוב אנשי אותו המקום להשכירם או ליתנם באריסות <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>מותר להשכיר' לעכו\"ם או ליתנם לו באריסות: <small>הגה ואפילו במקום האסור אם אין המרחץ או התנור של ישראל <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>רק שכרם <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>מעכו\"ם וחזר והשכירם לעכו\"ם שרי דאין שם הישראל נקרא עליו [א\"ז בשם גאונים] וכן אם יש מרחץ בבית דירה ואין רוחצין במרחץ <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>רק <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>אותן <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"3\"></i>שבביתו והם יודעים ששכרו עכו\"ם שרי [ב\"י בשם מהרי\"א ור\"ח וא\"ז] ואם <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>עבר והשכירו במקום האסור י\"א ששכרו מותר [ב\"י בשם הגאוני'] <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>וי\"א שאסור [מרדכי פ\"ק דשבת וכן עיקר] [וע\"ל ס\"ס רמ\"ה]:</small>","m":["(יב) רק שכרם - בב\"י הביא בשם תשובת הגאונים דה\"ה אם קנה מאינו יהודי ותיכף קודם שישב בה השכירם דלא נקרא שמו עליו ויש לסמוך ע\"ז [מ\"א וש\"א]:","(יג) מאינו יהודי - דאם היה של ישראל נראה דאסור דעי\"ז יחשדו אותו ישראל בעל המרחץ שהאינו יהודי הוא שכיר יומו:","(יד) וחזר והשכירם - י\"א דבשכירות נמי אינו מותר אלא כשלא ישב בה הישראל כמש\"כ הב\"י בקנה אבל הא\"ר ושארי אחרונים כתבו דבשכרו מאינו יהודי אף שישב בה הישראל מותר להשכירה לאינו יהודי דלא נקרא שמו עליו:","(טו) בבית דירה - היינו שהמרחץ אינו בר\"ה רק בחצירו באחד מהבית דירה שלו ולכך אם אין רוחצין בו בחול אלא אותן שבביתו שרי דאנשים אחרים לא ידעו אם יש שם מרחץ ואותן שבביתו היודעים מזה גם הם יודעים שהשכירו לא\"י אבל כשרוחצין בו גם אנשים אחרים הלא נתפרסם שיש שם מרחץ ואותו המרחץ נקרא מכבר על שם ישראל וכשיראו אח\"כ שעשן יוצא ממנו בימי השבת יתלו דבשליחותו הסיקו הא\"י וכ\"ז כשהוא בבית דירה שלו אבל אם הוא עומד בר\"ה במקום רואים אז אפילו אם אינם רוחצין בו רק אותן שבביתו מ\"מ אסור דהא הכל יודעים שיש שם מרחץ ואין הכל יודעים שהשכירו לאינו יהודי כן כתבו הרבה אחרונים ויש מקילין עוד דאם הוא עומד ברשות אחר בפ\"ע שלא בחצירו אז אפילו רוחצין בו גם אנשים אחרים אפ\"ה שרי דמסתמא אין הכל יודעים שהוא שלו רק אותן השכנים של המרחץ ומסתמא נתודע להם גם את זה שהשכירו לא\"י:","(טז) י\"א ששכרו מותר וכו' - והאחרונים הסכימו דלא פליגי דבמקום דמותר מדינא כגון שהשכיר המרחץ לאינו יהודי לשנה או לחודש דמשום שכר שבת ליכא דהלא הוא בהבלעה ואינו אסור אלא משום מראית העין כנ\"ל בס\"א לכן בדיעבד מותר לקבל השכר מהאינו יהודי משא\"כ אם השכירו לימים דמדינא אסור משום שכר שבת לכן אפילו הביא האינו יהודי מעצמו מעות אסור לקבל הימנו כמ\"ש בסימן רמ\"ה ס\"ו וע\"ש מה שכתבנו במ\"ב ואם המלאכה מוטלת על ישראל עיין ריש סימן רמ\"ה: "]}],"244":[{"s":"<b>איזו מלאכות יכול העכו\"ם לעשות בעד הישראל. ובו ו סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>פוסק אדם <small>[פי' מתנה] </small> עם העכו\"ם על המלאכה וקוצץ דמים והעכו\"ם <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>עושה <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>לעצמו ואע\"פ שהוא עושה בשבת מות' בד\"א בצנעא <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>שאין מכירי' הכל שזו המלאכ' הנעשית בשבת של ישראל היא אבל אם היתה ידועה ומפורסמת אסו' שהרוא' את העכו\"ם עוסק אינו יודע שקצץ <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>ואומ' שפלוני שכר <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>העכו\"ם לעשות בו מלאכ' בשבת לפיכך הפוסק עם העכו\"ם <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>לבנות לו <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"3\"></i>חצירו או כותלו <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>או <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i><i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>לקצור לו שדהו <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>אם היתה המלאכ' במדינה או בתוך התחום אסו' לו להניח לעשו' לו מלאכ' בשבת מפני הרואי' שאינם יודעים שפסק: <small>הגה <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>ואפי' אם דר בין העכו\"ם יש לחוש <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>לאורחי' הבאים שם או <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"5\"></i>לבני ביתו שיחשדו אותו [ב\"י בשם תשובת אשכנזים] </small> ואם היתה המלאכה <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>חוץ לתחום וגם אין עיר אחרת בתוך תחומו של מקום שעושין בו מלאכ' מותר ועכו\"ם שהכניס צאן של ישראל לדיר שדהו <small> (ע\"ל סי' תקל\"ז סעיף י\"ד):</small>","m":["(א) וקוצץ דמים - היינו קבלנות שמתנה עמו שיעשה לו איזה מלאכה בשכר דבר קצוב ואם עושה לו בטובת הנאה עיין לקמן בסימן רמ\"ז ס\"ד ובסימן רנ\"ב ס\"ב:","(ב) מותר - דכיון שקצץ אדעתיה דנפשיה קעביד למהר להשלים מלאכתו דלישראל אין קפידא בזה דאם לא יעשהו היום יעשהו למחר דאם קובע לו מלאכתו בשבת אסור כדלקמן סימן רמ\"ז ס\"א:","(ג) בצינעה - היינו שהיא מלאכת צינעה לפי שאין הכל מכירין שהיא של ישראל וכמו שמפרש אבל אה\"נ דאפילו אם הוא עושה אותה בפרהסיא שרי כיון דהמלאכה עצמה אין ידוע שהיא של ישראל:","(ד) שאין מכירים הכל - ואפילו אם קצת יודעים שהיא מלאכת ישראל שרי ואף על גב דמבואר לקמן בהג\"ה דיש לחוש לאורחים ובני ביתו שיחשדו אותו שם שהיא מלאכת מחובר וסתם מחובר שם בעליו נקרא עליו החמירו בו ביותר:","(ה) לפיכך וכו' - ר\"ל דסתם מחובר הוי כאלו ידוע ומפורסמת שהיא של ישראל:","(ו) חצירו או כותלו - ואפילו אם הוא עומד במקום שאין ידוע שהוא שלו ג\"כ אסור דיש לחוש לשכניו שיודעים שהוא שלו ויחשדוהו ששכירו הוא לימים [מ\"א וש\"א]:","(ז) לקצור לו שדהו - ואע\"ג דדרך שדה לאריסות וא\"כ יסברו שלקחה באריסות כמ\"ש סימן רמ\"ג ס\"א מ\"מ אסור דשאני התם דכשיחקרו הדבר ימצא שכן הוא שהאינו יהודי חולק בפירות אבל הכא שיראו בעת הקציר שאין האינו יהודי נוטל בריוח ידעו למפרע דלאו אריס היה ויחשדוהו ששכיר יום היה דשכיח לשכור פועלים לימים למלאכה. ואפילו אם מנהג העיר לשכור בקיבולת דעת הט\"ז להחמיר שלא להניח להאינו יהודי לעשות בשדה בשבת ויו\"ט וכ\"ש בבנין בית דאכתי יחשדוהו בשכיר יום שגם זה הוא רגילות ויש שמקילין בזה כשמנהג כל העיר הוא בקיבולת [וקיבולת הוא דוקא כשכל המלאכה הוא בקיבולת לאפוקי אם רק האדריכל לבדו הוא קבלן ושאר המסייעים דרך לשכרם לפעמים ליום ואפילו אם הוא שכרם הכל בקבלנות ג\"כ אסור] ועיין בבה\"ל שביארנו דבשדה יש לסמוך על דבריהם במקום הפסד אבל בבית צ\"ע אם יש להקל בזה דהוא נגד דעת כמה פוסקים ועיין בשע\"ת בשם נו\"ב סי' י\"ב:","(ח) במדינה - היינו בתוך העיר שקרוי מדינה לפעמים:","(ט) התחום - שרגילין אנשי העיר לפעמים לילך לשם:","(י) להניחה - איתא בס\"ח סימן שמ\"ח מעשה באדם אחד ששכר אינו יהודי לבנות ביתו בקבלנות והיה האינו יהודי בונה בשבת והיו מתרעמים עליו ולא חשש לכך ולא היו ימים מועטים שלא נשאר הקרקע לא לו ולא לזרעו:","(יא) אם דר וכו' - ר\"ל שהוא דר מחוץ לתחום העיר וגם אין עיר אחרת בתוך תחומו אפ\"ה אסור דיש לחוש לאורחים דמקלעי לגביה ויחשדוהו ומה דמקילין לקמיה מבחוץ לתחום היינו כשרק המלאכה היא שם אבל הוא בעצמו דר בעיר:","(יב) וגם אין עיר אחרת - וה\"ה כשדר שם איזה יהודי בתוך התחום של מלאכה ג\"כ אסור ויצוה להאינו יהודי קודם שבת שלא יעשה בשבת:","(יג) מותר - דתו ליכא משום מראית העין ואינו יהודי כי קטרח בדידיה קטרח. והנה מתוך מה שנתבאר בזה הסעיף מוכח דאסור לשכור אינו יהודי בקבלנות לפנות זבלו מחצר והוא עושה בו בשבת דהוא מתקן החצר בזה והוא בכלל מלאכת מחובר ויש מקומות שנוהגין היתר לשכרו ליקח הזבל מרחוב אף שעושה בו בשבת וכתב המ\"א דטעמם דבשל רבים ליכא חשדא אבל בשכיר יום פשיטא דאסור והאחרונים השיגו על טעמו ודעתם דאין נ\"מ בזה הענין בין רבים ליחיד וגם הוא בעצמו כתב לבסוף דבמקום שאין נוהגין היתר ברחוב אין להקל ע\"ש טעמו דיש ח\"ה בדבר וכדלקמיה. והנה אפילו אם נאמר דבשל רבים ליכא חשדא מ\"מ הסכים המ\"א שאין להתיר לבנות בהכ\"נ בשבת בקבלנות כי בזמנינו שאין האומות שכנינו מניחים לשום אדם לעשות מלאכה בפרהסיא ביום חגם איכא ח\"ה אם נניח אנחנו לעשות ביום שבת ויו\"ט ומ\"מ כתבו כמה אחרונים דאם יש חשש ח\"ו שיתבטל הבנין בהכ\"נ לגמרי מותר להניח לאינו יהודי לבנותו כשהוא בקבלנות ובלבד שיהיה מפורסם לכל שהוא בקבלנות:","(יד) לפסול האבנים וכו' - ודוקא כשאבנים וקורות הם של ישראל ונתנם לאומן אינו יהודי לסתתם ולתקנם אבל אם האינו יהודי מסתת אבנים שלו ומתקן קורות שלו שהישראל עשה עמו קיבולת על הכל והברירה עוד ביד האינו יהודי לסתת אבנים אחרות ולהחזיק אלו לעצמו אפילו עושה זה לצורך ישראל אם אינו בביתו של ישראל אף שהוא מפורסם שעשה זה לצורך ישראל מותר שזה לא נקרא עדיין מלאכת ישראל כ\"כ הדגמ\"ר וכבר קדמו בתשובת הרדב\"ז בחלק ששי סימן נ\"ו אך שמסיים שם דאם היה האינו יהודי מסתת אותם בשבת סמוך לבנין אין נכון הדבר משום מראית העין שלא יאמרו שכירו הוא:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>לפסול האבני' ולתקן הקורו' אפי' בביתו של עכו\"ם אסו' כיון <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>דלצורך מחובר היא ואם עשו כן לא ישקעם בבנין: <small>הגה וי\"א דאם אינו מפורסם שהוא של ישראל שרי [כל בו]:</small>","m":["(טו) דלצורך מחובר הוא - כדי לשקעם בהבנין ע\"כ חשבוהו כמחובר וצריך למחות בידו אם הוא בתוך התחום אפילו עושה רחוק מהבנין:","(טז) ואם עשו כן - עיין לקמיה מש\"כ בזה:","(יז) ויש אומרים דאם אינו וכו' - הי\"א קאי אכולהו דהיינו אף מחובר גמור לא אסרו בקבלנות אלא בסתמא דמסתמא שם הישראל נקרא עליו אבל בידוע לנו שאינו מפורסם הבנין על שם ישראל לא אסרו בקיבולת והא דציין הרמ\"א הי\"א על סיתות אבנים משום דבבנין ממש אין מצוי זה:","(יח) שרי - היינו שאינו צריך למחות בא\"י אם יעשה מלאכתו בשבת ובלבד שלא יאמר לו שיעשה בשבת. וכ\"ז דוקא אם הא\"י עושה בביתו או שיהיה עכ\"פ רחוק מהבנין כדי שלא יהיה מינכר שהוא של ישראל וכנ\"ל ומשמע בכמה אחרונים דסבירא לן לדינא דהי\"א הזה לענין סיתות האבנין ואפשר דגם המחבר מודה ליה בזה אך לענין מחובר גופא אפילו אם הבנין עומד במקום שאין ידוע שהוא שלו ג\"כ אין להקל דיש לחוש לשכניו או לבני ביתו שיודעים שהוא שלו ויחשדוהו וכמש\"כ לעיל בסק\"ו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>אם בנו עכו\"ם לישראל בית בשבת באיסור <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i><i data-commentator=\"Turei Zahav\" data-order=\"4\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>נכון להחמיר <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>שלא יכנסו בו: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>מיהו אם התנה ישראל עם עכו\"ם שלא לעשות לו מלאכה בשבת והעכו\"ם עשאה בעל כרחו למהר להשלים מלאכתו אין לחוש [מרדכי ריש פרק מי שהפך ור' ירוחם וב\"י וע\"ל סי' תקמ\"ג]:</small>","m":["(יט) באיסור - היינו שהיה בקיבולת ובתוך התחום דהוא אסור רק משום מראית עין דבאמת אדעתיה דנפשיה עביד וכנ\"ל אבל אם היו שכירי יום דמדינא אסור יש בזה איסור מצד הדין בדיעבד ולא נכון בלבד כ\"כ המ\"א וכן מוכח ג\"כ דעת הב\"ח לענין שכיר יום וכ\"כ הח\"א דבשכיר יום אסור מדינא בענין זה שהוא מילתא דפרהסיא לו לעולם ולאחרים בכדי שיעשו וכמו לקמן בסימן שכ\"ה סי\"ד ע\"ש ויש מקילין דאף בכה\"ג אינו אסור מדינא כ\"א בכדי שיעשו וע' לקמן בסי' שכ\"ה סי\"ד שם במ\"ב:","(כ) נכון להחמיר - והאחרונים כתבו דבדיעבד יש לסמוך בקבלנות על דעת ר\"ת ומותר לדור בו אפילו לעצמו וכן בסיתות האבנים ותיקון הקורות אם היה בקבלנות יש להתיר בדיעבד לשקעם בבנין:","(כא) שלא יכנסו בו - לעולם ואפילו אחרים אבל מ\"מ מותר ליהנות ממנו ולמכרה לא\"י:","(כב) בעל כרחו - ר\"ל שעבר על תנאו שהתנה עמו מקודם על כן אין לו לחוש לזה דהיינו שאין צריך אפילו למחות לו עוד בעת שעושה המלאכה [כן מוכח במרדכי ורי\"ו שהם מקור דין לזה שהובאו בב\"י לקמן וכן מוכח מביאור הגר\"א] ועיין במ\"א שמפקפק מאד בדין זה דכיון שהוא מחובר והוי מילתא דפרהסיא איכא חשדא דרואים שלא ידעו שהתנה וכן בא\"ר נתקשה על עיקר הדין של המרדכי וע\"כ אין להקל בזה אלא יראה למחות לו ולמנעו מפעולתו וכתב הא\"ר דמ\"מ נראה שא\"צ ליתן להם מעות כדי שיפסקו כיון שבכך התנה מתחלה ונרצו לכך עכ\"ד ומשמע מלשונו דאם לא התנה מתחלה אין די במחאתו בלבד אלא צריך לפזר ממעותיו כדי שיפסקו ונראה שטעמו דפשע דה\"ל להתנות מתחלה וצ\"ע לדינא:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>מלאכת פרהסיא אפילו במטלטלין <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i>כגון ספינה הידועה לישראל דינה כמו מלאכת מחובר:","m":["(כג) הידועה לישראל - אין מיירי שעושה אותה ברשות ישראל דא\"ה אפילו היה דינו רק כמטלטלין דעלמא ג\"כ היה אסור כדמוכח בסימן רנ\"ב ס\"ב דאף במטלטלין אסור אם עושה אותה ברשות ישראל אלא מיירי שלא בביתו ועיין במ\"א ושארי אחרונים דדוקא אם לעושה את הספינה במקום גלוי ומפורסם דאם בצינעה אין להחמיר בה כדמוכח בסימן רנ\"ב ס\"ג:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>אם שכר עכו\"ם לשנה או לשתים <i data-commentator=\"Magen Avraham\" data-order=\"14\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"7\"></i>שיכתוב לו או שיארוג לו בגד הרי זה כותב ואורג בשבת <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>כאלו קצץ עמו שיכתוב לו ספר או שיארוג לו בגד שהוא עושה בכל עת שירצה והוא שלא יחשוב עמו יום יום <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>ולא יעש' המלאכ' בבית ישראל <i data-commentator=\"Magen Avraham\" data-order=\"15\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>ויש מי שאוס' בשוכר עכו\"ם לזמן: <small>הגה ודוקא ששכרו למלאכה מיוחדת כגון בגד לארוג או ספר לכתוב אבל כששכרו לכל המלאכות שיצטרך תוך זמן השכירות <i data-commentator=\"Magen Avraham\" data-order=\"16\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>לכ\"ע אסור (ב\"י) וכמו שיתבאר ס\"ס רמ\"ז:</small>","m":["(כד) שיכתוב לו - כתב מ\"א כונת הרמב\"ם כדרך השרים שיש להם סופר מיוחד או חייט מיוחד שבכל עת שצריך השר לכתוב מחויב לו לכתוב ובעת שאין צריך לו יושב ובטל ולכן מותר לכתוב או לארוג בשבת שהוא עושה בכל עת שירצה שהרי הישראל אין אומר לו לעשות בשבת ואם רצה עושה למחר ואין הישראל מרויח במה שעושה בשבת אבל אם שכרו לארוג לו תמיד בשנה זו או לכתוב לו תמיד אסור אף להרמב\"ם לכתוב לו בשבת אף שאין מדקדק עליו על ביטול איזה יום מ\"מ הרי מרויח הישראל בעשייתו ומהט\"ז משמע דגם בכה\"ג חשוב להרמב\"ם קבלנות כיון שאינו מקפיד עליו אם יבטל איזה יום דאם הוא מקפיד עליו שלא ישב איזה יום בטל אסור לכו\"ע דהוי כאלו צוהו לעשות ביום השבת. עוד כתב הט\"ז דאם שכרו לגמור ספר או בגד תוך אותו זמן הוא כמקפיד והיינו בשידוע דא\"א לגמור אם לא שיעשה גם בשבת ואף שאם יאנוס עצמו וישב בלילה יוכל לגמור בחול אעפ\"כ הוי זה כמצוה לו לעשות בשבת [כן ביאר הפ\"מ כונתו והסכים עמו נגד הא\"ר]:","(כה) או שיארוג לו ה\"ז וכו' - כצ\"ל:","(כו) שלא יחשוב עמו - ר\"ל שלא ידקדק עליו אם מבטל איזה יום ממלאכתו:","(כז) בבית ישראל - דבזה אפילו קבלנות גמורה אסור כדלקמן בסימן רנ\"ב:","(כח) ויש מי שאוסר - הוא דעת הראב\"ד והנה לדעת הט\"ז הנ\"ל ניחא בפשיטות טעם הראב\"ד דס\"ל דאף שאינו מקפיד על ביטולו מ\"מ הרי הישראל מרויח על ידו ולדעת המ\"א הנ\"ל ג\"כ ניחא דס\"ל להראב\"ד דהישראל מרויח במה שעושה בשבת דשמא יצטרך גם למחר לכתוב ולא יוכל לעשות שניהם כאחד:","(כט) למלאכה מיוחדת - דבזה אפשר שלא יגיע לישראל ריוח עי\"ז שהוא עושה בשבת כגון שלא יצטרך הישראל אריגה או כתיבה כ\"כ אבל אם לכל המלאכות קרוב הדבר לודאי שיצטרך למחר מלאכה אחרת וא\"כ מרויח הישראל במלאכת הא\"י בשבת ולכך אפילו אם לא יחשוב עמו יום יום אסור:","(ל) לכל המלאכות - ומטעם זה יש למחות ביד השפחות כשעושין מלאכת אדוניהן בשבת אפילו כשעושין שלא בבית ישראל ושלא בצווי בעליהן דהא הם שכורין לכל המלאכות וכ\"ש כשעושין בבית ישראל דזה אסור אפילו בשכור למלאכה מיוחדת וכנ\"ל. ועיין בט\"ז סק\"ך דמביא בשם רבינו שמחה דהוא אוסר להשפחה אפילו לעשות מלאכת עצמה בבית בעליה והטעם מפני הרואים שלא יאמרו מלאכה של ישראל היא עושה והא\"ר הביא בשם סה\"ת דמלאכת עצמה מותר ודעתו שגם רבינו שמחה מודה לזה ע\"ש בדבריו והפמ\"ג יישב דברי הט\"ז ע\"ש ועיין בספר ח\"א כלל ס\"ד דלתקן השפחה בגדיה לכו\"ע מותר בבית בעה\"ב שהוא ניכר שמלאכת עצמה היא עושה ועי\"ש עוד מה שכתב בענין זה ועיין מה שכתבנו בס\"ק ל\"ה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>יהודי הקונה מכס ומשכיר לו עכו\"ם לקבל מכס בשבת מות' <i data-commentator=\"Turei Zahav\" data-order=\"6\"></i>אם הוא <i data-commentator=\"Magen Avraham\" data-order=\"17\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"9\"></i>בקבולת דהיינו שאומ' לו לכשתגבה ק' דינרים אתן לך כך וכך: <small>הגה וכן יוכל <i data-commentator=\"Magen Avraham\" data-order=\"18\"></i>להשכיר המכס לכל השבתות לעכו\"ם והעכו\"ם יקח הריוח של שבתות לעצמו ולא חיישי' שיאמרו לצורך ישראל הוא עוש' דבמקום פסידא כה\"ג לא חששו [ב\"י] וישראל הממונה על מטבע של מלך <i data-commentator=\"Magen Avraham\" data-order=\"19\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i>דינו כדין הממונ' על המכס ואע\"פ שמשמיעי' קול בשבת בהכא' המטבע [הגהו' מיי' פ\"ז] וע\"ל סי' רנ\"ב ויזהר <i data-commentator=\"Turei Zahav\" data-order=\"7\"></i>שלא ישב הישראל אצל העכו\"ם בשב' כשעוסק <i data-commentator=\"Magen Avraham\" data-order=\"20\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"11\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"11\"></i>במלאכתו במטבע או בקבל' המכס [מרדכי פ\"ק דשב']:</small>","m":["(לא) ומשכיר לו א\"י - הלשון אינו מדויק כי הכונה הוא ששוכר את הא\"י [אחרונים]:","(לב) אם הוא בקיבולת - דאז שרי מדינא כמו בעורות לעבדן בריש סימן רנ\"ב דמותר ליתן לו קודם שקיעת החמה אם הוא בקיבולת משום דאדעתא דנפשיה קעביד אע\"ג דאסור שם לקבוע לו מלאכתו בשבת ועוד דהוי מילתא דפרהסיא שהעסק היה ידוע לכל שהוא של ישראל וכמו שהיה עושה הא\"י עתה בבית ישראל דמי דאסר שם מ\"מ התירו בזה משום פסידא דאדם בהול על ממנו ואי לא שרית ליה אתי לגבות בעצמו ויבוא לידי איסורא דאורייתא דשמא יכתוב פתקא כדרך המוכסים [בית יוסף] ולפ\"ז משמע דבמכ\"ס שאין כותבין כגון אותן שלוקחין מיני מאכל במכס אסור אפילו ע\"י א\"י דלא יבא לידי איסור דאורייתא אפילו אי לא שרינן ליה אבל הט\"ז ומ\"א מסקי דאפילו באופן זה שרינן ע\"י א\"י משום פסידא. מיהו בעצמו אסור לקבל אף המכס של מיני מאכל אפילו אם לא הובא מחוץ לתחום ולא שייך בו חשש צידה ומחובר משום ממצוא חפצך וכמ\"ש סימן ש\"ו [א\"ר]. יהודי ששכר בשול המלח מן השר מותר להשכיר לו פועלים בקיבולת שאם יעשה לו כך וכך מלח יתן לו כך וכך ואע\"פ שהכלים והעצים הם של ישראל שרי [ובלבד שלא יביאו עצים מרשות הישראל בשבת שכל קבלנות אינה מותרת אא\"כ מסר להם מע\"ש כל מה שרוצה למסור לצורך המלאכה ויוציאום מרשותו מע\"ש] אבל אין לו היתר לשכור א\"י על שבת וחודש דמ\"מ מרויח הישראל במלאכתו ואין לו היתר אלא בקבלנות [ח\"א]:","(לג) אתן לך כך וכך - דהיינו שאין מזכיר לו יום השבת כלל אלא בסתמא אם תגבה כו\"כ אתן לך סך כו\"כ א\"כ לא הוי שכיר יום וגם לית כאן שכר שבת כלל שכבר שכר מהשר המכס של כל השנה עם השבתות בכלל [פמ\"ג]:","(לד) והא\"י יקח וכו' - ר\"ל דבזה ג\"כ מדינא שרי דא\"י כי עביד אדעתא דנפשיה עביד וכתב המ\"א דגם משום שכר שבת לית בזה אף שהוא משכירו לשבת לחוד משום דהרי הוא כאלו קנה ממנו המכס [וה\"ל כאלו יודע שיביאו לו א\"י סחורה בשבת ומכרה בע\"ש לא\"י שהוא יקבלה ממנו בשבת דפשיטא דשרי] וכן גבי מטבע מוכר לו הורמנא בעלמא מה שיש לו מהמלך וכל הריוח יקח הא\"י ואין בזה רק משום מראית העין שיאמרו שהוא עושה לצורך ישראל שישראל שכרו לכתוב בשבת ולקבל המכס וזהו שכתב הרמ\"א ולא חיישינן וכו' דבמקום פסידא וכו' ולא הזכיר כלל משכר שבת ועיין בבה\"ל:","(לה) לא חששו - דע דמשמע מכל הפוסקים דלא התירו אפי' במקום הפסד גדול אלא באופן זה שצייר השו\"ע דהיינו או בקיבולת או שמשכיר לו את גוף הריוח דבכל זה העובד גלולים אדעתא דנפשיה קעביד אבל בשכיר יום ממש אסור בכל גווני ומזה תדע שאותן האנשים המחזיקים בית משקה שלוקחין מע\"ש איזה א\"י בביתן על יום השבת לעסוק במכירת המשקה שלא כדין הם עושין דאף אם נחשוב מניעת ריוח יום השבת להפסד גדול מ\"מ הלא לא התירו בשכיר יום ממש וגם דאולי הוא רק בכלל מניעת הריוח כמו שכתבו האחרונים לענין תנור ומרחץ ועכ\"פ אין להתיר אלא באופן שציירו השו\"ע והרמ\"א או שיקנה לו מע\"ש כל הדברים שנותן לו למכור ואף דעכ\"פ עדיין העסק נקרא על שם ישראל זה מותר משום פסידא ולפי מה שכתבנו לקמיה בשם הט\"ז יהיה מותר בזה לישראל לישב מרחוק ולשמור שלא יגנוב הא\"י מהעסק אך שיזהר שלא יתערב בהעסק ושלא ידבר עמו כלום מענינים ההם והוא דבר שקשה ליזהר שלא לדבר כלום כשיושב שם אך העולם נוהגין להתיר והנח להם מוטב שיהיו שוגגין ואל יהיו מזידין [תו\"ש] והבוטח בה' ואינו מחפש צדדי קולות על שבת אשריו:","(לו) דינו כדין וכו' - וע\"כ מותר ליתן הכסף לא\"י מבעוד יום בקיבולת שאם יעשה לו מן הכסף כו\"כ יתן לו כו\"כ או שישכיר לו הישראל הריוח שיעלה מזה בשבת להא\"י וכנ\"ל משום פסידא:","(לז) שלא ישב הישראל - שהשכיר לו או שלוחו וכתב הט\"ז דמה שאסור לישב שם היינו כדי לידע מה היא ההתעסקות שעושה הא\"י וכדי לקבל הימנו חשבון ע\"ז למחר דזה אסור משום מצוא חפצך כדלקמן סימן ש\"ו ס\"א אבל אם אינו יושב שם אלא כדי לשמור את הא\"י שלא יגנוב מן המכס מותר ומזה ניחא מה שנהגו מחזיקי רחיים מהשר להושיב שם ישראל אפילו בשבת רק יזהרו שלא ידבר כלום בהעסק עכ\"ל וכ\"כ שארי אחרונים: "]}],"245":[{"s":"<b>ישראל ועכו\"ם שותפין איך יתנהגו בשבת. ובו ו סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>ישראל ועכו\"ם שיש להם שדה או <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>תנור או מרחץ או <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>רחיים של מים <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>בשותפו' או שהם שותפין בחנות בסחורה אם התנו מתחלה בשעה שבאו להשתתף שיהיה שכר השבת לעכו\"ם לבדו <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>אם מעט ואם הרבה ושכר יום אחד כנגד יום השבת לישראל לבדו מות' <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>ואם לא התנו בתחל' כשיבואו לחלוק נוטל עכו\"ם שכר השבתו' כולם והשאר חולקים אותו <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ואם לא היה שכר השבת ידוע יטול העכו\"ם לבדו שביעית השכר וחולקים השאר: <small>הגה ויש מתירין השכר בדעבד אפילו לא התנו <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>וחלקו סתם [הרא\"ש פרק קמא דע\"א ור' ירוחם חי\"ב] ונ\"ל דבהפסד גדול יש לסמוך עלייהו וי\"א שכל זה לא מיירי אלא בשותפות שכל א' <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>עוסק <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"2\"></i>ביומו [ב\"י] אבל כששניהם עוסקי' ביחד כל ימי החול ובשבת עוסק העכו\"ם לבדו מות' לחלוק עמו כל השכר דעכו\"ם <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>אדעתיה דנפשיה קא עביד ואין הישראל נהנה במלאכתו בשבת כיון שאין המלאכה מוטלת עליו לעשות ומ\"מ לא יטול שכר שבת אלא <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>בהבלעה עם שאר הימים [ר\"ן פ\"ק דשבת ס\"פ כ\"כ ופ\"ק דע\"א]:</small>","m":["(א) ישראל וא\"י וכו' - דע ההיתר גמור הוא באם הישראל יש לו איזה עסק או מלאכה בשותפות עם הא\"י שיתנו מתחלה קודם שלוקחין בשותפות עבוד עתה בשבת ותקח כפי מלאכתך הן רב או מעט ואני אעבוד כנגדך יום אחד בחול ואטול כפי מלאכתי ובשעת חלוקה יטול הא\"י שכר עבור השבת והישראל יטול יום א' כנגדו הן רב או מעט אבל אם לא התנו מתחלה ובשעת חלוקה אומר לא\"י טול אתה כנגד עמלך בשבת ואני בחול זהו ודאי אסור ואם לא התנו מתחלה ובשעת חלוקה חלקו סתם בשוה זהו בעיא בגמרא ולא אפשיטא ופסק הרמב\"ם לחומרא והרא\"ש לקולא והמחבר סתם כהרמב\"ם והרמ\"א פסק בהג\"ה כהרא\"ש במקום הפסד גדול. ואם התנו קודם שבאו להשתתף כנ\"ל ובשעת חלוקה נתרצו לחלוק בשוה זהו מותר אף להרמב\"ם וכמש\"כ בס\"ב זהו עיקרי הדינים שבסעיפים הראשונים ויתר הפרטים וגם טעמיהן יבוארו לקמיה. שדה או תנור וכו' - טעם הדברים אלו דבעינן התנו דאל\"ה כיון דמתחלה בשעת עשיית השותפות היה מוטל המלאכה על שניהם יחדו ולהכי אם אח\"כ יאמר להא\"י עשה אתה לבדך בשבת וטול לך כל הריוח של שבת ואני אעשה לבדי יום אחד בחול כנגדו ואטול אותו לעצמי הריוח של אותו יום הו\"ל כאלו מעמיד את הא\"י לפועל בידים כאלו אומר לו עשה אתה עבורי בשבת ואני אעשה נגד זה עבורך בחול והוי שלוחו ממש [תוספות] ולפ\"ז אם שותפו הא\"י בעצמו אינו עושה כלום רק שא\"י אחרים הבאים לאפות מסיקין בו בתנור של השותפות ונותנים סך מה בשכרם יכול הישראל לקבל משותפו שכרו המגיע לו לפי חלקו אפילו אם לא התנו ובלבד שלא יקח ממנו משכר שבת לבדו אלא יקח ממנו סתם בהבלעת שאר ימים כדי שלא יהיה שכר שבת ולא חיישינן משום מראית העין שיאמרו לצורך ישראל הוא עושה כיון שידוע שיש לא\"י חלק בו [מ\"א וש\"א]:","(ב) אם התנו מתחלה - הטעם דכיון שהותנו בתחלה לא הוטל על הישראל כלל מעיקרא לעשות בשבת ואין הא\"י שלוחו:","(ג) שיהיה שכר שבת וכו' - וגבי שדה צריך שיאמר לו תעמול לזרוע ולחרוש בשבת ותטול בשעת קצירה כנגד עמלך בשבת ואני או שלוחי אעמול בחול ואטול ג\"כ כנגד יום שלי:","(ד) אם מעט וכו' - דכיון דאינם מחשבין זה כנגד זה ליטול בשוה א\"כ אינם שותפים כלל ביום שבת וביום א' רק בשאר הימים ולאפוקי אם מתנה עמו בשעת התנאי שלבסוף יבואו לחשבון שיהיה השכר לשניהם בשוה דאסור דעל כרחך הוא עמו כשותף גם ביום השבת:","(ה) ואם הרבה - ואם אח\"כ בשעת חלוקה באו לחשבון לומר כמה נטלת אתה מרובה ואני מועט נחלוק המותר שיהיה לשניהן בשוה דעת המ\"א לפסוק כדעת הראב\"ד שמחמיר בזה משום דאיגלאי מילתא למפרע דהתנאי דמעיקרא הערמה בעלמא הוי ויש מקילין בזה כיון דהתנו מעיקרא ועיין בא\"ר שהאריך ג\"כ בזה ולבסוף נשאר בצ\"ע:"]},{"s":" <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>היכא שהתנו בתחלה אם אח\"כ בשע' חלוקה נתרצה העכו\"ם לחלוק בשוה מות':","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>היכא שלא התנו בתחלה יש תיקון ע\"י שיחזיר המוכר להם <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>דמי הקרקע או ימכרוהו לאיש אחר ויחזרו ויקנוהו בשותפות ויתנו בשעת הקניה ואם נשתתפו בחנו' ולא התנו יחזור כל אחד ויטול חלקו ויבטלו השותפות ואח\"כ יחזרו להשתתף ויתנו בתחל' ואם קבל הקרקע לעשות בו מלאכה בשותפות יבטלו השיתוף וימחלו זה לזה ואח\"כ יחזרו להשתתף ויתנו בתחל': <small>הגה <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>ואם ירצה <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>להשכיר לעכו\"ם חלקו <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>בשבת או לשכרו בקבולת שרי וכמו שיתבאר לעיל ס\"ס רמ\"ד לענין מכס ומטבע דשרי וכ\"ש כאן דשרי עם שותפו' עכו\"ם:</small>","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>יכול ישראל ליתן לעכו\"ם <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>מעות להתעסק בהם ואף ע\"פ שהעכו\"ם נושא ונותן בהם בשבת חולק עמו כל השכר בשוה מפני שאין מלאכה זו מוטלת על ישראל לעשותה שנא' שהעכו\"ם עושה שליחותו וכן אין העסק ניכר ממי הוא: <small>הגה ודוקא בכה\"ג שהעכו\"ם נושא ונותן לחוד עם המעות אבל אם כ\"א עוסק ביומו וישראל צריך לעסוק נגד מה שעסק העכו\"ם בשב' אסור [ב\"י בשם גאון] וישראל שיש לו משכון מן העכו\"ם ע' לקמן סי' שכ\"ה סעיף ב' וג':</small>","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>מות' לישראל ליתן סחורה לעכו\"ם למכור אם קצץ לו שכר ובלבד שלא יאמר לו מכור בשבת <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>תנור שלקחו ישראל משכון מעכו\"ם וקבל עליו העכו\"ם שמה שיעלה שכר התנור יתן לישראל ברבית מעותיו מותר ליטול שכר שבת לפי שהוא ברשות העכו\"ם ואין לישראל חלק בו וגם אין הישראל אומ' לו לעסוק בשבת ועכו\"ם כי טרח בנפשיה טרח לקיים תנאו:","m":["(ו) מותר - ואם לא נודע אח\"כ ריוח של כל אחד ואחד על יומו כגון בחנות רשאין לכתחלה לחלוק בשוה [מ\"א בשם רלב\"ח]:","(ז) ואם לא התנו בתחלה - כתב סתמא לאסור בלא התנו אפילו אם לא אמר לו עבוד אתה בשבת ואני בחול וגם בשעת חלוקה לא הזכיר לו של שבת אלא רוצה לחלוק עמו סתם בשוה אפ\"ה אסור כיון שלא התנו קודם שנשתתפו:","(ח) וחלקו סתם - היינו שבשעת חלוקה לא הזכיר לו ישראל את השבת לומר אתה תטול כנגד יום עמלך בשבת ואני אטול כנגד יום עמלי בחול אלא חלקו סתם בשוה וגם מיירי שלא אמר לו בתחלה עבוד אתה בשבת ואני אעבוד כנגדך בחול אלא הא\"י עשה מעצמו שלא בצוויו דאל\"ה אסור לכו\"ע בכל זה דגלי דעתו דשלוחו היה על שבת והוא עמל כנגדו בחול כיון שמתחלה הוטל על שניהן יחד. ודע דכל הסעיף הזה מיירי שהישראל והאינו יהודי הם שותפים בגוף התנור והמרחץ אבל אם אין לא\"י חלק בגוף התנור רק שהוא מקבל חלק בריוח בשביל שהוא אופה ומסיק התנור י\"א דלא מהני בזה אפילו כשמתנה בתחלה טול אתה חלקך בשבת ואני יום אחד בחול דכיון שגוף התנור הוא של ישראל הו\"ל כמשכיר לו תנורו על שבת שיסיק לו בשביל זה השכר יום אחד של חול ואסור ליטול שכר שבת ועיין במ\"א שמסיק דיש לחוש להחמיר כדעה זו ודוקא באופן זה שהוא שלא בהבלעה אבל אם הוא בהבלעה כגון שאומר לאופה טול אתה ב' וג' ימים שרי כשהתנה זה בתחלת השותפות ויש מאחרונים שסוברין דלא בעינן בזה שאין לא\"י חלק בגוף התנור התנו מעיקרא כיון שהוא בהבלעה:","(ט) ביומו - דאז כיון דהישראל עושה כל יום א' הו\"ל הא\"י כשלוחו לעשות כל יום השבת בשבילו ולכך בעינן שיתנה מעיקרא וכנ\"ל וכתבו האחרונים דה\"ה אם הא\"י נתן מעות לישראל להתעסק בהם בחול ובשבת מתעסק הוא דאסור לישראל לקבל ממנו שכר מן הריוח שנולד בשבת אא\"כ יתנה הישראל עמו מעיקרא שלא יהיה מוטל עליו יום השבת כלל דאל\"ה כיון דהמלאכה הזאת מוטלת על ישראל והא\"י עושה שליחותו אסור:","(י) אדעתיה דנפשיה קעביד - בשביל חלקו דה\"ל כאריס דמותר מדינא וכנ\"ל בריש סימן רמ\"ג דכיון שהוא לוקח בפירות עביד אדעתיה דנפשיה וחלק הישראל נשבח ממילא וה\"ה כאן אלא דשם אסור בתנור משום מראית העין שיאמרו שכירו הוא וכאן ליכא מ\"ע דהכל יודעין שיש לא\"י חלק בו:","(יא) ואין הישראל נהנה וכו' - ר\"ל דהנאתו הוא רק הנאה דממילא אבל אין הא\"י עושה מלאכתו בשבילו להנותו דליהוי כשלוחו בזה כיון דאין מוטל כלל על ישראל בזה לעשות בשבת דהא בחול מחממין שניהם ובשבת אין הא\"י יכול לכופו שיעסוק עמו משו\"ה בודאי אדעתיה דנפשיה עביד:","(יב) בהבלעה - דאל\"ה מחזי כשכר שבת:","(יג) נתרצה הא\"י - ר\"ל שעלה לפי מה שהתנו הן רב או מעט על חלק השבת יותר מיום אחד החול של ישראל ובשעת חלוקה נתרצה לחלוק בשוה אפ\"ה לא אמרינן דאיגלאי מלתא למפרע דהא\"י היה שלוחו למלאכת שבת אלא מתנה בעלמא הוא דיהיב ליה הא\"י כיון דהתנו מתחלה שיהיה יום השבת שייך לו לבדו ודוקא שריצוי של א\"י שיהיה החלוקה בשוה היה בסתמא שלא ע\"י עשיית חשבון מריוח שני הימים אבל אם בא ע\"י עשיית חשבון שהישראל אמר לא\"י בשעת חלוקה את שקלית בשבת ק' זוזי ואנא שקילנא ביום החול נ' זוזי מלא לי החסרון ועי\"ז נתרצה הא\"י להשלים לו כבר כתבתי לעיל בס\"ק ה' שיש דעות בזה:","(יד) שיחזיר המוכר להם - ובח\"מ איתא שצריך עתה קנין מחדש להקנות להמוכר ולא סגי בזה שיחזיר לו הדמים והשטר מכיר ועיין שם סימן קפ\"ט וקצ\"ד לענין קנין הא\"י:","(טו) ואם ירצה וכו' - עיין במג\"א וט\"ז שנתקשו בזה מאד דלמה יהיה מותר ואינו דומה לסימן רמ\"ד דשם שרי משום פסידא דווקא ותירץ המג\"א במסקנא דהכא איירי שמשכיר לו את חלקו בשבת בהבלעה דהיינו שמשכיר לו כל ימי השבתות שלו עם ב' וג' ימים מימי החול דתו ליתא כאן משום שכר שבת ומה דשרי בקיבולת מיירי ג\"כ שלא ייחד לו שבת בהקיבולת אלא בסתמא כל אימת שתעשה בעצמך ותרויח לי כו\"כ אתן לו כו\"כ ועיקר רבותא דהרמ\"א דקמ\"ל דלא חיישינן בזה למראית עין שיאמרו לצורך ישראל הוא עושה כיון שידוע שיש לא\"י חלק בו ומש\"כ כמו שנתבאר כונתו כמו שם דלא חששו למ\"ע וכ\"ש הכא דליכא מ\"ע כלל כיון שהוא בשותפות עם הא\"י וכן הט\"ז מסיק לדינא דאינו מותר בזה אלא בהבלעה ואעפ\"כ יזהר שלא לדבר עם הא\"י בהעסק בשבת כמ\"ש האחרונים בסוף סימן רמ\"ד:","(טז) מפני שאין וכו' - שאם היה מוטלת עליו אסור מדינא כמ\"ש בס\"א שאם לא התנה שאסור:","(יז) שנאמר וכו' - ומשום מיחזי כשכר שבת ליכא דהרי הוא בהבלעה ועיין לקמן סימן ש\"ז ס\"ג וס\"ד ומה שכתבתי שם במשנה ברורה:","(יח) וכן אין וכו' - ר\"ל דמשום מראית העין שיאמרו הבריות שהא\"י שכירו הוא ליכא ג\"כ דהלא אין העסק ניכר של מי הוא שאם היה ניכר ונקרא על שם ישראל היה אסור כמ\"ש סימן רמ\"ג ס\"א גבי מרחץ ע\"ש. ומ\"מ כ\"ז אינו מותר אלא כשלא יאמר לא\"י שיתעסק בהם בשבת אלא שהא\"י בעצמו עושה כן וכמו שכתב כעין זה בס\"ה:","(יט) אסור - אם לא שהתנה עמו בזה קודם שנשתתף עמו וכנ\"ל בס\"א:","(כ) אם קצץ וכו' - דאז אמרינן אדעתיה דנפשיה עביד ואינו כשלוחו:","(כא) ובלבד וכו' - ואם יום השוק הוא בשבת אפילו בסתמא אסור דהוי כאלו אמר לי מכור לי בשבת [אחרונים לקמן בסימן ש\"ד ע\"ש עוד בזה]:","(כב) מותר ליטול וכו' - היינו אפילו שלא בהבלעה ואין צריך להתנות כלום:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>אם אפו עכו\"ם בתנורו של ישראל בשבת על כרחו ונתנו לו פת בשכר התנור אסו' ליהנות ממנו:","m":["(כג) אם אפו א\"י - עיין בב\"ח סוף סימן רמ\"ג שכתב דאיירי דלא אפו בו רק בשבת וע\"כ אף שבע\"כ אפו בו אם יקבל את הככר נוטל שכר שבת אבל אם אפו בו עוד שאר ימים מותר לקבל מהם שכר שבת ג\"כ בהבלעה ועיין בביאור הלכה דזה מותר אפילו לא היה האפיה בע\"כ דאף דעשה איסורא במה שהרשה להם וכנ\"ל בריש סימן רמ\"ג מ\"מ בדיעבד אין לאסור שכרו דהאיסור בזה הוא רק משום מראית העין וכמ\"ש בסוף סימן רמ\"ג במ\"ב ס\"ק ט\"ז:","(כד) ונתנו לו פת - לאו דוקא דה\"ה אם נתנו לו מעות אסור לו לקבל מהם ועובדא היה בפת [א\"ר]:"]}],"246":[{"s":"<b>דיני השאלה והשכרה לעכו\"ם בשבת. ובו ה סעיפים:</b><br><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>מותר להשאיל <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>ולהשכיר כליו לעכו\"ם ואע\"פ שהוא עושה בהם מלאכה בשבת מפני שאין אנו מצווים על <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>שביתת כלים <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>וי\"א דכלים שעושין בהם מלאכה כגון מחרישה וכיוצא בה אסור להשכיר לעכו\"ם <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>בע\"ש וביום הה' מות' להשכיר לו <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ובלבד שלא יטול שכר שבת אלא <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>בהבלעה כגון שישכיר לו לחדש או לשבוע <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>ולהשאיל לו מותר אפי' בערב שבת: <small>הגה וכן עיקר כסברא האחרונה ומותר להשאיל לו בערב שבת (טור וסמ\"ג וסמ\"ק ותו' פ\"ק דשבת) אע\"ג שמתנה שהעכו\"ם יחזור וישאיל לו לא אמרינן בכי האי גוונא דהוי כשכירות (הגהת מיי' פ\"ז):</small>","m":["(א) מותר להשאיל וכו' - הוא דעת הרי\"ף והרמב\"ם וס\"ל דהא דתניא לא ישכיר כליו לא\"י בע\"ש ובד' וה' מותר הוא מטעם שביתת כלים דאסור ואתיא כב\"ש דס\"ל אדם מצווה על שביתת כליו כמו על שביתת בהמתו אבל ב\"ה ס\"ל שביתת כלים אין אדם מצווה עליו וממילא מותר להשאיל ולהשכיר כליו אפילו בע\"ש ואפילו כלים שעושין בהם מלאכה ומ\"מ גם הם ס\"ל דכל הכלים אין היתר להשכיר רק בהבלעה אבל לא על שבת לחוד אפילו אם משכירם בתחלת השבוע דזה הוי שכר שבת וכמ\"ש אח\"כ לפי הי\"א דע\"ז לא מצינו מי שמקיל והי\"א הוא דעת הרב רבינו יונה דהך ברייתא לא אסרה משום שביתת כלים אלא ככו\"ע אתיא והטעם דכשמוסר בע\"ש את הכלים שעושין מלאכה בהן והא\"י יעשה בהן מיד בשבת נראה כמו שעושה מלאכתו בשליחותו של ישראל וזה אסור דאמירה לא\"י שבות ואע\"ג דבסימן רנ\"ב ס\"ב איתא דשרי ליתן עורות לעבדן עם חשיכה דא\"י אדעתיה דנפשיה קעביד כיון דקצץ לו דמים שאני התם שאין ריוח לישראל במה שהא\"י עושה בשבת אבל בשכירות כלים ידוע הוא שאם יתנה עם הא\"י שישבות בהכלים בשבת לא יתן לו שכירות כ\"כ הילכך כיון שיש ריוח לישראל במה שהכלים נשכרים אצל הא\"י בסתמא ועושה בהן מלאכה בשבת מחזי כשלוחו של ישראל לזה משא\"כ כשמוסר לו בד' וה' מותר דלא מיתחזי כולי האי כשלוחו:","(ב) וכיוצא בה - כגון ריחיים וכל כלי אומנות [הרא\"ש] ועיין בפמ\"ג דה\"ה כלים שאין עושין בעצמן מלאכה כגון גיגית שהשכר נעשה בה או קדרה שמבשלין בה וכל כה\"ג כיון שעכ\"פ הא\"י עושה בהן מלאכה מחזי כשלוחו של ישראל ולא בא הרר\"י למעוטי אלא כשמשכיר לו חלוק וטלית וכה\"ג איזה כלי שאין עומד לעשות בה מלאכה דמותר להשכיר לו אפילו בע\"ש:","(ג) בהבלעה - אבל ליטול שכר שבת לחוד אפילו בכלי שאין עושין בו מלאכה או שמשכיר לו חדר לדור בו אסור לכו\"ע וכמו שיתבאר לקמן בסימן ש\"ו ס\"ד:","(ד) ולהשאיל לו וכו' - דכיון שאין ריוח לישראל במלאכת הא\"י לא יאמרו שלוחו הוא לזה וע\"כ מותר להשאיל לו אפילו ליום השבת לחוד אפילו כלים שיעשה הא\"י מלאכה בהן:","(ה) ולא אמרינן וכו' - היינו שאע\"פ שאינו משאילו חנם כ\"א בשכר שישאילנו אח\"כ מ\"מ כיון דלא הוי בדרך שכירות ממש לומר אתן לך כך כדי שתשאילני כלי כלך שרי [ב\"י] ועיין בה\"ל:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>אסור להשאיל שום כלי לעכו\"ם בשבת <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>ואפילו בערב שבת אם הוא סמוך לחשיכה כל שאין שהות להוציאו <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>מפתח ביתו של המשאיל קודם חשיכה <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>מפני שהרואה סבור שישראל <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>צוהו <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>להוציאו:","m":["(ו) שום כלי - היינו אפילו כלים שאין עושין בהן מלאכה ואסור אפילו לדעה ראשונה:","(ז) ואפילו בע\"ש אם הוא וכו' - ואסור אז אפילו למכור לו או ליתן לו במתנה וכמו שמבואר לקמן בסימן רנ\"ב ס\"א וע\"ש במ\"ב מש\"כ בזה:","(ח) קודם חשיכה - היינו קודם שתשקע החמה (מגיד משנה):","(ט) צוהו להוציאו - לחוץ לר\"ה ואפילו לדידן דלית לן ר\"ה גמורה אסור דאמירה לא\"י שבות הוא אפילו במילי דרבנן וא\"כ אם העיר מוקפת חומה דמותר לטלטל בכולה והא\"י ג\"כ דר שם שרי להשאילו כלים שאין עושין מלאכה בהן ולמכור לו ולהשכירו אסור אף בזה שלא יאמרו שמכר והשכיר לו בשבת ואם הוא כלים שעושין בהן מלאכה אפילו להשאילו אסור אא\"כ יוציאם מפתח ביתו קודם השבת שלא יאמרו בשליחותו של ישראל עושה מלאכה בשבת:"]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"7\"></i><i data-commentator=\"Turei Zahav\" data-order=\"4\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>אסור להשכיר או להשאיל בהמתו לעכו\"ם כדי שיעשה בה <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>מלאכה בשבת <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>שאדם מצווה על שביתת בהמתו: <small>הגה אבל יכול להשכירה או להשאילה ולהתנו' שיחזירנו לו קודם השבת אבל לא מהני אם מתנה עם העכו\"ם שתנוח בשבת כי אין העכו\"ם נאמן <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>על כך. [סמ\"ג וסה\"ת ומרדכי פ\"ק דשבת] </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>ואם השאילה או השכירה לעכו\"ם והתנה עמו להחזירה לו קוד' השבת ועיכבה בשבת <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>יפקירנה בינו לבין עצמו קודם השבת <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>או יאמ' <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>בהמתי <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>קנויה לעכו\"ם כדי שינצל מאיסורא דאורייתא: <small>הגה ואם רוצה יכול להפקירה לפני ג' בני אדם כדין שאר הפקר <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>ואפי' הכי אין שום אדם יכול <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>לזכות בה דודאי אין כוונתו רק <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>כדי להפקיע מעליו איסור שבת (טור) ודוקא בשבת <i data-commentator=\"Turei Zahav\" data-order=\"6\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"3\"></i>אבל ביום טוב <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>אין אדם <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"8\"></i>מצווה על שביתת בהמתו ביום טוב. (ב\"י סי' ש\"ה בשם שיבולי הלקט):</small>","m":["(י) אסור להשכיר וכו' - אפילו ביום ראשון ואפילו בהבלעה:","(יא) כדי שיעשה וכו' - צ\"ל שמא יעשה בה [הגר\"א וכן מוכח מהש\"ע גופא]:","(יב) על שביתת בהמתו - דכתיב למען ינוח שורך וחמורך וגו' ואע\"ג דהשכיר הבהמה לא\"י הא קי\"ל דשכירות לא קניא והו\"ל בהמתו של ישראל ומצווה על שביתתה וי\"א דלחומרא אמרינן דשכירות קניא וע\"כ אם ישראל שכר בהמה מא\"י מצווה על שביתתה ונכון להחמיר כיון דהוא איסור דאורייתא ואם שכרה מא\"י וחזר והשכירה לא\"י שרי ממה נפשך. ואם קנה בהמה מא\"י או מכר לא\"י במשיכה לחוד או בכסף לחוד הוי ספיקא דדינא ואזלינן לחומרא לענין שביתת בהמה [תו\"ש]:","(יג) אין הא\"י נאמן - ומירתת נמי לא מירתת לעשות בה מלאכה כיון שהוא ברשותו ע\"י שאלה או שכירות לא נתפס עליו כגנב עי\"ז משא\"כ ברישא כשמתנה שיחזירנה לו קודם שבת כבר כלה השאלה והשכירות קודם השבת ועי' לקמן סי' ש\"ה סכ\"ג [אחרונים]:","(יד) יפקירנה וכו' - וזהו דוקא בדיעבד שכבר התנה עמו ועיכבה בשבת אבל לכתחלה אסור להשכירה ע\"ד שכשיגיע יום השבת שיפקירנה ואפילו אם יפקירנה בפני שלשה שאין הכל יודעים מן ההפקר ואתי לידי חשדא שיאמרו בהמתו של ישראל עושה מלאכה בשבת ואף במכירה אין היתר אלא כשמוכר בהמתו לא\"י במכירה גמורה על כל ימי השבוע ולא כשמוכר לו על יום השבת לחוד מפני חשדא וכנ\"ל והב\"ח מתיר לכתחלה להשכיר ע\"ד שיפקירנה בפני ג' דכיון דג' ליודעים מיפרסמא מילתא ולא יבא לידי חשדא ובשעת הדחק אפשר שיש לסמוך על דבריו ובסוף הסימן נבאר אי\"ה:","(טו) בינו לבין עצמו - שאז אינו מצווה על שביתתה כיון שאינו שלו שכבר הפקירה ואע\"ג דהפקר בעינן שיהיה בפני שלשה זהו מדרבנן אבל מדאורייתא אפילו בינו לבין עצמו סגי והכא שכבר השכירה והתנה עמו שיחזירנה ועיכבה די בזה כדי להנצל מאיסורא דאורייתא ועיין בב\"י שיש פוסקים שסוברין דגם בכאן אף שהוא דיעבד בעינן דוקא תלתא וע\"כ טוב ליזהר בזה לכתחלה אם יש באפשרי ועכ\"פ יזהר להפקירה בפני אחד דרבים מגדולי הפוסקים סוברים דאף דאורייתא אינה הפקר עד שיפקירה עכ\"פ בפני אדם אחד ואפילו בפני אחד מאנשי ביתו די בזה:","(טז) בהמתו קנויה להא\"י - עיין במ\"א שדעתו דדוקא אם אומר לו בפניו בהמתי קנויה לך שאז מתכוין הא\"י לקנותה והיא נקנית לו באמירה זו כיון שהיא ברשותו וקניא ליה חצירו אבל אם אומר כן שלא בפניו לא קנאה הא\"י כלל. ואפילו אם זיכה לו ע\"י ישראל אחר ג\"כ לא מהני כמבואר בח\"מ סימן רמ\"ג סי\"ד וכן הסכים הפמ\"ג ושארי אחרונים כהמ\"א ופשוט דאפילו באומר בהמתי קנויה לך בעינן שיהיה לזה ג\"כ פסיקת דמים דאל\"ה אין זה מכירה כלל וכ\"כ בח\"א בכלל נ\"ח:","(יז) כדי שינצל וכו' - ר\"ל אבל לכתחלה אין לסמוך להשכיר ע\"ד שיפקיר כשיגיע יום השבת או שיקנהו אז להא\"י שההפקר וההקנאה אינן מפורסמין ויש כאן חשש מראית העין וכנ\"ל ועין בסוף הסימן:","(יח) דודאי אין כונתו - ר\"ל שבודאי לא היה בדעתו שישאר הפקר לעולם כ\"א ליום השבת בלבד כדי להפקיע מעליו איסור שבת ולאחר השבת יחזור לרשותו אבל ביום השבת גופא בודאי הוא הפקר גמור [וגם זה מקרי בשם הפקר וכדאיתא בגמרא דאפילו הפקר ליום אחד הוי הפקר] ואין צריך לחוש שמא יזכה בה אחר בשבת גופא שבודאי הא\"י לא יניחנו כ\"ז שהיא ת\"י למלאכתו:","(יט) אין אדם מצווה וכו' - דשביתת בהמתו ילפינן ממה דכתיב למען ינוח שורך וחמורך כמוך והאי קרא בשבת כתיב ואפ\"ה לא ישכירם אלא בהבלעה דלא יהיה שכר יו\"ט והנה המהרש\"ל חולק ע\"ז ודעתו דיו\"ט ושבת שוין הן בזה כמו בכל מלאכות ועין במג\"א שהאריך בזה ומביא דהב\"י בסימן תצ\"ה הביא דעות הראשונים בזה ומצדד שם לאיסור וע\"כ יש להחמיר ובביאור הגר\"א ג\"כ האריך בזה ומסיק דהעיקר כדעת מהרש\"ל הנ\"ל וגם לקמן בסימן תצ\"ה ס\"ג מפרש הגר\"א מה שכתוב שם בשו\"ע דאין מוציאין משא על הבהמה ביו\"ט הטעם הוא משום שביתת בהמתו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>ישראל שהשכיר שוורים לעכו\"ם לחרוש בהם וחורש בהם יש מתירים אם קבל עליו העכו\"ם אחריות מיתה וגזילה וגניבה ויוקרא וזולא וי\"א דכיון שאין העכו\"ם יכול למכר' אם ירצה נקראת <i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"9\"></i>בהמת ישראל <small>[ועיין למטה בסי' זה]:</small>","m":["(כ) אם קבל עליו וכו' - דעי\"ז הוי הבהמה כמו של א\"י ומותר לחרוש בה בשבת ואע\"פ שמחזירה בעין אם לא יקרה לה כלום מ\"מ השתא ברשת הא\"י קאי לגמרי כיון דגם ליוקרא וזולא ברשותו היא:","(כא) ועיין למטה וכו' - היינו דשני יש מתירין ועין במה שנכתוב שם:","(כב) בתחילה כשקנה וכו' - דנמצא דלא קנויה הבהמה לישראל כלל ביום השבת ואז אח\"כ מותרין אפילו לחלוק בשוה ואין בזה משום שכר שבת כמ\"ש סימן רמ\"ה ס\"ב וגם דאז אפילו אם אחריות שניהם בשוה כל ימות השבוע בין בחול ובין בשבת ומותר:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>אם ישראל ועכו\"ם שותפין בבהמה מות' לעשות בה עכו\"ם מלאכה בשבת <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i>ע\"י שיתנה <i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i>עם העכו\"ם בתחלה כשקנו אות' שיטול העכו\"ם בשבת וישראל ביום חול ואם לא התנו מתחלה אסור אע\"פ שהתנו אחר כך <i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>ואם ילוה אותה לעכו\"ם בהלואה גמורה שיהא רשות בידו להוציאה אם ירצה שלא ברשות ישראל ויזקוף הדמי' על העכו\"ם ואחריות השוורים על העכו\"ם מותר <i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i>ויש מתירים אפי' לא יהא רשות ביד העכו\"ם להוציאם על ידי שיזקוף הדמים על העכו\"ם במלוה ויחזור העכ\"ם ויעשם אפותיקי <small> (פירוש אפו תהא קאי כלומר לא יהיה לך פרעון אלא מזה) </small> לישראל או <i data-commentator=\"Magen Avraham\" data-order=\"14\"></i>יהרהנם <small>[פירוש משכון בלשון ישמעאל רהן) </small> אצלו ובלבד שלא יאמר לו מעכשיו <i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"15\"></i>ויש מתירים על ידי שיזהיר ישראל את העכו\"ם שלא יעשה בה מלאכ' בשבת ואם יעבור ויעשה תהיה אחריות עליו אפילו מהאונסים <i data-commentator=\"Magen Avraham\" data-order=\"15\"></i>ויכתוב כן <i data-commentator=\"Ba'er Hetev\" data-order=\"11\"></i>בערכאותיהם דהשתא אם בא לעשות בו מלאכה בשבת אינה בהמת ישראל שהרי קנא' העכו\"ם להתחייב באונסיה: <small>הגה וכל צדדי היתרים אלו הלכתא נינהו ויכול לעשות איזה מהן שירצה <i data-commentator=\"Magen Avraham\" data-order=\"16\"></i>ואפי' אם הבהמה כולה של <i data-commentator=\"Ba'er Hetev\" data-order=\"12\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"12\"></i>ישראל דינו כאלו היתה בשותפות העכו\"ם רק שיפרסם שעשה דרך היתר:</small>","m":["(כג) ואם לא התנו מתחלה - אלא לאחר שנשתתפו אמר לו טול אתה בשבת ואני כנגדו בחול אף אם נאמר שאין איסור בזה מחמת שביתת בהמתו כיון שיש לא\"י חלק בה וע\"כ של ישראל עושה מלאכה מ\"מ אסור דהא בכל זה הוא נוטל יום אחד כנגד יום השבת והוי שכר שבת שלא בהבלעה:","(כד) אף על גב שהתנו אח\"כ - מלשון זה משמע דכ\"ש דאם לא התנה כלל דאסור ובב\"י מצדד לומר דאם אף לאחר שנשתתפו לא התנה לומר טול אתה וכו'. אלא חולקין סתם השכר כל השבוע בשוה דשרי דהא נוטל שכר שבת בהבלעה ואיסור דשביתת בהמתו ס\"ל דאין כאן דהא הא\"י עושה בע\"כ בשבת מחמת חלקו שיש לו [ואך דעשה בזה איסור מתחלה כשנשתתף שהיה לו לחוש שיעשה בהבהמה מלאכה בשבת והו\"ל להתנות מתחלה טול אתה וכו' ע\"ש בב\"י]. אמנם מלשון השו\"ע משמע דלא רצה לסמוך ע\"ז למעשה. ודע דאפילו לפי דעת הב\"י הנ\"ל דאין בזה משום שביתת בהמתו אין להתיר לחלוק סתם אח\"כ אלא במקום הפסד גדול לפי דעת הרמ\"א לעיל ברמ\"ה ס\"א בהג\"ה ומשמע במ\"א לדיש לסמוך ע\"ז:","(כה) ויזקוף הדמים - היינו ששם אותם בדמים כפי מה שהיא עכשיו ואם תתיקר או תוזל יהיה הכל ברשותו ואפ\"ה התנה ג\"כ שיהא רשות בידו להוציאה דס\"ל כדעת היש אומרים הנ\"ל בס\"ד דבעינן שיהא הא\"י יכול למכרה:","(כו) להוציא על ידי וכו' במלוה - ומיירי ג\"כ שהלוה אותה לא\"י ושם אותה בדמים וכנ\"ל והדמים זקוף עליו במלוה אלא דבא להוסיף דאף דעי\"ז שעשה אותה הא\"י אפותיקי לישראל תו אין לו רשות למכרה אפ\"ה שרי:","(כז) יהרהנם אצלו - פי' אע\"פ שיניחם ביד הישראל למשכון שיהיה יוכל להפרע מהם כשלא יתן מעות עבורם ואח\"כ נוטל אותם הא\"י ועובד בהם אפ\"ה שרי דאכתי גוף הבהמה ברשות א\"י הוא:","(כח) ובלבד וכו' מעכשיו - היינו אפילו אם אמר לו אם לא אתן לך המעות לזמן פלוני יהיו שלך כיון דלא אמר לו מעכשיו יהיו שלך לא קנאם הישראל למפרע כשלא יפרענו הא\"י ואין לו עליהם עתה רק שעבוד בעלמא:","(כט) ע\"י שיזהיר וכו' - ואע\"פ שאין לו לא\"י רשות למכרה אפ\"ה שרי וסתם בזה כדעת המתירין לעיל בס\"ד דהכא נמי מיירי שקבלה עליו ברשותו לענין יוקרא וזולא:","(ל) ויכתוב כן - לפרסומי מילתא שלא יבוא לידי חשדא:","(לא) הלכתא נינהו - והיותר טוב שבכל ההתירים שיקנה אותם לו בחול במכירה גמורה ויתן לו אויפגא\"ב ע\"ז ויתר הדמים יזקוף עליו במלוה ויעשם אפותיקי לישראל שיהיה בטוח במעותיו והנכון שיעשה ענין המכירה בפני דייני העיר כדי שיעשה כד\"ת וגם שיפורסם הדבר שלא יהיה חשש מראית העין:","(לב) איזה מהן שירצה ואפילו וכו' - היינו דאף קבלת אחריות בלחוד שכתב המחבר לבסוף דבריו מהני גם בזה אף דאין לו רשות לא\"י למכרה כיון דעומדת ברשותו לענין יוקרא וזולא וסתם בזה כדעת היש מתירין בס\"ד ויותר טוב שיעשה מכירה גמורה וכנ\"ל בסל\"א כדי לצאת גם דעת המחמירין שם כי לדבריהם יש בזה חשש דאורייתא. ואם קשה לו לעשות כל אופני ההיתר האלו והוא שעת הדחק כגון מי שיש לו שדות וא\"א לו להשכיר באריסות לא\"י אם לא יתן לו גם שוורים לחרוש בהם ולא יוכל למנעו שלא לחרוש בו בשבת יש לסמוך ע\"ד הב\"ח הנ\"ל שמתיר ע\"י שיפקירם בפני ג' קודם השבת ויפורסם הדבר ולא יבוא לידי חשד וההפקר צריך להיות בלב שלם אבל בלא שעת הדחק אין לסמוך על ההפקר וכמ\"ש לעיל במ\"ב ס\"ק י\"ד וכן הסכים בד\"מ בהדיא:","(לג) דינו כאילו היתה וכו' - והנה כ\"ז הוא כשמשכירה או משאילה לו לעשות מלאכת עצמו אבל לעשות מלאכת ישראל בשבת אין היתר כלל אפילו אם מכרה לו הבהמה במכירה גמורה שהרי מ\"מ עושה הא\"י מלאכת ישראל בשבת בשבילו ולפ\"ז אם הסוסים הוא של ישראל וגם הא\"י הוא שכירו לכל המלאכות שיצטרך הישראל אין היתר במכירת הסוסים לו דהרי אסור לו להניח לעשות מלאכתו אא\"כ הוא מושכר לו רק למלאכה זו ליסע עם הסוסים להוליך לו סחורה בכל עת שיצטרך בשנה זו אז שרי להרמב\"ם כמ\"ש סי' רמ\"ד ס\"ה. ואפילו באופן זה אסור לומר לו שיסע בשבת אלא דאם הוא נוסע מעצמו א\"צ למנעו מזה [אחרונים]:","(לד) רק שיפרסם וכו' - עיין בבה\"ל שהבאנו דאין כדאי להתיר ע\"י כל ההתירים אלא בשעת הדחק ולאפוקי מאלו האנשים שמוכרים בכונה את שווריהן לא\"י כדי שיעשה בהן מלאכה בשבת והמלאכה נקראת על שם ישראל ואף דאין למחות ביד המקילין בזה שיש להם ע\"מ לסמוך מ\"מ כל בעל נפש יחוש לעצמו שלא לעשות זה כ\"א בשעת הדחק וע\"פ הוראת חכם. ישראל שיש לו סוס ובא המושל המכירו להשאילו או להשכירו והוא אינו יכול למאן נגדו מפני איבה ימכרנו לו בדבר מועט ואז יוכל המושל לעשות בו כרצונו ואם אח\"כ יחזור ויתן לו הסוס וגם השכירות מתנה בעלמא יהיב ליה [תשו' שבות יעקב ועיין בשע\"ת שהסכים ג\"כ עמו נגד היד אהרן]: "]}],"247":[{"s":"<b>דין עכו\"ם המביאים כתבים בשבת. ובו ו סעיפים:</b><br><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>שולח אדם <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>אגרת ביד עכו\"ם ואפי' בע\"ש עם חשיכה <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>והוא <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>שקוצץ לו דמים ובלבד שלא יאמר לו <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>שילך בשבת ואם לא קצב <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>אי לא קביע <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>בי דואר <small> (פי' איש ידוע שכל כתב אליו יובל והוא משלחם למי ששלוח אליו) </small> במתא אסור לשלוח אפילו מיום ראשון ואי קביע בי דואר במתא משלחין אפי' בע\"ש <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>והוא שיהא שהות ביום כדי שיוכל להגיע לבית <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>הסמוך <i data-commentator=\"Be'er HaGolah\" data-label=\"•\" data-order=\"3\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>לחומה: <small>הגה ויש מתירין אפי' לא קצץ <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>ואפילו לא קבוע בי דואר במתא אם משלחו <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>ביום ה' או קודם לכן (טור) ויש לסמוך עלייהו אם צריכין לכך:</small>","m":["(א) אגרת - ה\"ה בכל מלאכות כשנותן לו ואין שהות לגמרו קודם השבת בעינן דוקא שיקצוב לו דמים בעד מלאכתו דאז אדעתיה דנפשיה קעביד ולא בשביל ישראל וכדאיתא לקמן בסימן רנ\"ב ס\"ב אלא נקט אגרת לאשמועינן דאי לא קצץ ולא קביע בי דואר במתא אסור כדמסיק והטעם כמו שכתבנו לקמיה אבל שאר כלים וחפצים או מעות אם שולח ביד א\"י בע\"ש הדין כמו בכל מלאכות ולכך אפילו אם לא קצץ אם יש שהות ביום להגיע למקום מי שנשתלח לו מותר ולא חיישינן שמא לא ימצאנו בביתו ויצטרך לחפש אחריו בשבת:","(ב) עם חשיכה - היינו בעוד שהשמש זורח וגם צריך שיצא הא\"י מפתח ביתו של ישראל קודם השבת [רמב\"ם]:","(ג) ובלבד וכו' - ואם הא\"י אמר מעצמו שילך בשבת לית לן בה כיון שהישראל לא אמר לו זה וא\"י אדעתיה דנפשיה קעביד בשביל שכירותיה:","(ד) שילך בשבת - וה\"ה שלא יאמר לו ראה שתהא שם ביום א' או ביום ב' וכיוצא בזה וידוע שא\"א לו להיות שם אלא א\"כ ילך בשבת דזה הוי כאלו א\"ל לך בשבת [אחרונים]:","(ה) לא קביע בי דואר וכו' - היינו שאינו קבוע תמיד הבי דואר באותה העיר שנשתלח שם אלא הולך לפעמים למקום אחר אסור דשמא לא ימצאנו הא\"י ויצטרך לילך אחריו בשבת ולכך החמירו כולי האי וחששו לזה בעניננו דכיון שכתב ידו של ישראל נושא וניכר מעשה ישראל יאמרו בשבת נתן לו להוליך וא\"כ אם נכתב האגרת בכתב א\"י שרי להוליך אפילו בע\"ש ובלא קצץ כל שיכול להגיע שם מבעוד יום לבית ראשון הסמוך לחומה וכמו שהתרנו לעיל בשולח שאר כלים וחפצים ע\"י א\"י:","(ו) אסור לשלוח - כתב עו\"ש ונראה דכל זה מיירי כששולח ע\"י הא\"י ליד הבי דואר אבל כשאדם משלח אגרת על ידו לחבירו אין לחוש שמא לא ימצאנו בביתו שילך אחריו בשבת ושרי אפילו בע\"ש ובלא קצץ כל שיכול להגיע שם מבעוד יום וכן נוטה דעת מהר\"ר אברהם מפראג המובא בב\"ח וע\"ש שהאריך ומסיק להקל בזה ודעת הט\"ז ומ\"א דגם בשולח אגרת לחבירו ג\"כ יש חשש זה ובפירוש ר\"ח שיצא עתה לאור מוכח כהעו\"ש עיין שם ומיהו אם אמר לא\"י שילך לשם וימסור לבני ביתו של אותו האיש אם לא ימצאנו לכו\"ע שרי אפילו בע\"ש ובלא קצץ כל שיכול להגיע לבית ראשון הסמוך לחומה של העיר שהאיש שם:","(ז) אפילו מיום ראשון - ואם הוא דרך קרוב כגון מהלך יום אחד נראה דאף אם הוא משלחו ביום ב' וג' שרי שאף שלא ימצאנו בביתו יש לו שהות הרבה ללכת [מ\"א]:","(ח) ואי קביע בי דואר - היינו שהאיש הממונה ע\"ז קבוע שם תמיד ובכלל זה הוא מה שקורין עכשיו פאשט מייסטער שרגיל להיות במקומות גדולים שהוא עומד על המשמר בעתים ידועים לקבל כתבים ולשלחם להשייכים לכתבים ההם:","(ט) הסמוך לחומה - לעיר שנשתלח שם כלומר לבית ראשון מבפנים:","(י) ויש מתירין וכו' - טעמייהו דכיון שלא אמר לו ישראל בהדיא שילך בשבת אין לאסור כ\"א סמוך לשבת דנראה כשלוחו של ישראל לזה ואמירה לא\"י שבות אפילו אמר לו בע\"ש לעשות מלאכה בשבת אבל מופלג מן השבת קצץ לא מחזי כאומר לו עשה מלאכה בשבת ולפיכך אין לאסור כ\"א ביום ע\"ש [הרא\"ש]:","(יא) ואפילו לא קביע - ואפילו ידוע שלא יוכל להגיע לשם קודם שבת ג\"כ שרי לדעה זו דכיון שהוא מופלג מן השבת לא מחזי כשלוחו וכנ\"ל:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"4\"></i>ואם התנה עמו שיתן לו שכרו אף על פי שלא פירש כמה יתן לו דינו כקוצץ דסמכיה דעתיה דעכו\"ם ובדידיה קא טרח אבל בסתם <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>אע\"פ שיש בדעתו שיתן לו שכר אסור דלא סמכיה דעתיה ובישראל קא טרח:","m":["(יב) אע\"פ שיש בדעתו - ר\"ל לא מבעיא אם הא\"י מסתפק כלל אם יתנו לו שכר דאסור אלא אפילו אם הישראל מבין ממנו שמצפה לשכר מאתו או ממי שנשתלח לו אפ\"ה אסור כיון שהישראל לא הבטיחו עדיין:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"5\"></i>אם שכרו לימים דבר קצוב בכל יום בהליכתו ובחזרתו אלא שאינו מקפיד עמו מתי ילך אם הוא <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>בע\"ש אסור דכשיוצא בשבת נראה כאלו התנה עמו כך:","m":["(יג) אם שכרו לימים - ר\"ל דאף שהתרנו לעיל בקצץ אפילו בע\"ש היינו כשהוא קוצץ לו סך קצוב בעד פעולתו דאז אדעתיה דנפשיה עביד ולא מינכר כלל שהמלאכה הנעשית בשבת הוא בשליחות ישראל אבל כששכרו לימים שקוצב לו שכר בעד כל יום אף שאינו מקפיד עליו מתי ילך ואדעתיה דנפשיה עביד פעולתו גם בזה [ולפיכך עדיף מלא קצץ כלל ומותר בד' וה' אף לדעת המחבר] מ\"מ כששוכרו בע\"ש אסור דכיון שיוצא תיכף בשבת נראה כאלו התנה עמו כך ובשליחותו הולך מאחר שנתן לו שכר בעד היום:","(יד) בע\"ש - אבל ביום ה' מותר ולדעת הרמ\"א לעיל בהג\"ה אפילו לא קצץ כלל מותר ביום ה':","(טו) שהרי הא\"י מאליו וכו' - פי' דאין הישראל כופה אותו על כך אלא מעצמו הוא מתרצה להוליך האגרת ותלינן שמה שנתרצה הוא מפני הטובה שקיבל ממנו מכבר ואדעתיה דנפשיה קעביד:"]},{"s":"(אם) <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"6\"></i>העכו\"ם מוליך הכתב בחנם אפילו נתנה לו בערב שבת מותר <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>שהרי העכו\"ם מאליו הוא עוש' זה ואינו אלא להחזיק טובה לישראל מפני מה שקיבל ממנו והו\"ל כאלו קצץ: <small>הגה <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>ויש חולקים וסבירא להו דכל שעושה בחנם <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>אסור וטוב להחמיר אבל במקום שהעכו\"ם מתחיל עם הישראל לומר שילך לו בחנם ודאי דעתו על הטובה שקיבל ממנו ושרי (ב\"י):</small>","m":["(טז) וטוב להחמיר - הנה מלשון זה משמע דרק טוב לחוש לדעה זו וכן בט\"ז משמע דדעתו כדעה הראשונה אבל בד\"מ סימן רנ\"ב משמע דדעתו הוא כהיש חולקין וכן בלבוש ובא\"ר בסימן זה משמע דאסור בחנם וע\"כ מהנכון שיקצוב לו עכ\"פ איזה דבר מועט עבור זה והוי כקצץ כיון שקיבל עליו שיהיה זה שכרו וכ\"כ בח\"א:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"7\"></i>אם העכו\"ם הולך מעצמו למקום אחר וישראל נותן לו אגרת <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>מותר בכל <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>גוונא:","m":["(יז) הולך מעצמו - ואם יודע שמרבה הדרך בשבילו אסור [ב\"י]:","(יח) בכל גווני - היינו אפילו לא קצץ ליתן לו שכר אלא בסתמא דקיי\"ל בס\"א דאסור לשלוח על ידו כשאין קבוע בי דואר דחיישינן שמא לא ימצאנו בביתו וילך אחריו בשבת אפ\"ה שרינן כאן כיון שאין הא\"י הולך בשליחותו אלא שמעצמו הולך לשם בודאי אם לא ימצאנו לא יחפש אחריו ודוקא אם יש שהות להגיע שם מבעוד יום אבל אם אין שהות להגיע שם מבעוד יום אסור אף בזה דאף דהליכתו בשביל עצמו הוא מ\"מ מה שנושא המכתב הוא בשביל ישראל. ודע דליתן לו בשבת אסור לכו\"ע אפילו בהולך מעצמו ואפילו קצץ לו שכר מבעוד יום עבור זה וע\"כ אסור ליתן אגרת על הפאצט בשבת [ומע\"ש מותר דעל הפאצט הוי תמיד קצץ דאף אם אינו משלם כאן מ\"מ יצטרך לשלם מי שנשתלח לו] אפילו במקום שיש עירוב ואפילו ע\"י א\"י אסור דבר זה [ולא מהני קציצה על שבת גופא] אך במקום הפסד גדול יש להתיר בכה\"ג דהוי שבות דשבות במקום פסידא דמותר ושלא במקום הפסד יש להחמיר אפילו בע\"ש שלא ליתן לא\"י האגרת שהוא יתן אותו על הפאצט בשבת ואפילו בקצץ שהרי מייחד מלאכתו על שבת [ח\"א בכלל ג' ע\"ש]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"8\"></i>מי שיש לו שכיר עכו\"ם לשנה או יותר אסור לשלחו <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>ערב שבת באגרת: <small>הגה ומיהו אם לא שכרו רק בשליחות אגרת יש מתירין כמו שנתבאר לעיל סי' רמ\"ד ס\"ה:</small>","m":["(יט) אסור לשלחו - דמה שהוא שכירו לשנה לא נחשב כקציצה ודינו בכל הפרטים כמבואר לעיל בס\"א בלא קצץ אלא דבזה מקילינן דאין אסור אלא בע\"ש והטעם כמו שביארנו בבה\"ל:","(כ) כמו שנתבאר לעיל - היינו דעה הראשונה שם דס\"ל דזהו נחשב כקצץ ע\"ש הטעם. ומ\"מ אסור לומר לו שילך בשבת כנ\"ל בס\"א:\n"]}],"248":[{"s":"<b>דין המפליג בספינה וההולך בשיירא בשבת. ובו ד סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>מותר להפליג בספינה אפילו בערב שבת אם הולך <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>לדבר <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>מצוה <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>ופוסק עמו שישבות ואם אחר כך לא ישבות אין בכך כלום <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>אבל לדבר הרשות אין מפליגין בספינה בפחות <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>מג' <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>ימים קודם השבת: <small>הגה אבל <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>קודם <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>שלשה ימים שרי אפי' בספינה שמושכין אותו ע\"י בהמות <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>אפי' אין בגובה המים <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>י' טפחים [מהרי\"ק שורש מ\"ה] <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>ואפי' במקום שיצטרך <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>הישראל לעשות אח\"כ מלאכה בשבת להוליך הספינה [ריב\"ש סי' קנ\"ב] </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>ואם הוא דרך מועט כמו מצור לצידון שאין ביניהם כי אם מהלך יום אחד מות' להפליג בע\"ש בבקר <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>מפני שאפשר שיגיע <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>שם קודם השבת <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>ומקום שנהגו שלא להפליג בע\"ש כלל אפי' דרך מועט אין מפליגין:","m":["הנה קודם שנכנוס בביאור דברי השו\"ע נעתיק לשון הברייתא הנאמר בזה בגמרא דף י\"ט ת\"ר אין מפליגין בספינה פחות מג' ימים קודם לשבת בד\"א לדבר הרשות אבל לדבר מצוה שפיר דמי ופוסק עמו ע\"מ לשבות ואינו שובת דברי רבי רשב\"ג אומר אינו צריך ומצור לצידון [שהוא מהלך יום אחד] אפילו בע\"ש מותר ע\"כ לשון הברייתא. והנה הרבה טעמים נאמרו ע\"ז בפוסקים י\"א הטעם שמא יצטרך הישראל לעשות מלאכה בעצמו בשבת משום פיקוח נפש דמקום סכנה הוא או שיעשה הא\"י בעל הספינה עבורו מלאכה בקשירת הקלע ושאר חילולים או משום איסור תחומין כמבואר בב\"י באריכות והרי\"ף ס\"ל דאי משום חשש מלאכה או תחומין ודאי היה אסור אף קודם ג' ימים וגם לדבר מצוה לא היה מותר אלא דעיקר האיסור משום ביטול מצות עונג שבת דכל ג' ימים הראשונים יש להם צער מחמת נענוע הספינה שגופו משתבר וכדכתיב יחוגו וינועו כשכור וגם מחמת סרחון העולה מן הימים המלוחין ואין רוחו חוזרת לבוא עד אחר ג' ימים שהורגל בזה וכמ\"ש ס\"ב וי\"א דהטעם שאסרו להפליג בספינה הוא מפני שנראה כאלו צף ושט ע\"פ המים בשבת וזהו אסור לכו\"ע מפני גזירה שמא יעשה חבית של שייטין וכדלקמן בסימן של\"ט וקודם ג' ימים שרי דע\"י שהוצרך להפליג זמן הרבה קודם שבת אית ליה היכרא ולא יבוא לעשות חבית של שייטין ואותן הפוסקים הנ\"ל דס\"ל דהטעם הוא משום מלאכה או משום תחומין מה שחילק הברייתא לדידהו בין תוך ג' ימים לקודם ג' ימים הוא משום דשלשה ימים קודם שבת מקרי קמא שבתא וחל עליו להזהר שלא יבוא לידי חילול שבת אבל קודם ג' ימים דהם מקרי בתר שבת העבר עדיין לא חל עליו אזהרת שבת הבאה ושרי להפליג בהם ואז אף אם יצטרך אח\"כ לבוא לידי חילול שבת משום פיקוח נפש שרי. והנה המחבר אף שנמשך בס\"ב אחר הרי\"ף שהעתיק פירושו מ\"מ גם הוא ס\"ל כהפוסקים דקודם ג' ימים שרי אף במקום שיצטרך אח\"כ לבוא לידי חילול שבת ע\"י מלאכה וכמ\"ש ס\"ד [ועיין במה שכתבנו שם] אלא דס\"ל דאף אי לא היה בו שום חשש מלאכה ותחומין [כגון שהיא כולה של א\"י דכשנעשה בה מלאכה מסתמא אדעתיה דא\"י נעשה וגם היא במקום שעמוק יותר מעשרה טפחים דאין בזה משום איסור תחומין להרבה פוסקים וכדלקמן בסימן ת\"ד ע\"ש] אפ\"ה אסור משום ביטול עונג שבת לחוד. ועתה נבוא לבאר בעז\"ה את דברי השו\"ע:","(א) אפילו בע\"ש - היינו אף דבודאי לא יקיים עונג שבת עי\"ז כמ\"ש המחבר בס\"ב אפ\"ה מותר כיון דלצורך מצוה הוא וקי\"ל דעוסק במצוה פטור מן המצוה ולא מבעיא אם הספינה הולכת במקום שהמים עמוקים יותר מעשרה טפחים דמותר ואין לחוש ליציאת חוץ לתחום דקי\"ל אין תחומין למעלה מעשרה טפחים אלא אפילו יש מקומות שהמים מועטין פחות מעשרה טפחים ג\"כ מותר לצאת בע\"ש בספינה כיון שהוא לדבר מצוה [א\"ר]:","(ב) ופוסק עמו וכו' - כתב המ\"א דבשבת אסור להפליג אפילו לדבר מצוה דהא לא יוכל לפסוק עמו שישבות ולא ילך ויש שמצדדים דאפילו בשבת שרי לדבר מצוה ועיין בשע\"ת סוף סימן זה ובח\"א כלל ד':","(ג) שישבות - בין אם הוא מפליג מע\"ש בין מקודם כיון שהוא תוך ג' ימים הסמוך לשבת [ט\"ז]. בספר עו\"ש נסתפק אם א\"א לו לפסוק כגון שהא\"י אומר לו שלא ישבות וכה\"ג אי מעכב או לא והסכימו רוב האחרונים דהפסיקה הוא רק למצוה בעלמא ואינו מעכב:","(ד) פחות משלשה ימים - דהיינו ביום רביעי בשבת אסור [מ\"א בשם הרבה אחרונים] אבל הגר\"א הביא בשם הרבה ראשונים דהג' ימים נחשבין עם השבת גופא וביום רביעי מותר ועי\"ש שכתב שכן מוכח בתוספתא ובירושלמי:","(ה) קודם השבת - וה\"ה קודם יו\"ט דיו\"ט ושבת שוין וכן ביו\"ט שני אין מפליגין:","(ו) אפילו בספינה וכו' - ר\"ל דלא נימא דדמי להליכה בקרון דאסור ליסע בשבת אפילו אם ישב בהקרון קודם ג' ימים ועיין בס\"ב בהג\"ה דלפי מה שרגילין למשוך הספינות בבהמות בנהרות אפילו בתוך ג' ימים מותר להפליג אלא דנקט קודם ג' ימים משום שאר ספינות [הגר\"א]:","(ז) ואפילו אין בגובה וכו' - דהו\"א דאסור משום תחומין קמ\"ל דלא והטעם כיון שהתחיל קודם ג' ימים וכמש\"כ לקמיה:","(ח) ואפילו במקום וכו' - הטעם כמו שכתבנו למעלה דשלשה ימים קודם השבת שייכים לשבת הבא וחל עליו להזהר שלא יבוא לידי חילול שבת וכשיצא בתוך הזמן הזה הרי הוא כאלו מתנה לחלל עליו את השבת אבל קודם לזה שייכים לשבת שעבר וכיון שהפליג בהיתר אין לו להמנע מחמת שבת הבא שאז אם יארע לו סכנה ויצטרך לחללו משום פיקוח נפש אין כאן חילול ועיין לקמן בסקכ\"ה מה שנכתוב בזה:","(ט) לעשות אח\"כ וכו' - היינו דאין לו למנוע מחמת זה מלישב בספינה כיון שהוא קודם ג' ימים אבל מ\"מ כל מה שיכול לעשות שלא יצטרך בעצמו לחלל את השבת כגון ע\"י א\"י וכדומה פשיטא דמחויב לעשות כן:","(י) בבוקר - דאם ימשך שעה ושתים על היום אסור דלא יגיע לשם קודם השבת [ב\"י]:","(יא) מפני שאפשר וכו' - ר\"ל כשיש רוח טוב הולכין ביום אחד לכן שרי להלוך בע\"ש לפי שאפשר שיהיה רוח טוב:","(יב) אפילו בע\"ש - ואין צריך לפסוק עמו שישבות ולענין להפליג בשבת עיין בס\"ג:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>הא דאין מפליגין בספינה בפחות משלש' ימים קודם השבת הטעם משום עונג שבת שכל שלשה ימים הראשונים <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>יש להם צער <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>ובלבול <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>ודוקא למפליגים במים המלוחים אבל בנהרות אין שום צער למפליגים בהם ולפיכך מותר להפליג בהם אפילו בערב שבת <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>והוא שלא יהא ידוע לנו שאין בעומקם עשרה טפחים <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>אבל במקום שידוע לנו <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>שמקרקע <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>הספינ' לקרקע הנהר פחות מעשר' טפחים <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>אסור (לצאת חוץ <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>לתחום) משום איסור תחומין. <small>הגה וכן בספינה שיצטרך הישראל לבא לידי מלאכה בשבת אסור ליכנס בה שלשה ימים קודם השבת אפי' הם נהרות הנובעים והוא למעלה מעשרה (ריב\"ש סי' קנ\"ב מהרי\"ק) אבל אין איסור במה שהבהמות מושכות הספינה בשפת הנהר <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>ולא דמי <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>להליכה בקרון <i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>שאסור:</small>","m":["(יג) והוא שלא וכו' - דכיון דתחומין דרבנן הוא ואפילו תחומין די\"ב מיל קי\"ל דבימים ונהרות אין בהן איסור דאורייתא לד\"ה שאין דומין לדגלי מדבר לפיכך תלינן בספיקו להקל ואמרינן דעמוק עשרה טפחים מקרקע הספינה לקרקע המים ואין תחומין למעלה מעשרה:","(יד) שמקרקע הספינה - פי' אע\"פ שהמים עמוקים עשרה אם הספינה משוקעת במים שאין בין קרקע הספינה לקרקע המים י\"ט לא מבעיא אם הוא יושב בספינה למטה מיו\"ד נמצא מהלך למטה מיו\"ד אלא אפילו אם הוא יושב בספינה במקום גבוה שהוא למעלה מיו\"ד מקרקעית המים ג\"כ אסור כיון שהספינה רחבה ארבעה וניחא להילוך כעומד למטה דמיא ויש מתירין כשהוא יושב למעלה מיו\"ד טפחים ואין רגליו תלויות למטה מיו\"ד טפחים ויש לסמוך על דבריהם כשהוא צריך לכך:","(טו) אסור לצאת וכו' - היינו בכל הג' ימים שקודם שבת אם יודע שיזדמן לו שם בשבת מקום ההוא ויצטרך לעבור עליו על איסור תחומין אבל קודם לזה מותר וכמו שכתוב בס\"א בהג\"ה:","(טז) לידי מלאכה - אפילו מלאכה דרבנן [אחרונים]:","(יז) ליכנס בה שלשה ימים - הטעם כמו שכתבנו למעלה בסק\"ח:","(יח) אין איסור במה שהבהמות וכו' - ר\"ל דאם לא היה איסור אחר כגון בנהרות הנובעים ולמעלה מעשרה וגם לא יצטרך הישראל לעשות מלאכה שם אין לאסור ליסע בספינה היכא שהבהמות מושכות הספינה דיהיה דומה כאלו יושב בקרון והבהמה מושכת אותו דאסור לא אמרינן הכי דהתם הטעם שמא יחתוך זמורה להנהיגה אבל הכא הבהמות הולכות ברחוק ממנו וע\"כ מותר אפילו בתוך ג' ימים:"]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>היכא דמותר להפליג מערב שבת אם נכנס בספינה מערב שבת וקנה בה <i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i>שביתה אף על פי שמפלגת בשבת <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>מותר <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>והוא שלא יצא מהספינה מעת שקנה שביתה: <small>הגה ויש אומרים <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>דאפי' יצא מן הספינה שרי דמאחר שקנה בה שביתה מע\"ש מות' אח\"כ ליכנס בה בשבת ולהפליג. וי\"א <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>שעושין <i data-commentator=\"Ba'er Hetev\" data-order=\"11\"></i>קידוש בספינה ואח\"כ חוזרים לביתם ולנים שם ולמחר חוזרין לספינה ומפליגין כן נהגו בקצת מקומות ואין למחות (ר\"ן פ\"ק דשבת וריב\"ש סי' י\"ז קכ\"א קכ\"ב) ועיין לקמן סי' של\"ט ות\"ד:</small>","m":["(יט) היכא דמותר וכו' - פי' דהמחבר לא קאמר לעיל להתיר אפילו בנהרות הנובעים ולמעלה מעשרה אלא להפליג בע\"ש אבל בשבת לא וכאן אתי לאורויי דלפעמים אף בשבת מותר להפליג בהם:","(כ) שביתה - היינו שישב שם כל בין השמשות עד שתחשך:","(כא) והוא שלא יצא - דאל\"ה אסור ליכנס בה בשבת מפני שנראה כשט ע\"פ המים וזה אסור כמ\"ש סימן של\"ט:","(כב) דמאחר שקנה בה וכו' - היינו דעי\"ז הו\"ל הספינה כביתו ואינו נראה כשט כשנכנס בה בשבת ואפילו לדעה זו אינו מועיל הקנין שביתה אלא שיהיה מותר לכנוס בהספינה בשבת אבל כשמגיע אח\"כ ליבשה אסור לו לזוז מד' אמותיו כמ\"ש בסימן ת\"ד [ואם הגיעה הספינה לעיר המוקפת מחיצות עי\"ש בהג\"ה] אבל אם לא יצא מהספינה מעת שקנה שביתה מותר אח\"כ לילך במקום שיגיע ליבשה עד אלפים לכל רוח והני מילי כשהיתה הספינה לעולם למעלה מעשרה טפחים וכמבואר שם ובספינה גופא מהלך את כולה אפילו אם יצא מבערב לביתו אחר שקנה שביתה כיון ששבת באויר מחיצות מבעוד יום ואם לא קנה שביתה כלל מבע\"י עיין לקמן בסי' ת\"ה ס\"ז במ\"ב כי שם בארנו כל פרטי הדינים האלו:","(כג) שביתה מע\"ש - ואפילו אם חל יו\"ט ע\"ש שרי לקנות שביתה ואין בזה משום הכנה מיו\"ט לשבת [מ\"א] ואינו מועיל לזה הקנין שביתה שקנה מעיו\"ט ועיין בסימן תט\"ז באיזה אופן אין בו משום הכנה:","(כד) שעושין קידוש - גם לדעת זו בעינן שישב שם כל בין השמשות לקנין שביתה אלא שסוברין דלכתחלה נכון לעשות שם ג\"כ קידוש ולאכול מעט כדי לפרסם הדבר שקנו שם שביתה ולא יבואו לחשדם:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>היוצאים בשיירא במדבר והכל יודעים שהם צריכים <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i>לחלל <i data-commentator=\"Ba'er Hetev\" data-order=\"12\"></i>שבת כי מפני הסכנ' לא יוכלו לעכב במדבר בשבת לבדם ג' ימים קודם שבת אסורים לצאת <i data-commentator=\"Magen Avraham\" data-order=\"14\"></i>וביום ראשון ובשני ובשלישי <i data-commentator=\"Ba'er Hetev\" data-order=\"13\"></i> מותר לצאת ואם אח\"כ יארע לו סכנה ויצטרך לחלל שבת מפני פקוח נפש מותר ואין כאן חילול <i data-commentator=\"Ba'er Hetev\" data-order=\"14\"></i><i data-commentator=\"Magen Avraham\" data-order=\"15\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>והעולה לארץ ישראל אם נזדמנה לו שיירא אפילו בערב שבת כיון דדבר מצוה היא יכול לפרוש ופוסק עמהם לשבות ואם אחר שיהיו במדבר לא ירצו לשבות עמו <i data-commentator=\"Magen Avraham\" data-order=\"16\"></i>יכול <i data-commentator=\"Eshel Avraham\" data-label=\"ב\" data-order=\"2\"></i>ללכת עמהם חוץ לתחום מפני <i data-commentator=\"Ba'er Hetev\" data-order=\"15\"></i>פיקוח נפש <i data-commentator=\"Magen Avraham\" data-order=\"17\"></i>ואם נכנס לעיר אחת בשבת מהלך את כולה ואפי' הניחוהו מחוץ לעיר ורוצה ליכנס לעיר מותר דכיון <i data-commentator=\"Magen Avraham\" data-order=\"18\"></i>דלדבר מצוה נפק יש לו אלפים אמה לכל רוח: <small>הגה י\"א שכל מקום שאדם הולך <i data-commentator=\"Magen Avraham\" data-order=\"19\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"16\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"16\"></i>לסחורה או לראות פני חבירו <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>חשוב הכל דבר מצוה ואינו חשוב דבר הרשות רק כשהולך לטייל וע\"כ נהגו בקצת מקומות להקל בענין הפלגת הספינות <i data-commentator=\"Magen Avraham\" data-order=\"20\"></i>והליכת <i data-commentator=\"Ba'er Hetev\" data-order=\"17\"></i>שיירא תוך שלשה ימים כי חושבים הכל לדבר מצוה ואין למחות בידן הואיל ויש להם על מי שיסמוכו:</small>","m":["(כה) לחלל שבת - אפילו באיסור דרבנן [מ\"א בשם הריב\"ש]:","(כו) וביום ראשון ובשני ובשלישי - כבר נתבאר הטעם משום דהם נקראים על שם שבת העבר ואין צריך להזהר עתה שלא יבוא לידי חילול שבת הבא ובכנה\"ג כתב בשם הריב\"ל דכשיודע בודאי שיבוא לידי חילול שבת אסור אף בכה\"ג וכ\"כ הרדב\"ז ועפ\"ז סומכין עכשיו שמסכנים בעצמם קצת שלא לחלל שבת כדי שלא יהיה איסור למפרע על מה שיצא:","(כז) ואם אח\"כ יארע וכו' - ר\"ל כיון דממילא נסבב הדבר לבסוף ובאונס של פיקוח נפש אין כאן חילול. ופשוט דלכו\"ע אסור לו להבטיח לשיירא בעת שישתתף עמם שיסייעם באיזה עשיית מלאכה בשבת ואפילו מלאכה דרבנן אף שעי\"ז תתבטל הנסיעה שלו שלא ירצו להשתתף עמו ואפילו אם הוא דבר מצוה דהרי הוא מתנה בהדיא לחלל את השבת:","(כח) והעולה לארץ ישראל - י\"א דה\"ד כדי להתיישב בה וי\"א דאפילו ע\"מ להחזיר דלהלוך בה הילוך ד\"א נמי הוי מצוה ובפרט לפי מה שהקיל רמ\"א בסוף הסימן בהג\"ה ודאי דגם זה הוא בכלל דבר מצוה:","(כט) ופוסק עמהם לשבות - והפסיקה הוא לעיכובא ואם לא יתרצו בזה לא ילך עמם וכמו שבארתי בבה\"ל:","(ל) יכול ללכת וכו' - אם מתיירא להתעכב במדבר שמא יפגשו בו חיות רעות או יפגעו בו לסטים ויגזלו ממנו בהמתו ולא יוכל ללכת ברגליו ויסתכן או יקחו ממונו ולא יוכל להחיות את עצמו במדבר או שיקחו ממנו מלבושיו בזמן הקור כולם הוא בכלל ספק פיקוח נפש ומותר לילך עמהם:","(לא) חוץ לתחום - וה\"ה אפילו חוץ לי\"ב מיל נמי שרי עד שיגיע למקום שאין שם שוב חשש סכנת נפשות ויפרד מהם וישבות שם ויש לו משם אלפים לכל רוח [אחרונים]:","(לב) ואם נכנס וכו' - דכיון דבאונס יצא חוץ לתחום מפני פיקוח נפש וגם מתחלתו ברשות נפק ע\"כ לא הוי כשאר יצא חוץ לתחום דאין לו אלא ד\"א וכתב המ\"א דדוקא כשהלך לדבר מצוה גמורה ולא כשהלך לסחורה דאף דדעת ההג\"ה שגם זה מקרי צורך מצוה מ\"מ לענין שיהיה יכול להלוך בתוך כל העיר וכן במה שכתב המחבר ואפילו וכו' יש לו אלפים לכל רוח אין לסמוך ע\"ז כיון שהרבה פוסקים חולקין ע\"ז:","(לג) דכיון דלדבר מצוה וכו' - אבל אם יצא מתחלה לדבר הרשות אף שעתה היה מותר לו ללכת עמהם חוץ לתחום מפני פ\"נ מ\"מ כיון שעבר מתחלה על דעת חכמים במה שיצא תוך ג' ימים הרי הוא כשאר יוצא חוץ לתחום דאין לו אלא ד\"א ואם יצא קודם ג' ימים אפילו לדבר הרשות כיון דהשתא היה צריך לצאת מפני פיקוח נפש יש לו אלפים אמה לכל רוח כמ\"ש סימן ת\"ז [מ\"א]. עוד כתב דאם הלך תוך ג' ימים מפני שסבר שמותר לילך תוך ג' ימים הו\"ל שוגג ויש לו אלפים אמה לכל רוח וכ\"כ ש\"א:","(לד) לסחורה - אפילו יש לו מזונות והולך לסחורה להרוחה ולגבות מעות מא\"י שהוא חולה כל עוד שאינו גוסס לא מקרי פסידא ודאית [מ\"א] והא\"ר מיקל בזה דלא גרע מהולך לסחורה וע\"כ מותר להפליג עבור זה בתוך ג' ימים ועיין לקמן בסימן של\"ט במ\"א סקי\"ג ובמ\"ב שם:","(לה) והליכת שיירא - ודעת מ\"א בשם כמה פוסקים דבהליכת שיירא אין להקל:","(לו) ואין למחות וכו' - אבל במקום שלא נהגו להקל אין כדאי לכתחלה להקל דכמה פוסקים סוברים דבעינן מצוה גמורה:"]}],"249":[{"s":"<b>דינים השייכים לערב שבת. ובו ד סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>אין הולכין בע\"ש <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>יותר <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>מג' פרסאות כדי שיגיע לביתו בעוד היום גדול <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>ויוכל <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>להכין צרכי סעודה לשבת בין שהולך לבית אחרים בין שהולך לביתו <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>וה\"מ כשהוא ביישוב במקום שיוכל להכין צרכי שבת אבל אם במקום שהוא שם א\"א לו להכין צרכי שבת או שאינו מקום יישוב בטוח מותר לילך אפי' כמה פרסאות <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ואם שלח להודיעם שהוא הולך שם לשבת מותר לו לילך כמה פרסאות בכל גוונא:","m":["(א) יותר מג' פרסאות - מתחלת היום והוא קרוב לשליש היום כפי מהלך אדם בינוני י' פרסאות ביום ובנוסע בעגלה או רוכב על סוס דנוסע במהרה יוכל ליסע הרבה יותר מג' פרסאות עד שליש היום ומהב\"ח משמע להקל בנוסע בעגלה ליסע אפילו אחר חצות היום ובלבד שיעמוד לשבות בעוד היום גדול בכדי שיוכל להכין צרכי שבת:","(ב) לביתו - היינו למקום ששובת שם:","(ג) שהולך לביתו - ואף שהוא מכוין שבביתו יהיה לו יותר עונג שבת מ\"מ אסור שמא לא ידעו כלל מביאתו ולא הכינו בשבילו. ובמדינות אלו רוב בני אדם מכינים צרכי שבת בריוח ולכן אין נזהרין בזה כלל בין כשהולך לביתו או להתארח בבית אחרים [ממ\"א בשם אגודה] ובהרבה אחרונים ראיתי שכתבו דמ\"מ צריך ליזהר לכתחלה שלא ילך או יסע עד סמוך לערב מפני שכמה פעמים נכשלים עי\"ז ובאים לידי חילול שבת כי בעל אושפיזא או אפילו בביתו כשבא סמוך לשבת מוסיפין לבשל בשבילו ומחללין שבת וגם כמה פעמים יארע דלא יגיע למלון ולביתו מבעוד יום עד שחשכה ממש וכמה חילול שבת יש בהוצאה והכנסה ויציאה מחוץ לתחום ושביתת בהמתו ולכן כל זה ישים האדם ללבו וימהר לשבות אפילו בכפר ולא יסיתנו היצר לומר עוד היום גדול והדרך טוב אך אם אירע שהלך עד חשיכה והיה בבה\"ש בתוך תחום עיר מותר להלוך בתוכה כבסימן תי\"ו וצריך לירד מעגלה וסוס עיין סימן רס\"ו ושם יבואר אי\"ה:","(ד) וה\"מ כשהוא וכו' - ר\"ל במקום שכלו הג' פרסאות כ\"כ הלבוש ועיין בא\"ר:","(ה) שאינו וכו' - דעמידה בדרך אינו מקום בטוח דכל הדרכים בחזקת סכנה ולכן אפילו יש עמו צדה כדי צרכי שבת מותר לו ליסע משם עד שיבוא למקום בטוח:","(ו) כמה פרסאות - ומ\"מ יזהר שלא יתאחר לבוא עד סמוך לערב וכנ\"ל בסק\"ג:"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>אסור לקבוע בע\"ש סעודה ומשתה <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>שאינו רגיל בימי החול ואפילו הוא <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>סעודת <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>אירוסין מפני <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>כבוד השבת שיכנס לשבת כשהוא תאב לאכול וכל היום בכלל האיסור. <small>הגה <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>וסעודה שזמנה בע\"ש כגון ברית מילה או <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>פדיון הבן <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>מותר כנ\"ל וכן המנהג פשוט.</small> <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"3\"></i>ולאכול ולשתות בלי קביעות סעודה אפילו סעודה שרגיל בה בחול כל היום מותר להתחיל מן הדין אבל מצוה להמנע מלקבוע סעודה שנהוג בה בחול מט' שעות ולמעלה:","m":["(ז) אסור לקבוע - ואיתא בגמרא דהיתה משפחה בירושלים שקבעה סעודתא בע\"ש ונעקרה:","(ח) בע\"ש - וה\"ה בעיו\"ט דיו\"ט נמי מצוה לענגו ולכבדו (פמ\"ג):","(ט) סעודת אירוסין - פי' אם אירס קודם לכן אסור לעשות הסעודה בע\"ש דאף דסעודת אירוסין היא מצוה מ\"מ היה לו להקדימה אבל אם אירס בע\"ש מותר לעשות הסעודה דכיון דאירוסין שריא בע\"ש משום שלא יקדמנה /יקדמנו/ אחר ממילא שרי הסעודה לזה ג\"כ וחשובה כמו סעודת מילה ופדיון הבן שזמנה קבוע. וכן אם היו הנשואין בע\"ש מותר לעשות הסעודה ג\"כ ומ\"מ לכתחלה טוב ונכון אם אפשר לדחות הסעודה למחר או יום אחר אפילו באירס בע\"ש. ודע דכ\"ז בסעודת אירוסין אבל בסעודה שעושין בשידוכין שלנו לא הוי סעודת מצוה כ\"כ בפמ\"ג בסימן תמ\"ד ולפ\"ז אין לעשותה בע\"ש אפילו אם נגמר השידוך באותו יום ומה שנוהגין לאכול מיני מרקחת בשעת כתיבת התנאים לא מקרי סעודה:","(י) כבוד השבת - ויש שכתבו הטעם שמתוך טרדת הסעודה לא יתעסקו בצרכי שבת:","(יא) שיכנס לשבת וכו' - שאף שאוכלה בבוקר כיון שהוא מרבה בסעודתו שלא כרגילותו שוב לא יאכל בלילה לתיאבון:","(יב) ברית מילה - אפילו אם אינה בשמיני ללידתו כגון שהיה חולה בשמיני ונדחית מ\"מ מקרי זמנה קבוע דכל שעתא ושעתא זמניה הוא דאסור להניחו ערל אפילו יום אחד וכן בפדיון הבן אפילו עבר זמנו מ\"מ כיון שמן הדין אפילו אחר ל' יום כל שעתא ושעתא רמיא חיובא עליה לפדותו ממילא מותר לעשות ג\"כ הסעודה:","(יג) מותר - דהיא ג\"כ סעודת מצוה ואין לדחותה מפני סעודת שבת ומ\"מ לכתחלה מצוה להקדימה בשחרית משום כבוד שבת וכמו שמבואר בסימן תרצ\"ה ס\"ב לענין סעודת פורים ע\"ש ובדיעבד יכול לעשותה אפילו ממנחה ולמעלה:","(יד) ולאכול ולשתות וכו' - ואין בכלל זה אם הוא שותה כ\"כ הרבה מיני משקה עד שיהא שבע כי הוא בודאי מקלקל תאות המאכל והחוש יעיד ע\"ז ולפעמים יוכל להבטל ע\"י שכרותו מסעודת שבת לגמרי וע\"כ מצוה להמנע מזה עכ\"פ מט' שעות ולמעלה:","(טו) אפילו וכו' - היינו כמו ואפילו ור\"ל דלא מבעיא בלי קביעת סעודה כלל דזה ודאי מותר כל היום ואפילו מצוה להמנע ג\"כ ליכא ואפילו בקביעת סעודה כיון שאינו עושה סעודה רחבה רק כמו שרגיל בה בחול מותר כל היום מן הדין אבל מצוה להמנע וכו':","(טז) מלקבוע סעודה - ואם התחיל אינו מפסיק:","(יז) מט' שעות ולמעלה - היינו שעות זמניות והוא רביעית היום עד הלילה ומ\"מ נראה דבימות החורף בזמן שהימים קצרים מאד מצוה להמנע מלקבוע סעודה הרגילה אפילו קודם ט' שעות כל שהוא משער בנפשו שעי\"ז לא יהיה תאב לאכול בלילה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>דרך אנשי מעשה <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>להתענות בכל ערב שבת:","m":["(יח) להתענות - כדי שיהיו תאבים לאכול בלילה ועיין בב\"ח ומ\"א וש\"א שהסכימו דאין להתענות בע\"ש כדי שלא יכנס לשבת כשהוא מעונה אם לא שהוא איסטניס כ\"כ שאם יאכל ביום לא יוכל לאכול בלילה לתאבון אז מנהג טוב הוא אם אין מזיק לו התענית:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>אם קבל עליו להתענות בע\"ש צריך להתענות עד צאת הכוכבים <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>אם לא שפירש בשעת קבלת התענית עד שישלימו הצבור תפלתן: <small>הגה <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>ויש אומרים דלא ישלים אלא מיד <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>שיוצאים מבית הכנסת יאכל (טור ומרדכי ס\"פ בכל מערבין (בשם הר\"מ) והגהות מיי' פרק א' מהלכות תענית) ולכן בתעני' יחיד לא ישלים וטוב לפרש כן בשעת קבלת התענית <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>ובתעני' צבור ישלים <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"4\"></i>והכי נהוג (מהרי\"ל בתשו' סי' ל\"ג) <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i></small>ואם הוא <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"8\"></i>תענית חלום צריך להתענות עד צאת הכוכבים:","m":["(יט) צריך להתענות וכו' - וכמו אם קבל תענית סתם בשאר ימי השבוע דדינו הוא עד צאת הכוכבים דוקא ולא מהני במה שהתפלל תפלת ערבית מקודם וכדלקמן בסימן תקס\"ב ס\"א וב' ה\"ה הכא ואינו נחשב לאיסור במה שנכנס לשבת כשהוא מעונה אע\"ג דביום השבת גופא אסור להתענות:","(כ) אם לא שפירש - ואז מותר אפילו עוד היום גדול וכן אם התנה להתענות רק עד אחר מנחה גדולה מהני תנאו:","(כא) וי\"א דלא וכו' - האי י\"א ס\"ל דבין בתענית יחיד ובין בת\"צ כגון עשרה בטבת שחל בע\"ש לא יתענה רק עד שיצא מבהכ\"נ דאז כבר קבלו שבת בתפלה שמתפללים מפלג המנחה ואילך [הוא מי\"א שעות חסר רביע ואילך והשעות הן זמניות ועיין לקמן סימן רס\"א] ומקרי עי\"ז השלמת התענית מה שמתענה עד אחר קבלת שבת וה\"ה בעיו\"ט עד אחר קבלת יו\"ט [ובחול גם לי\"א לא מקרי השלמת התענית עד צאת הכוכבים] ומכריע הרמ\"א דבתענית יחיד דהיינו שיחיד גזר על עצמו תענית לסמוך על הי\"א דלא ישלים ומ\"מ לכתחלה טוב יותר שיפרש כן בשעת קבלת התענית ובדיעבד אין זה לעיכובא ובת\"צ חמירא מזה וצריך להשלים כדין ואפילו תנאי לא מהני דלאו בדידיה תליא מילתא וצבור שגזרו על עצמן תענית מחדש בשביל איזה ענין לא חמירא כ\"כ ומהני תנאי:","(כב) בתענית יחיד וכו' - תענית יחיד נקרא מי שקיבל על עצמו להתענות בע\"ש זה או שדרכו להתענות בכל ע\"ש או ערב ר\"ח שחל בע\"ש [היינו אותם אנשים שאין אומרים יו\"כ קטן ביום ה' שלפניו דאלו האומרים מתענין ג\"כ ביום ה'. א\"ר בסי' תי\"ח] או שמתענה יום שמת בו אביו ואמו או כ' סיון או שמתענה תעניתים המבוארים בסימן תק\"פ. כתב מ\"א דאם מתענה בכל ע\"ש והשלים פעם ראשון צריך לנהוג כן לעולם וה\"ה בכל הנ\"ל דמסתמא כ\"ז שלא התנה בפירוש שאין דעתו להשלים תמיד אמרינן דדעתו לנהוג כן לעולם. ולכתחלה יותר טוב שלא ישלים בפעם ראשון כשחל בע\"ש וכמו שכתב הרמ\"א וכדי שלא יצטרך להשלים תמיד ואם בתחלה כשהתחיל להתענות יום שמת בו אביו ואמו או ער\"ח ושאר תעניתים הנ\"ל חל בחול ובחול הלא משלימין וע\"כ יש פוסקים דס\"ל דאפילו כשיארע אח\"כ בע\"ש ג\"כ צריך להשלים עד צה\"כ דמסתמא דעתו להתנהג כן תמיד אם לא כשהתנה בפירוש שאין דעתו להתנהג כן לעולם ויש חולקין ע\"ז וס\"ל דמסתמא לא קבל על עצמו להשלים אף בע\"ש וע\"כ מי שמצטער יוכל לסמוך על המקילין ולאכול תיכף אחר יציאתו מבהכ\"נ אף שהיום גדול:","(כג) עד צאת הכוכבים - ואפילו הי\"א הנ\"ל מודו בזה שהרי אפילו בשבת עצמו יכול להתחיל ולהתענות ת\"ח וכדלקמן בסימן רפ\"ח וכ\"ש שישלים עד הלילה. והנה יש מהפוסקים שחולקין וסוברין דגם בתענית חלום די להמתין עד שיצא מבהכ\"נ ערבית דבזה מקרי השלמה אבל האחרונים הסכימו עם השו\"ע דאין להקל בזה דכיון שהוא מפני הסכנה לבטל ולבער חלום רע שמא לא יועל לבטלו אם לא ישלים עד הלילה:"]}],"250":[{"s":"<b>הכנת הסעודה לשבת. ובו ב סעיפים:</b><br><i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>ישכים בבוקר ביום הששי להכין צרכי שבת <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>ואפי' יש לו כמה עבדים לשמשו ישתדל <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>להכין <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"2\"></i>בעצמו שום דבר לצרכי שבת כדי לכבדו כי רב חסדא היה מחתך הירק דק דק ורבה ורב יוסף היו מבקעים עצים ורבי זירא היה מדליק האש ורב נחמן היה מתקן הבית ומכניס כלים הצריכים לשבת ומפנה כלי החול <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ומהם ילמוד כל אדם ולא יאמר לא אפגום כבודי כי זה הוא כבודו שמכבד השבת: <small>הגה <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>ויש להשחיז <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>הסכין בערב שבת כי זהו מכבוד השבת שמכין עצמו לאכילה (כל בו וב\"י בשם ספר חיי עולם):</small>","m":["(א) ישכים בבקר וכו' - דכתיב והיה ביום הששי והכינו את אשר יביאו וגומר הכנה דומיא דהבאה והבאת המן הלא היתה לאלתר בבקר דכתיב וילקטו אותו בבקר בבקר אף הכנה על שבת תהיה מיד בבקר והיינו מיד אחר ק\"ש ותפלה אך אם הוא רגיל ללמוד אחר התפלה איזה שעור קצוב או שלומד עם רבים אל יבטלנו וכמש\"כ בסוף סימן רנ\"א ואם דרך המקום ההוא למכור בבקר ולא ימצא לקנות אחר למודו לא יקבע למודו אלא אחר הקניה ואם רגילין למכור בבוקר השכם קודם התפלה ולא ימצא לקנות אחר התפלה יקנה ואח\"כ יתפלל אך יראה לקרות ק\"ש מקודם כיון שכבר הגיע זמנה ואין זה בכלל מה שאמרו אסור לעשות חפציו קודם שיתפלל שזו חפצי שמים היא:","(ב) ביום ששי - והוא יותר טוב משיקנה ביום ה' שהוא מינכר יותר שהוא לכבוד שבת אם לא בדבר שצריך הכנה רבה כמו בשר למלוח וכדומה יש לקנות ביום ה' אך אם הבשר שמוצא ביום ה' הוא כחוש ויש ספק שימצא ביום וי\"ו שומן וטוב ימתין על יום ו' [אחרונים] ומסתברא דבימים הקצרים כל מה שיכול להקדים ההכנה ביום ה' עדיף. וטוב שיאמר על כל דבר שקונה זהו לכבוד שבת כי הדבור הוא פועל הרבה בקדושה. ואע\"פ שהכין בהשכמה מצוה היא לכתחלה שיוסיף גם בין השמשות ורמז לדבר שנאמר והיה משנה [כלומר שיכינו שנית]. כתיב בתורה זכור את יום השבת לקדשו ודרשו ב\"ש שתהא זוכרו מאחד בשבת נזדמן לך חלק יפה תהא מתקנו לשבת ואמרו על שמאי הזקן שכל ימיו היה אוכל לכבוד שבת היה מוצא בהמה נאה אומר זו לשבת מצא אחרת נאה הימנה אוכל הראשונה ומניח השניה על שבת נמצא שהאכילה היא כדי שתשאר היפה של שבת אבל הלל הזקן מדה אחרת היתה בו שהיה אומר ברוך אדני יום יום יעמם לנו צרכנו. והסכימו הרבה פוסקים שגם הלל מודה שכדברי ב\"ש עדיפא טפי אלא שהיה בוטח בה' שבודאי יזמין לו לשבת מנה יפה משאר הימים וכדי לחזק מדת בטחונו היה נוהג כן אבל בשאר כל אדם שאין בטחונו חזק כ\"כ גם הוא מודה דכשמאי עדיפא טפי ופשיטא בדבר שאינו שכיח לקנות כשיזדמן לו דבר שלא יהיה נפסד אזי יניח אותו לשבת. מצוה לטעום מכל תבשיל בע\"ש כדי לתקנן יפה כהוגן ועיין בספר שלחן שלמה דהטעימה בשבת מכל מין בודאי היא מצוה ורמז לזה טועמיה חיים זכו:","(ג) להכין בעצמו וכו' - דמצות כבוד שבת מוטל על כל אדם וכדכתיב וקראת לשבת עונג לקדוש ה' מכובד ומצוה בו יותר מבשלוחו וה\"ה בכל המצות מצוה בו יותר מבשלוחו ועיין בבה\"ל. כתבו הספרים יהרהר בתשובה ויפשפש במעשיו בכל ע\"ש כי שבת מקרי כלה מלכתא וכאלו מקבל פני המלך ית\"ש ואין נאה לקבלו כשהוא לבוש בבלויי הסחבות של חלאת העונות ויש לפנות קורי עכביש שקורין שפי\"ן וועב\"ש מהבית בע\"ש [א\"ר] וכ\"ש שצריך לכבד הבית מהאבק והעפר מבעוד יום וזהו הכל בכלל כבוד שבת וידמה בדעתו כאלו יבוא אליו להתאכסן מלך ב\"ו כמה מכבד הבית ומציע המטות וכ\"ש שבת מלכתא [ח\"א]:","(ד) ומהם ילמד כל אדם - היינו אפילו החשוב יותר ובפרט בימים הקצרים ומכ\"ש כשרואה שכבר הוא סמוך לשבת שאז הוא מחוייב לעסוק בכל כחו וראיתי אנשי מעשה גדולי תורה שהיו מכבדין הבית בעצמן בימים הקצרים כדי שלא יתחלל שבת וזהו חיוב גמור על כל אדם דמאי שנא דאין לו מי שיכין או שהשליח אין לו פנאי:","(ה) כי זה הוא וכו' - ובספרי מסמיך לה אקרא וידעת כי שלום אהלך זו השחזת הסכין כי אם קהה הסכין יוכל לבוא לפעמים לידי קטטנה ח\"ו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>ירבה בבשר ויין ומגדנות כפי יכלתו:","m":["(ו) כפי יכלתו - עיין לעיל בסימן רמ\"ה שם מבואר כל הפרטים בזה:"]}]};